/* 300 original OSCECore educational cases; specialty metadata is hidden in play view. */
const CASES = [{"dx":"Rheumatoid arthritis","patient":"42F","chief":"Hand pain and stiffness","opening":"Both hands have become swollen and stiff over several months.","history":"Morning stiffness lasts more than an hour; symptoms improve with movement; fatigue.","exam":"Symmetric tender swollen MCP and PIP joints, sparing DIPs.","test":"RF and anti-CCP, ESR/CRP; hand radiographs for baseline.","mechanism":"Autoimmune inflammatory synovitis causes marginal erosions and prolonged morning stiffness.","differential":"Osteoarthritis; psoriatic arthritis","management":"Early rheumatology referral and DMARD, usually methotrexate after appropriate screening.","redflag":"Assess function and extra-articular manifestations.","difficulty":2,"system":"MSK","id":"O001"},{"dx":"Osteoarthritis","patient":"68F","chief":"Knee pain","opening":"Knee pain has slowly worsened, especially after long walks.","history":"Brief morning stiffness under 30 minutes, worse with activity; no systemic symptoms.","exam":"Bony enlargement and crepitus; no hot effusion.","test":"Usually clinical; weight-bearing radiograph if needed shows osteophytes and joint-space loss.","mechanism":"Cartilage degeneration and remodeling cause mechanical rather than inflammatory symptoms.","differential":"Rheumatoid arthritis; septic arthritis","management":"Exercise, strengthening, weight management, topical NSAIDs when appropriate.","redflag":"New hot swollen joint is not routine osteoarthritis.","difficulty":1,"system":"MSK","id":"O002"},{"dx":"Gout","patient":"55M","chief":"Sudden toe pain","opening":"He awoke overnight with intense pain at the base of his big toe.","history":"Rapid peak within hours; previous similar attacks; alcohol and diuretic exposure.","exam":"Erythematous exquisitely tender first MTP joint.","test":"Arthrocentesis if uncertain or septic joint possible: negatively birefringent needle-shaped urate crystals.","mechanism":"Monosodium urate crystal inflammation classically causes podagra.","differential":"Septic arthritis; calcium pyrophosphate deposition disease","management":"NSAID, colchicine or glucocorticoid based on contraindications; later evaluate urate-lowering indications.","redflag":"Crystals do not exclude coexisting joint infection.","difficulty":1,"system":"MSK","id":"O003"},{"dx":"Calcium pyrophosphate deposition disease","patient":"76F","chief":"Swollen knee","opening":"A knee became acutely painful and swollen after a recent hospitalization.","history":"Sudden monoarthritis; older age; prior episodic attacks.","exam":"Warm knee effusion and painful restricted movement.","test":"Joint aspiration shows rhomboid weakly positively birefringent CPP crystals; radiographic chondrocalcinosis may occur.","mechanism":"CPP crystal deposition produces pseudogout and may mimic septic arthritis.","differential":"Gout; septic arthritis","management":"Exclude infection; treat flare with anti-inflammatory therapy.","redflag":"Never diagnose crystal arthritis from imaging alone in a toxic patient.","difficulty":2,"system":"MSK","id":"O004"},{"dx":"Septic arthritis","patient":"61M","chief":"Hot swollen knee","opening":"He has severe knee pain and cannot bear weight since yesterday.","history":"Fever or immunosuppression may be present; recent bacteremia or skin breach.","exam":"Hot swollen joint with severe pain on passive motion.","test":"Urgent arthrocentesis for synovial WBC, Gram stain, culture and crystals; blood cultures.","mechanism":"Bacterial infection rapidly destroys cartilage; diagnosis requires urgent action.","differential":"Gout; cellulitis","management":"Immediate drainage and empiric IV antibiotics after cultures when feasible; orthopedic consultation.","redflag":"Time-critical joint-threatening emergency; normal temperature does not exclude it.","difficulty":1,"system":"MSK","id":"O005"},{"dx":"Ankylosing spondylitis","patient":"25M","chief":"Chronic back pain","opening":"Back stiffness has been troublesome for more than a year.","history":"Onset before 40; nocturnal pain and improvement with exercise; possible uveitis.","exam":"Reduced lumbar flexion and chest expansion; SI joint tenderness.","test":"Pelvic radiography or MRI sacroiliac joints; inflammatory markers may support.","mechanism":"Axial spondyloarthritis causes inflammatory sacroiliitis and eventual spinal restriction.","differential":"Mechanical back pain; lumbar disc herniation","management":"Physical therapy and NSAIDs; rheumatology assessment for biologics if persistent.","redflag":"Ask about uveitis, psoriasis and inflammatory bowel disease.","difficulty":2,"system":"MSK","id":"O006"},{"dx":"Psoriatic arthritis","patient":"39M","chief":"Finger swelling","opening":"A finger is swollen from base to tip and several joints ache.","history":"Known psoriasis or nail changes; morning stiffness; possible inflammatory back pain.","exam":"Dactylitis, nail pitting and asymmetric joint swelling.","test":"Clinical assessment and inflammatory markers; radiographs may show erosions and new bone formation.","mechanism":"Seronegative inflammatory arthritis associated with psoriasis, including enthesitis.","differential":"Rheumatoid arthritis; gout","management":"Rheumatology referral; NSAIDs for symptoms and DMARD or biologic according to severity.","redflag":"Check for active skin disease and eye involvement.","difficulty":2,"system":"MSK","id":"O007"},{"dx":"Reactive arthritis","patient":"28M","chief":"Swollen ankle","opening":"He developed painful swelling of an ankle a few weeks after an illness.","history":"Recent diarrhea or urethritis; may have conjunctivitis or enthesitis.","exam":"Asymmetric oligoarthritis of lower limbs, heel tenderness.","test":"Clinical diagnosis after assessing infection; STI testing when appropriate.","mechanism":"Postinfectious sterile inflammatory arthritis follows GI or genitourinary infection.","differential":"Septic arthritis; psoriatic arthritis","management":"Treat underlying infection when present; NSAIDs and follow-up for persistent disease.","redflag":"A hot monoarthritis still requires exclusion of septic arthritis.","difficulty":3,"system":"MSK","id":"O008"},{"dx":"Systemic lupus erythematosus","patient":"23F","chief":"Joint pain and rash","opening":"She reports fluctuating joint aches, fatigue and an intermittent facial rash.","history":"Photosensitivity, oral ulcers, pleuritic pain or urinary changes may coexist.","exam":"Nonerosive symmetric joint tenderness, malar eruption or oral ulcers.","test":"ANA screening with anti-dsDNA, complement, urinalysis and renal function as appropriate.","mechanism":"Multisystem autoantibody disease with immune-complex injury.","differential":"Rheumatoid arthritis; viral arthritis","management":"Assess organ involvement urgently; hydroxychloroquine often foundation under specialist care.","redflag":"Screen for nephritis even when symptoms seem musculoskeletal.","difficulty":2,"system":"MSK","id":"O009"},{"dx":"Polymyalgia rheumatica","patient":"72F","chief":"Shoulder and hip stiffness","opening":"Both shoulders are painful and very stiff on waking.","history":"Age over 50; morning stiffness, functional difficulty lifting arms; possible headache.","exam":"Painful active shoulder movement with largely preserved true muscle power.","test":"ESR and CRP usually elevated; assess alternate diagnoses.","mechanism":"Inflammation of periarticular structures produces proximal aching without primary myopathy.","differential":"Inflammatory myopathy; rheumatoid arthritis","management":"Low-dose glucocorticoids after evaluation with monitoring and follow-up.","redflag":"Ask about headache, jaw claudication and visual symptoms suggesting GCA.","difficulty":2,"system":"MSK","id":"O010"},{"dx":"Giant cell arteritis","patient":"74F","chief":"New headache","opening":"A new one-sided temporal headache has appeared with scalp tenderness.","history":"Jaw fatigue while chewing and transient blurred vision are concerning.","exam":"Temporal artery tenderness or reduced pulse; visual deficit may occur.","test":"ESR/CRP and urgent temporal artery ultrasound or biopsy depending on pathway.","mechanism":"Granulomatous large-vessel vasculitis can cause irreversible ischemic blindness.","differential":"Migraine; tension headache","management":"Start high-dose glucocorticoids immediately when strongly suspected; urgent specialist evaluation.","redflag":"Do not delay treatment for confirmatory testing when vision threatened.","difficulty":1,"system":"MSK","id":"O011"},{"dx":"Carpal tunnel syndrome","patient":"46F","chief":"Hand tingling","opening":"She wakes at night with numbness in several fingers.","history":"Thumb, index and middle finger tingling; shaking hand relieves symptoms.","exam":"Thenar weakness if severe; Phalen or Tinel may reproduce symptoms.","test":"Often clinical; nerve conduction studies if uncertain or surgery considered.","mechanism":"Median nerve compressed at the wrist causes sensory symptoms sparing little finger.","differential":"Cervical radiculopathy; ulnar neuropathy","management":"Night wrist splint, activity changes; consider injection or decompression for persistent cases.","redflag":"Progressive thenar atrophy merits prompt referral.","difficulty":1,"system":"MSK","id":"O012"},{"dx":"Cubital tunnel syndrome","patient":"37M","chief":"Numb fingers","opening":"His ring and little fingers tingle after long periods at a desk.","history":"Worse with elbow flexion or leaning on elbows.","exam":"Reduced ulnar sensation, interosseous weakness; elbow Tinel may reproduce symptoms.","test":"Clinical exam; EMG/nerve conduction when needed.","mechanism":"Ulnar nerve compression at elbow affects medial digits and intrinsic hand muscles.","differential":"Carpal tunnel syndrome; C8 radiculopathy","management":"Avoid prolonged elbow flexion and pressure; night elbow positioning; referral if weakness.","redflag":"Look for intrinsic muscle wasting or progressive weakness.","difficulty":2,"system":"MSK","id":"O013"},{"dx":"De Quervain tenosynovitis","patient":"32F","chief":"Wrist pain","opening":"Pain near the thumb side of the wrist worsens when lifting her infant.","history":"Repetitive thumb motion, gripping and lifting trigger symptoms.","exam":"Radial styloid tenderness, pain with Finkelstein maneuver.","test":"Clinical; imaging usually unnecessary.","mechanism":"Inflamed first dorsal extensor compartment tendons cause radial wrist pain.","differential":"Thumb CMC osteoarthritis; scaphoid fracture","management":"Thumb-spica splint, activity modification, topical NSAID or injection when appropriate.","redflag":"Trauma and snuffbox tenderness suggest a different evaluation.","difficulty":1,"system":"MSK","id":"O014"},{"dx":"Trigger finger","patient":"58F","chief":"Finger catching","opening":"A finger locks in flexion and painfully snaps straight.","history":"Morning stiffness and repetitive gripping; diabetes can predispose.","exam":"Palpable tender nodule at A1 pulley and reproducible catching.","test":"Clinical diagnosis.","mechanism":"Flexor tendon catches under a thickened A1 pulley.","differential":"Dupuytren contracture; inflammatory tenosynovitis","management":"Activity modification, splint, corticosteroid injection or surgical release if persistent.","redflag":"Differentiate fixed contracture from intermittent triggering.","difficulty":1,"system":"MSK","id":"O015"},{"dx":"Rotator cuff tear","patient":"63M","chief":"Shoulder weakness","opening":"He cannot raise an arm easily after grabbing a heavy falling object.","history":"Pain at night and weakness with overhead activity; may follow trauma.","exam":"Weakness on empty-can or external rotation testing; drop-arm may be positive.","test":"Ultrasound or MRI for suspected significant tear; radiograph for trauma.","mechanism":"Tendon disruption reduces active movement while passive motion is relatively preserved.","differential":"Adhesive capsulitis; impingement syndrome","management":"Analgesia and physical therapy; early orthopedic assessment for acute traumatic full-thickness tear.","redflag":"Acute marked weakness after trauma should not be dismissed as a strain.","difficulty":2,"system":"MSK","id":"O016"},{"dx":"Subacromial pain syndrome","patient":"45F","chief":"Pain lifting arm","opening":"Shoulder pain occurs when reaching up to a high shelf.","history":"Painful arc with overhead activity, no major trauma.","exam":"Painful arc and positive Hawkins-Kennedy/Neer maneuvers; power largely preserved.","test":"Clinical diagnosis; imaging if atypical or persistent.","mechanism":"Rotator cuff tendinopathy and subacromial structures are irritated by loading.","differential":"Rotator cuff tear; adhesive capsulitis","management":"Load modification, exercise therapy and analgesia; consider injection selectively.","redflag":"Special tests are supportive, not independently definitive.","difficulty":1,"system":"MSK","id":"O017"},{"dx":"Adhesive capsulitis","patient":"52F","chief":"Stiff shoulder","opening":"A shoulder has become progressively painful and difficult to move for months.","history":"Diabetes or thyroid disease; difficulty with dressing and grooming.","exam":"Both active and passive external rotation significantly restricted.","test":"Clinical; radiographs to exclude arthritis when appropriate.","mechanism":"Capsular inflammation and fibrosis cause global restriction of passive motion.","differential":"Rotator cuff tear; glenohumeral osteoarthritis","management":"Education, analgesia and graded physiotherapy; intra-articular steroid may help early pain.","redflag":"Passive movement limitation is the key discriminator.","difficulty":2,"system":"MSK","id":"O018"},{"dx":"Lateral epicondylitis","patient":"40M","chief":"Elbow pain","opening":"He has lateral elbow pain while using tools and carrying groceries.","history":"Pain with repetitive wrist extension and gripping.","exam":"Tender lateral epicondyle; pain on resisted wrist extension.","test":"Clinical diagnosis.","mechanism":"Extensor carpi radialis brevis tendinopathy at lateral elbow.","differential":"Radial tunnel syndrome; cervical radiculopathy","management":"Activity modification, progressive strengthening and short-term analgesia.","redflag":"Screen for neurologic symptoms or an alternative source of pain.","difficulty":1,"system":"MSK","id":"O019"},{"dx":"Medial epicondylitis","patient":"44F","chief":"Inner elbow pain","opening":"The inside of her elbow hurts after repeatedly swinging a golf club.","history":"Provoked by gripping and wrist flexion.","exam":"Medial epicondyle tenderness, pain with resisted wrist flexion or pronation.","test":"Clinical diagnosis.","mechanism":"Flexor-pronator tendon overuse causes medial epicondylar tendinopathy.","differential":"Ulnar neuropathy; UCL injury","management":"Activity modification and structured rehabilitation.","redflag":"Check ulnar nerve symptoms in ring and little fingers.","difficulty":2,"system":"MSK","id":"O020"},{"dx":"Anterior cruciate ligament tear","patient":"21F","chief":"Knee injury","opening":"She twisted her knee during soccer and heard a pop.","history":"Rapid swelling and knee instability after pivoting without contact.","exam":"Positive Lachman; effusion and limited motion.","test":"MRI if diagnosis uncertain or to evaluate associated injury; radiographs per trauma rules.","mechanism":"ACL rupture produces acute hemarthrosis and anterior instability.","differential":"Meniscal tear; MCL sprain","management":"Initial protection, ice, analgesia, rehab and sports-orthopedic follow-up.","redflag":"Assess neurovascular status and associated injuries.","difficulty":1,"system":"MSK","id":"O021"},{"dx":"Meniscal tear","patient":"31M","chief":"Knee locking","opening":"His knee hurts and sometimes catches after a twisting injury.","history":"Joint-line pain, mechanical catching or locking; swelling may be delayed.","exam":"Joint-line tenderness, painful McMurray or Thessaly.","test":"MRI for persistent mechanical symptoms or surgical planning.","mechanism":"Fibrocartilage injury causes mechanical knee symptoms.","differential":"ACL tear; osteoarthritis","management":"Activity modification, rehabilitation; urgent assessment for truly locked knee.","redflag":"True locked knee needs evaluation for displaced tear.","difficulty":2,"system":"MSK","id":"O022"},{"dx":"Medial collateral ligament sprain","patient":"19M","chief":"Inner knee pain","opening":"A sideways collision during sport caused pain along the inside of the knee.","history":"Valgus mechanism; usually no large immediate effusion.","exam":"Tender MCL; pain or laxity with valgus stress at 30 degrees.","test":"Clinical examination; radiograph for indicated trauma; MRI if combined injury suspected.","mechanism":"Valgus force injures medial ligamentous restraint.","differential":"ACL tear; medial meniscal tear","management":"Functional bracing and rehabilitation based on grade.","redflag":"Check for multi-ligament injury in major trauma.","difficulty":2,"system":"MSK","id":"O023"},{"dx":"Patellofemoral pain syndrome","patient":"22F","chief":"Front knee pain","opening":"Her kneecap region aches with stairs, squats and prolonged sitting.","history":"Gradual onset after increased running mileage; little swelling.","exam":"Pain on squat or step-down; patellar tracking and hip weakness may be seen.","test":"Clinical assessment, imaging only if atypical.","mechanism":"Patellofemoral load intolerance causes anterior knee pain.","differential":"Patellar tendinopathy; meniscal tear","management":"Hip and quadriceps strengthening with load management.","redflag":"Marked effusion, locking or instability suggests another cause.","difficulty":1,"system":"MSK","id":"O024"},{"dx":"Patellar tendinopathy","patient":"24M","chief":"Pain below kneecap","opening":"Pain began below the kneecap during basketball training.","history":"Jumping provokes pain; focal rather than diffuse anterior pain.","exam":"Point tenderness at inferior patellar pole; pain with resisted knee extension.","test":"Clinical; ultrasound if needed.","mechanism":"Repeated tendon loading produces jumper's knee.","differential":"Patellofemoral pain syndrome; Osgood-Schlatter disease","management":"Progressive tendon loading and modification of jumping activity.","redflag":"Acute loss of extension suggests rupture, not routine tendinopathy.","difficulty":2,"system":"MSK","id":"O025"},{"dx":"Achilles tendon rupture","patient":"43M","chief":"Sudden calf pain","opening":"He felt as though someone kicked the back of his ankle while playing tennis.","history":"Sudden pop and impaired push-off.","exam":"Positive Thompson test, palpable gap and weak plantarflexion.","test":"Often clinical; ultrasound if uncertain.","mechanism":"Tendon failure disrupts gastrocnemius-soleus force transmission.","differential":"Gastrocnemius strain; ankle sprain","management":"Immobilize in plantarflexion, protect weight bearing and urgent orthopedic evaluation.","redflag":"Document neurovascular status and avoid missing partial preserved plantarflexion.","difficulty":1,"system":"MSK","id":"O026"},{"dx":"Plantar fasciitis","patient":"49F","chief":"Heel pain","opening":"The first few steps after waking are especially painful.","history":"Improves after walking initially, returns with prolonged standing.","exam":"Tender medial calcaneal tubercle and plantar fascia stretch.","test":"Clinical; imaging if atypical.","mechanism":"Plantar fascia degenerative overload produces characteristic start-up heel pain.","differential":"Calcaneal stress fracture; tarsal tunnel syndrome","management":"Calf/plantar stretching, supportive footwear and load reduction.","redflag":"Bilateral burning or numbness suggests neuropathic symptoms.","difficulty":1,"system":"MSK","id":"O027"},{"dx":"Lateral ankle sprain","patient":"20F","chief":"Swollen ankle","opening":"She rolled her foot inward coming off a curb.","history":"Inversion injury; lateral pain and swelling; weight bearing variable.","exam":"ATFL tenderness and swelling; assess bony points and anterior drawer later.","test":"Apply Ottawa ankle rules to determine radiograph indication.","mechanism":"Inversion typically stretches the anterior talofibular ligament.","differential":"Distal fibular fracture; syndesmotic injury","management":"Protected mobilization, compression and rehabilitation when fracture excluded.","redflag":"Assess ability to bear weight and posterior malleolar tenderness.","difficulty":1,"system":"MSK","id":"O028"},{"dx":"Tibial stress fracture","patient":"27F","chief":"Shin pain","opening":"A new runner develops progressively worsening focal shin pain.","history":"Recently increased mileage; pain initially with running then with walking.","exam":"Focal bony tenderness rather than broad medial tibial tenderness.","test":"Radiograph may be negative early; MRI is sensitive if suspicion high.","mechanism":"Repetitive loading exceeds bone remodeling capacity.","differential":"Medial tibial stress syndrome; osteomyelitis","management":"Stop impact loading, evaluate bone health and grade risk.","redflag":"Pain at rest or high-risk sites warrants more urgent evaluation.","difficulty":2,"system":"MSK","id":"O029"},{"dx":"Osteomyelitis","patient":"59M","chief":"Persistent foot pain","opening":"A small plantar wound has become painful with increasing drainage.","history":"Diabetes, neuropathy or recent trauma; constitutional symptoms may be absent.","exam":"Deep ulcer, erythema, possible probe-to-bone finding.","test":"ESR/CRP, plain radiographs, MRI if needed; bone culture when feasible.","mechanism":"Contiguous infection can spread from ulcer to bone.","differential":"Cellulitis; Charcot arthropathy","management":"Wound and vascular assessment, culture-directed antibiotics and surgical consultation as indicated.","redflag":"Look for sepsis and limb ischemia.","difficulty":2,"system":"MSK","id":"O030"},{"dx":"Lumbar disc herniation","patient":"36M","chief":"Back pain shooting down leg","opening":"Back pain radiates below the knee after lifting a heavy box.","history":"Worse with coughing or sitting; dermatomal paresthesias.","exam":"Positive straight-leg raise, possible root-pattern weakness or reflex loss.","test":"Usually clinical first; MRI if severe/progressive deficit or persistent symptoms.","mechanism":"Herniated disc irritates or compresses nerve root, often L5 or S1.","differential":"Spinal stenosis; piriformis syndrome","management":"Activity as tolerated, analgesia and rehab; evaluate persistent neurologic deficit.","redflag":"Ask about bowel/bladder change and saddle anesthesia.","difficulty":1,"system":"MSK","id":"O031"},{"dx":"Lumbar spinal stenosis","patient":"71M","chief":"Leg pain while walking","opening":"Both legs feel heavy after walking several blocks.","history":"Relief by sitting or leaning forward on shopping cart; worse with extension.","exam":"Exam may be normal at rest; assess pulses and neurologic status.","test":"Lumbar MRI if clinically indicated.","mechanism":"Canal narrowing causes neurogenic claudication that improves in flexion.","differential":"Peripheral arterial disease; lumbar disc herniation","management":"Flexion-based exercise, analgesia, and specialist options if disabling.","redflag":"Compare with vascular claudication, which depends less on posture.","difficulty":2,"system":"MSK","id":"O032"},{"dx":"Cauda equina syndrome","patient":"47F","chief":"Back pain with urinary trouble","opening":"Severe back pain now accompanies difficulty starting urination.","history":"New urinary retention, saddle numbness and bilateral neurologic symptoms.","exam":"Reduced perineal sensation, possible weak anal contraction and leg deficits.","test":"Emergency MRI lumbar spine and bladder assessment.","mechanism":"Compression of lumbosacral roots threatens permanent bowel, bladder and motor function.","differential":"Uncomplicated radiculopathy; spinal cord compression","management":"Immediate emergency spine/neurosurgical consultation and decompression pathway.","redflag":"Do not rely on normal rectal tone to exclude the syndrome.","difficulty":1,"system":"MSK","id":"O033"},{"dx":"Cervical radiculopathy","patient":"48M","chief":"Neck pain and arm tingling","opening":"Pain shoots from his neck down one arm when turning his head.","history":"Dermatomal numbness, hand or arm weakness possible.","exam":"Spurling may reproduce pain; root-specific reflex or strength changes.","test":"Clinical; MRI for progressive deficit or persistent symptoms.","mechanism":"Cervical nerve-root irritation causes radiating pain in a dermatomal pattern.","differential":"Carpal tunnel syndrome; cervical myelopathy","management":"Conservative rehab and analgesia if stable; escalation for deficit.","redflag":"Ask about gait problems and bowel/bladder changes.","difficulty":2,"system":"MSK","id":"O034"},{"dx":"Cervical myelopathy","patient":"67M","chief":"Clumsy hands and falls","opening":"He has trouble buttoning shirts and has become unsteady.","history":"Progressive hand dexterity loss and gait imbalance.","exam":"Hyperreflexia, Hoffmann or Babinski signs, spastic gait.","test":"Urgent cervical spine MRI.","mechanism":"Cord compression causes upper motor neuron signs below lesion.","differential":"Cervical radiculopathy; peripheral neuropathy","management":"Prompt spine referral for decompression evaluation.","redflag":"Progressive myelopathy needs urgent evaluation.","difficulty":2,"system":"MSK","id":"O035"},{"dx":"Adolescent idiopathic scoliosis","patient":"14F","chief":"Uneven shoulders","opening":"Her parent noticed one shoulder and hip seem uneven.","history":"Often painless during a growth spurt; family history may occur.","exam":"Adams forward-bend rib hump and shoulder asymmetry.","test":"Standing spine radiographs and Cobb angle, growth potential assessment.","mechanism":"Three-dimensional spinal curvature develops during adolescence.","differential":"Leg-length discrepancy; postural asymmetry","management":"Observation, bracing or surgical referral based on curve and maturity.","redflag":"Pain, neurologic deficit or rapid progression raises concern for secondary causes.","difficulty":2,"system":"MSK","id":"O036"},{"dx":"Osteoporotic vertebral compression fracture","patient":"77F","chief":"Sudden back pain","opening":"Severe mid-back pain began after lifting a light box.","history":"Postmenopausal status, steroid use or prior low-impact fracture.","exam":"Focal vertebral tenderness and kyphosis; neurologic exam often normal.","test":"Spine radiograph; MRI if unclear acuity or neurologic concerns; DXA later.","mechanism":"Fragile trabecular bone fails with minimal trauma.","differential":"Malignancy; lumbar muscle strain","management":"Analgesia, mobilization, fracture risk treatment and osteoporosis prevention.","redflag":"Consider malignancy or infection with systemic red flags.","difficulty":2,"system":"MSK","id":"O037"},{"dx":"Fibromyalgia","patient":"34F","chief":"Widespread pain and fatigue","opening":"She describes widespread aches, exhaustion and poor sleep for months.","history":"Unrefreshing sleep, cognitive complaints and chronic diffuse pain.","exam":"Generalized tenderness without objective synovitis or focal weakness.","test":"Clinical diagnosis after targeted evaluation for mimics; avoid indiscriminate tests.","mechanism":"Central pain processing amplification causes multisite symptoms.","differential":"Hypothyroidism; inflammatory arthritis","management":"Education, exercise-based pacing, sleep and psychological approaches; selected medications.","redflag":"Do not attribute objective inflammatory or neurologic signs to fibromyalgia.","difficulty":3,"system":"MSK","id":"O038"},{"dx":"Hip fracture","patient":"83F","chief":"Hip pain after a fall","opening":"She cannot stand after falling onto her side at home.","history":"Low-energy fall, osteoporosis risk, immediate groin pain.","exam":"Shortened externally rotated leg with painful hip motion.","test":"Urgent AP pelvis and lateral hip radiographs; MRI if x-ray negative with high suspicion.","mechanism":"Proximal femur fragility fracture impairs weight bearing.","differential":"Hip contusion; pelvic fracture","management":"Analgesia, neurovascular assessment and urgent orthopedic care.","redflag":"Avoid forcing weight bearing when fracture suspected.","difficulty":1,"system":"MSK","id":"O039"},{"dx":"Femoral head osteonecrosis","patient":"38M","chief":"Groin pain","opening":"Deep groin pain has worsened over several months.","history":"Prior steroid exposure or heavy alcohol use; pain on weight bearing.","exam":"Painful reduced internal hip rotation, possible antalgic gait.","test":"MRI detects early avascular necrosis even with normal x-ray.","mechanism":"Disrupted femoral head blood supply leads to subchondral collapse.","differential":"Hip osteoarthritis; femoroacetabular impingement","management":"Reduce modifiable risks and refer early for hip preservation options.","redflag":"Delayed diagnosis can result in irreversible femoral head collapse.","difficulty":3,"system":"MSK","id":"O040"},{"dx":"ST-elevation myocardial infarction","patient":"58M","chief":"Chest pressure","opening":"He has crushing central chest pressure and is sweating.","history":"Pain lasts over 30 minutes with nausea and arm radiation; cardiac risk factors.","exam":"Diaphoretic, possibly hypotensive; exam may be otherwise nonspecific.","test":"Immediate ECG shows territorial ST elevation; serial troponin and monitoring.","mechanism":"Acute coronary artery occlusion causes transmural ischemia.","differential":"NSTEMI; aortic dissection","management":"Activate emergent reperfusion/PCI pathway, give aspirin if appropriate and monitor.","redflag":"Do not delay reperfusion for troponin; evaluate dissection if suggestive.","difficulty":1,"system":"Cardio","id":"O041"},{"dx":"Non-ST-elevation myocardial infarction","patient":"64F","chief":"Chest discomfort","opening":"She has persistent pressure with exertion and now at rest.","history":"Diabetes and nausea or dyspnea; symptoms not reliably relieved by rest.","exam":"May have normal examination or signs of heart failure.","test":"Serial troponin rise/fall with ischemic symptoms; ECG may show ST depression or T inversion.","mechanism":"Myocardial necrosis from ischemia without persistent ST-elevation pattern.","differential":"Unstable angina; demand ischemia","management":"Antiplatelet and antithrombotic ACS pathway, monitoring and risk-guided angiography.","redflag":"A normal initial ECG does not exclude ACS.","difficulty":2,"system":"Cardio","id":"O042"},{"dx":"Unstable angina","patient":"61M","chief":"Chest pain at rest","opening":"Previously predictable exertional chest pain now occurs at rest.","history":"Episodes are more frequent or prolonged than baseline.","exam":"Exam may be normal between episodes.","test":"Serial troponins without myocardial injury; ischemic ECG changes may occur.","mechanism":"Acute coronary plaque instability causes ischemia without detectable necrosis.","differential":"NSTEMI; stable angina","management":"Urgent ACS assessment, serial ECG/troponin and risk-based management.","redflag":"Do not label as stable angina because troponin is initially negative.","difficulty":2,"system":"Cardio","id":"O043"},{"dx":"Stable angina","patient":"57M","chief":"Pain with stairs","opening":"Predictable pressure in the chest occurs after climbing two flights.","history":"Disappears within minutes of rest; recurring exertional threshold.","exam":"Typically normal examination at rest.","test":"Risk assessment and functional testing or coronary CT based on clinical pathway.","mechanism":"Fixed flow-limiting coronary atherosclerosis creates demand ischemia.","differential":"GERD; unstable angina","management":"Risk-factor modification, antianginal therapy and ischemic evaluation.","redflag":"New pain at rest changes risk category.","difficulty":1,"system":"Cardio","id":"O044"},{"dx":"Aortic stenosis","patient":"79M","chief":"Exertional dizziness","opening":"He gets winded and nearly faints walking uphill.","history":"Exertional syncope, chest discomfort and reduced exercise tolerance.","exam":"Harsh crescendo-decrescendo systolic murmur at RUSB radiating to carotids; delayed pulse.","test":"Transthoracic echo measures valve area and gradients.","mechanism":"Calcific outflow obstruction creates pressure overload and reduced exertional reserve.","differential":"Hypertrophic cardiomyopathy; pulmonary hypertension","management":"Cardiology evaluation for valve intervention if severe and symptomatic.","redflag":"Symptomatic severe stenosis carries high risk.","difficulty":1,"system":"Cardio","id":"O045"},{"dx":"Mitral regurgitation","patient":"66F","chief":"Breathlessness","opening":"Progressive breathlessness and fatigue have developed.","history":"Orthopnea or palpitations; prior mitral prolapse or ischemic disease.","exam":"Holosystolic apical murmur radiating to axilla; displaced apex if chronic.","test":"Transthoracic echocardiogram for severity, ventricular function and mechanism.","mechanism":"Backflow from LV to LA causes volume overload.","differential":"Aortic stenosis; tricuspid regurgitation","management":"Treat congestion when present; cardiology/valve intervention assessment.","redflag":"Acute severe regurgitation with pulmonary edema is an emergency.","difficulty":2,"system":"Cardio","id":"O046"},{"dx":"Mitral stenosis","patient":"38F","chief":"Shortness of breath","opening":"She notices breathlessness and intermittent palpitations.","history":"Remote rheumatic fever or migration from endemic region; possible hemoptysis.","exam":"Loud S1, opening snap and diastolic rumble at apex.","test":"Echocardiogram evaluates valve area and pulmonary pressure.","mechanism":"Rheumatic commissural fusion obstructs LA emptying and predisposes to AF.","differential":"Mitral regurgitation; atrial septal defect","management":"Rate control if tachycardic, anticoagulation when indicated and valve assessment.","redflag":"Pregnancy and AF may precipitate decompensation.","difficulty":2,"system":"Cardio","id":"O047"},{"dx":"Aortic regurgitation","patient":"49M","chief":"Pounding heartbeat","opening":"He feels bounding pulses and breathlessness during exertion.","history":"May have chronic valve disease or connective tissue disorder.","exam":"Early diastolic decrescendo murmur along left sternal border, wide pulse pressure.","test":"Echocardiogram to quantify regurgitation and LV size.","mechanism":"Diastolic backflow from aorta loads LV with excess volume.","differential":"Mitral regurgitation; patent ductus arteriosus","management":"Monitor LV function, manage afterload when indicated and consider valve surgery.","redflag":"Sudden regurgitation from dissection or infection is critical.","difficulty":2,"system":"Cardio","id":"O048"},{"dx":"Hypertrophic obstructive cardiomyopathy","patient":"21M","chief":"Fainting during exercise","opening":"A student athlete briefly faints during intense practice.","history":"Family history of sudden death or exertional palpitations.","exam":"Harsh systolic murmur increases with Valsalva or standing.","test":"Echocardiogram shows asymmetric hypertrophy and possible LVOT obstruction; ECG.","mechanism":"Sarcomeric hypertrophy and dynamic obstruction increase risk for arrhythmia.","differential":"Aortic stenosis; vasovagal syncope","management":"Avoid competitive exertion until evaluated; specialist risk stratification and therapy.","redflag":"Exertional syncope is a red flag for cardiac disease.","difficulty":1,"system":"Cardio","id":"O049"},{"dx":"Dilated cardiomyopathy","patient":"47M","chief":"Progressive exercise intolerance","opening":"He notices fatigue, dyspnea and ankle swelling.","history":"Alcohol exposure, viral illness, chemotherapy or familial disease possible.","exam":"Displaced apex, S3 and signs of volume overload.","test":"Echo shows dilated LV with reduced ejection fraction; evaluate cause.","mechanism":"Myocyte dysfunction and remodeling produce systolic failure.","differential":"Valvular cardiomyopathy; HFpEF","management":"Treat with guideline-directed heart failure therapy and address etiology.","redflag":"Consider arrhythmia and thromboembolic risk.","difficulty":2,"system":"Cardio","id":"O050"},{"dx":"Heart failure with reduced ejection fraction","patient":"70M","chief":"Shortness of breath and edema","opening":"He needs extra pillows and has new ankle swelling.","history":"Prior MI and weight gain; orthopnea or paroxysmal nocturnal dyspnea.","exam":"JVD, crackles, peripheral edema and S3 may occur.","test":"BNP/NT-proBNP, ECG, chest radiograph and echo showing reduced EF.","mechanism":"Impaired ventricular contractility elevates filling pressures and causes congestion.","differential":"COPD exacerbation; renal failure","management":"Diuresis if congested and initiate/optimize evidence-based HFrEF medications when stable.","redflag":"Assess oxygenation, perfusion and precipitating cause.","difficulty":1,"system":"Cardio","id":"O051"},{"dx":"Heart failure with preserved ejection fraction","patient":"76F","chief":"Breathlessness and leg swelling","opening":"A patient with hypertension becomes breathless with routine activity.","history":"Obesity, diabetes and longstanding hypertension; orthopnea possible.","exam":"Congestion, S4; often elevated blood pressure.","test":"Echo shows preserved EF with evidence of increased filling pressures; natriuretic peptides.","mechanism":"Impaired relaxation and ventricular stiffness elevate filling pressures despite preserved EF.","differential":"HFrEF; pulmonary disease","management":"Decongest, manage blood pressure/comorbidities and consider SGLT2 inhibitor when appropriate.","redflag":"Preserved EF does not exclude heart failure.","difficulty":2,"system":"Cardio","id":"O052"},{"dx":"Atrial fibrillation","patient":"73F","chief":"Irregular heartbeat","opening":"Her pulse has felt irregular for the last two days.","history":"Palpitations, fatigue or stroke risk factors; some patients asymptomatic.","exam":"Irregularly irregular rhythm without distinct atrial activity.","test":"ECG shows irregular R-R intervals and absent organized P waves.","mechanism":"Chaotic atrial activation loses organized contraction and increases embolic stroke risk.","differential":"Atrial flutter; frequent ectopy","management":"Assess stability; rate/rhythm strategy and anticoagulation using stroke-risk assessment.","redflag":"Unstable tachyarrhythmia needs synchronized cardioversion.","difficulty":1,"system":"Cardio","id":"O053"},{"dx":"Atrial flutter","patient":"65M","chief":"Fast heartbeat","opening":"A rapid regular heartbeat began earlier today.","history":"History of structural heart disease; may have exertional dyspnea.","exam":"Regular or variably irregular tachycardia near 150 bpm with 2:1 conduction.","test":"ECG reveals sawtooth flutter waves, often best inferior leads.","mechanism":"Macroreentrant right atrial circuit produces rapid atrial activity.","differential":"Atrial fibrillation; AVNRT","management":"Stability assessment, rate control, anticoagulation evaluation and consider ablation.","redflag":"2:1 flutter can resemble other narrow-complex tachycardias.","difficulty":2,"system":"Cardio","id":"O054"},{"dx":"AV nodal reentrant tachycardia","patient":"26F","chief":"Sudden palpitations","opening":"Her heart suddenly races, then abruptly returns to normal.","history":"Episodes start and stop instantly; may terminate with vagal maneuver.","exam":"Regular rapid pulse; otherwise normal exam between episodes.","test":"ECG during episode shows regular narrow-complex tachycardia; often hidden P waves.","mechanism":"Reentry involving dual AV nodal pathways causes paroxysmal SVT.","differential":"Atrial flutter; sinus tachycardia","management":"If stable, vagal maneuvers then adenosine when appropriate; ablation for recurrent symptoms.","redflag":"Assess for preexcited or irregular wide-complex rhythms before AV-nodal blockers.","difficulty":1,"system":"Cardio","id":"O055"},{"dx":"Ventricular tachycardia","patient":"69M","chief":"Palpitations and faintness","opening":"He develops sudden pounding heartbeat with lightheadedness.","history":"History of MI, cardiomyopathy or prior ventricular arrhythmia.","exam":"Rapid pulse, hypotension may occur.","test":"ECG shows broad-complex tachycardia, often with AV dissociation.","mechanism":"Ventricular reentry/scar can cause hemodynamic collapse.","differential":"SVT with aberrancy; hyperkalemia","management":"If unstable perform synchronized cardioversion; pulseless VT follows ACLS defibrillation.","redflag":"Treat undifferentiated wide-complex tachycardia as VT until proven otherwise.","difficulty":1,"system":"Cardio","id":"O056"},{"dx":"Complete heart block","patient":"78M","chief":"Slow pulse and dizziness","opening":"He feels faint and has a very slow pulse.","history":"Medication exposure, ischemia or degenerative conduction disease.","exam":"Marked bradycardia, potentially cannon A waves.","test":"ECG shows AV dissociation with independent P waves and QRS complexes.","mechanism":"No atrial impulses conduct to ventricles, leaving escape rhythm.","differential":"Sinus bradycardia; second-degree AV block","management":"Assess instability, pacing support and reversible causes; permanent pacemaker often indicated.","redflag":"Hypotension or syncope indicates urgent treatment.","difficulty":1,"system":"Cardio","id":"O057"},{"dx":"Wolff-Parkinson-White pattern with tachycardia","patient":"19M","chief":"Episodes of racing heart","opening":"He gets sudden episodes of rapid palpitations.","history":"Young onset, possible syncope.","exam":"Exam may be normal between episodes.","test":"ECG in sinus rhythm shows short PR, delta wave and wide QRS.","mechanism":"Accessory pathway bypasses AV node, permitting preexcitation and reentry.","differential":"AVNRT; atrial flutter","management":"EP referral for ablation; rhythm-specific acute management.","redflag":"In preexcited AF, avoid AV-nodal blocking drugs such as diltiazem.","difficulty":3,"system":"Cardio","id":"O058"},{"dx":"Congenital long QT syndrome","patient":"18F","chief":"Unexplained fainting","opening":"She faints during emotional stress and swimming.","history":"Family history of sudden death or congenital deafness in some variants.","exam":"Usually normal between episodes.","test":"ECG QTc prolonged; review medications and electrolytes; family evaluation.","mechanism":"Abnormal repolarization predisposes to torsades de pointes.","differential":"Vasovagal syncope; epilepsy","management":"Avoid QT-prolonging drugs; specialist assessment and beta blocker in appropriate cases.","redflag":"Sudden unexplained exertional syncope demands urgent cardiac evaluation.","difficulty":2,"system":"Cardio","id":"O059"},{"dx":"Acute pericarditis","patient":"29M","chief":"Sharp chest pain","opening":"Sharp chest pain is worse lying flat and improves while leaning forward.","history":"Recent viral illness and pleuritic quality.","exam":"Pericardial friction rub may be heard.","test":"ECG diffuse ST elevation and PR depression; echo for effusion; troponin.","mechanism":"Inflamed pericardial layers cause positional pleuritic pain.","differential":"STEMI; pulmonary embolism","management":"NSAID plus colchicine when appropriate; assess high-risk features.","redflag":"Tamponade physiology or myopericarditis changes urgency.","difficulty":1,"system":"Cardio","id":"O060"},{"dx":"Cardiac tamponade","patient":"62F","chief":"Severe breathlessness","opening":"She is rapidly becoming short of breath and lightheaded.","history":"Recent cancer, invasive procedure or pericarditis.","exam":"Hypotension, elevated JVP and muffled heart sounds may occur; pulsus paradoxus.","test":"Urgent bedside echo shows effusion with chamber collapse and plethoric IVC.","mechanism":"Pericardial pressure impedes ventricular filling and causes obstructive shock.","differential":"Tension pneumothorax; decompensated heart failure","management":"Urgent drainage by experienced team and stabilization.","redflag":"This is a life-threatening obstructive shock emergency.","difficulty":1,"system":"Cardio","id":"O061"},{"dx":"Infective endocarditis","patient":"48M","chief":"Persistent fever","opening":"He has fevers and malaise for two weeks without a clear source.","history":"Injection drug use, valve disease or recent bloodstream infection.","exam":"New regurgitant murmur; splinter hemorrhages or embolic signs possible.","test":"Multiple blood cultures before antibiotics if feasible; echocardiography.","mechanism":"Infected valve vegetations cause bacteremia, emboli and valve destruction.","differential":"Viral illness; noninfective endocarditis","management":"Prompt blood cultures, IV targeted antibiotics and specialist input.","redflag":"Watch for heart failure, stroke and conduction abnormalities.","difficulty":2,"system":"Cardio","id":"O062"},{"dx":"Myocarditis","patient":"23M","chief":"Chest pain after illness","opening":"He has chest pain and new exercise intolerance following a viral syndrome.","history":"Palpitations or recent systemic illness; possible syncope.","exam":"Tachycardia out of proportion, signs of heart failure possible.","test":"ECG, troponin, echo; cardiac MRI often helps.","mechanism":"Inflammatory myocardial injury impairs contractility and triggers arrhythmias.","differential":"Acute coronary syndrome; pericarditis","management":"Supportive cardiac care and avoid intense exercise until cleared.","redflag":"Arrhythmia and cardiogenic shock can occur.","difficulty":2,"system":"Cardio","id":"O063"},{"dx":"Hypertensive emergency","patient":"59F","chief":"Headache and confusion","opening":"She has a severe headache and new confusion with markedly elevated blood pressure.","history":"Visual change, chest pain, dyspnea or reduced urine output may coexist.","exam":"Very high BP plus objective neurologic or cardiac findings.","test":"Urgent tests for acute organ injury: creatinine, urinalysis, ECG, directed imaging.","mechanism":"Acute severe hypertension with target-organ damage distinguishes emergency from asymptomatic elevation.","differential":"Hypertensive urgency; intracranial hemorrhage","management":"Controlled IV blood pressure reduction tailored to the specific organ injury.","redflag":"Do not rapidly normalize BP indiscriminately.","difficulty":1,"system":"Cardio","id":"O064"},{"dx":"Aortic dissection","patient":"60M","chief":"Sudden severe chest pain","opening":"Abrupt severe chest pain radiates between the shoulder blades.","history":"Onset maximal immediately; hypertension or connective tissue disease.","exam":"Pulse or BP asymmetry, new AR murmur, possible neurologic deficit.","test":"CTA aorta in stable patient; bedside TEE if unstable and appropriate.","mechanism":"Intimal tear creates false lumen and can impair branch perfusion.","differential":"STEMI; pulmonary embolism","management":"Immediate specialist consultation, analgesia and impulse control; surgery for type A.","redflag":"Avoid antithrombotics until dissection considered when suggestive.","difficulty":1,"system":"Cardio","id":"O065"},{"dx":"Abdominal aortic aneurysm","patient":"72M","chief":"Abdominal and back discomfort","opening":"An older smoker reports deep abdominal discomfort.","history":"Smoking and family history; may be asymptomatic until large.","exam":"Pulsatile abdominal mass may be present.","test":"Abdominal ultrasound for stable screening; CTA for anatomy or symptomatic cases.","mechanism":"Degenerative aortic wall dilation risks rupture.","differential":"Renal colic; lumbar strain","management":"Vascular referral according to size/symptoms and rupture risk.","redflag":"Pain with hypotension suggests rupture: emergency.","difficulty":2,"system":"Cardio","id":"O066"},{"dx":"Peripheral arterial disease","patient":"68M","chief":"Calf pain when walking","opening":"His calf hurts after a fixed walking distance and settles at rest.","history":"Smoking, diabetes and atherosclerosis; foot wounds may heal poorly.","exam":"Diminished pulses, cool skin or trophic changes.","test":"Ankle-brachial index below 0.90 typically supports PAD.","mechanism":"Atherosclerotic flow limitation creates exertional ischemic muscle pain.","differential":"Lumbar stenosis; chronic venous disease","management":"Exercise therapy, smoking cessation, antiplatelet/statin therapy as indicated.","redflag":"Rest pain and tissue loss suggest chronic limb-threatening ischemia.","difficulty":1,"system":"Cardio","id":"O067"},{"dx":"Acute limb ischemia","patient":"71F","chief":"Sudden painful leg","opening":"Her foot became suddenly cold and painful an hour ago.","history":"Atrial fibrillation or vascular procedure; rapid sensory change.","exam":"Pain, pallor, pulselessness, poikilothermia, paresthesia, paralysis.","test":"Urgent vascular assessment and Doppler; CTA if it does not delay limb-saving care.","mechanism":"Embolic or thrombotic arterial occlusion threatens tissue viability.","differential":"DVT; compartment syndrome","management":"Immediate heparin if appropriate and emergency vascular consultation for revascularization.","redflag":"Motor deficit suggests advanced threatened limb.","difficulty":1,"system":"Cardio","id":"O068"},{"dx":"Deep venous thrombosis","patient":"46F","chief":"One swollen leg","opening":"One calf has become swollen and tender over two days.","history":"Recent surgery, immobility, estrogen exposure or cancer.","exam":"Unilateral edema, calf tenderness; signs nonspecific.","test":"Wells-based approach, D-dimer where indicated, compression venous ultrasound.","mechanism":"Venous thrombosis obstructs drainage and can embolize to lung.","differential":"Cellulitis; ruptured Baker cyst","management":"Anticoagulation if confirmed and appropriate; evaluate bleeding risk.","redflag":"Assess respiratory symptoms suggesting pulmonary embolism.","difficulty":1,"system":"Cardio","id":"O069"},{"dx":"Orthostatic hypotension","patient":"75M","chief":"Dizzy on standing","opening":"He becomes briefly lightheaded when rising from bed.","history":"Dehydration, antihypertensives or autonomic dysfunction; resolves sitting.","exam":"Sustained BP drop on standing with symptoms.","test":"Orthostatic vital signs and directed assessment of causes.","mechanism":"Impaired volume/autonomic compensation reduces cerebral perfusion on standing.","differential":"Vasovagal syncope; arrhythmia","management":"Review medications, hydration and treat underlying cause.","redflag":"Consider hemorrhage or cardiac syncope when history suggests.","difficulty":1,"system":"Cardio","id":"O070"},{"dx":"Vasovagal syncope","patient":"20F","chief":"Fainted at ceremony","opening":"She fainted while standing in a hot crowded room.","history":"Warmth, nausea, sweating and tunnel vision before brief loss of consciousness.","exam":"Normal exam and recovery; possible transient hypotension.","test":"Focused evaluation including ECG and orthostatic signs when appropriate.","mechanism":"Reflex vagal activation and vasodilation cause transient cerebral hypoperfusion.","differential":"Cardiac arrhythmia; orthostatic hypotension","management":"Reassurance and trigger avoidance after excluding high-risk features.","redflag":"Exertional syncope or family sudden death should not be labeled benign.","difficulty":1,"system":"Cardio","id":"O071"},{"dx":"Postural orthostatic tachycardia syndrome","patient":"24F","chief":"Racing heart on standing","opening":"She experiences palpitations and fatigue whenever standing for long.","history":"Orthostatic symptoms for months without sustained hypotension.","exam":"Heart rate rises at least 30 bpm within 10 minutes standing in adults, without orthostatic hypotension.","test":"Active stand or tilt testing after excluding other causes.","mechanism":"Autonomic orthostatic intolerance causes excessive upright tachycardia.","differential":"Orthostatic hypotension; anxiety","management":"Fluids, salt if appropriate, compression and graded exercise; specialist input.","redflag":"Exclude anemia, dehydration and primary arrhythmia.","difficulty":3,"system":"Cardio","id":"O072"},{"dx":"Coarctation of the aorta","patient":"17M","chief":"High blood pressure","opening":"A teenager is found to have hypertension on routine screening.","history":"May report leg fatigue with exertion or headaches.","exam":"Arm BP higher than leg BP, diminished/delayed femoral pulses.","test":"Echocardiogram; CT/MR angiography for anatomy.","mechanism":"Congenital aortic narrowing proximal to lower body reduces leg perfusion.","differential":"Essential hypertension; renal artery stenosis","management":"Congenital cardiology assessment and repair planning.","redflag":"Screen for associated bicuspid aortic valve.","difficulty":2,"system":"Cardio","id":"O073"},{"dx":"Patent ductus arteriosus","patient":"3F","chief":"Heart murmur","opening":"A young child is referred for a persistent murmur.","history":"Poor feeding or growth when shunt is significant.","exam":"Continuous machinery-like murmur near left infraclavicular area, bounding pulses.","test":"Echocardiogram confirms left-to-right ductal shunt.","mechanism":"Persistent fetal connection between aorta and pulmonary artery increases pulmonary flow.","differential":"Ventricular septal defect; aortic regurgitation","management":"Pediatric cardiology; closure when indicated.","redflag":"Large shunts can cause heart failure and pulmonary vascular disease.","difficulty":2,"system":"Cardio","id":"O074"},{"dx":"Tetralogy of Fallot","patient":"2M","chief":"Blue spells","opening":"A toddler becomes bluish while crying and occasionally squats afterward.","history":"Episodes with exertion or crying, poor feeding possible.","exam":"Cyanosis and harsh systolic ejection murmur at left sternal border.","test":"Echocardiography identifies VSD, RVOT obstruction, overriding aorta and RV hypertrophy.","mechanism":"Right-to-left shunting causes hypoxemia, especially during hypercyanotic spells.","differential":"Transposition of great arteries; pulmonary stenosis","management":"Urgent pediatric cardiology; manage hypercyanotic spell with knee-chest positioning and oxygen.","redflag":"Severe cyanotic spells require emergency care.","difficulty":2,"system":"Cardio","id":"O075"},{"dx":"Ventricular septal defect","patient":"6moM","chief":"Difficulty feeding","opening":"An infant breathes rapidly and tires during feeds.","history":"Poor weight gain and sweating with feeding when shunt large.","exam":"Harsh holosystolic murmur at lower left sternal border.","test":"Echocardiogram shows interventricular left-to-right shunt.","mechanism":"Large VSD increases pulmonary blood flow and can cause failure to thrive.","differential":"Atrial septal defect; patent ductus arteriosus","management":"Pediatric cardiology and treatment/closure guided by defect and physiology.","redflag":"Monitor growth and heart failure signs.","difficulty":2,"system":"Cardio","id":"O076"},{"dx":"Atrial septal defect","patient":"9F","chief":"Incidental murmur","opening":"A schoolchild has a murmur without major symptoms.","history":"May have exercise intolerance or recurrent respiratory infections.","exam":"Fixed wide split S2, systolic flow murmur at pulmonary area.","test":"Echocardiogram with Doppler confirms interatrial shunt.","mechanism":"Left-to-right atrial shunt increases right heart volume.","differential":"Pulmonic stenosis; VSD","management":"Cardiology assessment for closure if hemodynamically significant.","redflag":"Longstanding large shunts can develop arrhythmias and pulmonary hypertension.","difficulty":2,"system":"Cardio","id":"O077"},{"dx":"Pulmonary hypertension","patient":"51F","chief":"Progressive exertional dyspnea","opening":"Walking across a parking lot now causes marked breathlessness.","history":"Fatigue, exertional near-syncope and possible connective tissue disease.","exam":"Loud P2, RV heave, JVP elevation and edema if advanced.","test":"Echo suggests elevated pressure; right heart catheterization confirms and classifies.","mechanism":"Elevated pulmonary vascular resistance overloads right ventricle.","differential":"HFrEF; chronic thromboembolic disease","management":"Refer for etiology-specific workup and targeted treatment.","redflag":"Syncope and RV failure suggest severe disease.","difficulty":2,"system":"Cardio","id":"O078"},{"dx":"Tricuspid regurgitation","patient":"61M","chief":"Leg swelling","opening":"He has worsening leg edema and abdominal fullness.","history":"Prior right-sided heart disease or implanted device.","exam":"Holosystolic murmur at lower left sternal border louder with inspiration; pulsatile liver.","test":"Echocardiogram evaluates tricuspid valve and right ventricle.","mechanism":"Systolic regurgitation into RA causes systemic venous congestion.","differential":"Mitral regurgitation; right heart failure","management":"Treat underlying pulmonary/left heart disease and congestion; valve team if severe.","redflag":"Look for infection in device-associated disease.","difficulty":3,"system":"Cardio","id":"O079"},{"dx":"Constrictive pericarditis","patient":"58M","chief":"Abdominal bloating and edema","opening":"He has progressive edema despite preserved apparent systolic function.","history":"Prior cardiac surgery, radiation or tuberculosis exposure.","exam":"Elevated JVP with Kussmaul sign, possible pericardial knock.","test":"Echo and cardiac CT/MRI; catheterization if diagnostic uncertainty.","mechanism":"Rigid pericardium limits diastolic filling and causes systemic congestion.","differential":"Restrictive cardiomyopathy; cirrhosis","management":"Diuresis for symptoms; specialist evaluation for pericardiectomy.","redflag":"Recognize discordant left/right ventricular respiratory physiology.","difficulty":3,"system":"Cardio","id":"O080"},{"dx":"Acute asthma exacerbation","patient":"19F","chief":"Wheezing and breathlessness","opening":"She has chest tightness and wheezing after being around a cat.","history":"Episodic symptoms, nocturnal cough and atopy; reliever inhaler helps.","exam":"Expiratory wheeze, prolonged expiration; severe cases may have silent chest.","test":"Peak flow or spirometry when stable; measure O2 saturation and work of breathing.","mechanism":"Reversible airway inflammation and bronchoconstriction impair expiratory flow.","differential":"COPD exacerbation; anaphylaxis","management":"Inhaled short-acting bronchodilator, oxygen as needed and systemic steroid for moderate-severe attack.","redflag":"Silent chest, exhaustion or altered consciousness are life-threatening signs.","difficulty":1,"system":"Pulm","id":"O081"},{"dx":"Chronic obstructive pulmonary disease","patient":"67M","chief":"Chronic cough and dyspnea","opening":"A former smoker reports worsening breathlessness over years.","history":"Long smoking history, daily sputum and recurrent winter symptoms.","exam":"Reduced breath sounds, prolonged expiratory phase, possible barrel chest.","test":"Post-bronchodilator spirometry with persistent FEV1/FVC obstruction.","mechanism":"Chronic small-airway disease and emphysema cause incompletely reversible airflow limitation.","differential":"Asthma; heart failure","management":"Smoking cessation, vaccines, pulmonary rehab and guideline-based inhalers.","redflag":"Evaluate exacerbations and oxygen status.","difficulty":1,"system":"Pulm","id":"O082"},{"dx":"Acute COPD exacerbation","patient":"70M","chief":"Worsening shortness of breath","opening":"A patient with chronic lung disease now has increased cough and sputum.","history":"More dyspnea and sputum purulence/volume over two days.","exam":"Wheezing, accessory muscle use, possible hypoxia.","test":"Pulse oximetry, blood gas if severe; chest x-ray to assess pneumonia.","mechanism":"Acute airway inflammation worsens baseline obstruction and gas exchange.","differential":"Pneumonia; acute heart failure","management":"Short-acting bronchodilators, systemic steroid, controlled oxygen; antibiotics when indicated.","redflag":"Watch for hypercapnic respiratory failure and need for ventilation.","difficulty":1,"system":"Pulm","id":"O083"},{"dx":"Community-acquired pneumonia","patient":"49F","chief":"Fever and productive cough","opening":"She has fever, cough and right-sided chest pain on inspiration.","history":"Illness over three days, chills and purulent sputum.","exam":"Focal crackles, bronchial breath sounds or dullness.","test":"Chest radiograph with focal infiltrate if available; assess severity and O2.","mechanism":"Alveolar infection causes consolidation and V/Q mismatch.","differential":"Acute bronchitis; pulmonary embolism","management":"Appropriate empiric antibiotics based on severity and setting, supportive care.","redflag":"Assess sepsis, hypoxia and admission criteria.","difficulty":1,"system":"Pulm","id":"O084"},{"dx":"Aspiration pneumonia","patient":"81M","chief":"Cough after choking","opening":"He develops fever and cough following an episode of choking at dinner.","history":"Dysphagia, stroke history, sedation or poor dentition.","exam":"Focal crackles, often dependent lung zones.","test":"Chest imaging shows dependent infiltrate; evaluate swallowing.","mechanism":"Aspirated oropharyngeal material introduces pathogens into dependent lung.","differential":"Chemical pneumonitis; community pneumonia","management":"Treat established bacterial infection appropriately; manage aspiration risk and swallowing.","redflag":"Differentiate immediate chemical pneumonitis from later infection.","difficulty":2,"system":"Pulm","id":"O085"},{"dx":"Pulmonary embolism","patient":"38F","chief":"Sudden breathlessness","opening":"She becomes suddenly short of breath with sharp chest pain.","history":"Recent long trip or surgery, estrogen exposure, leg swelling possible.","exam":"Tachycardia, tachypnea, sometimes normal lung auscultation.","test":"Clinical probability, D-dimer if appropriate, CT pulmonary angiography or V/Q scan.","mechanism":"Thrombus obstructs pulmonary arteries causing V/Q mismatch and RV strain.","differential":"Pneumothorax; pneumonia","management":"Anticoagulate when appropriate; urgent reperfusion evaluation if high-risk instability.","redflag":"Unexplained hypoxia and shock should prompt urgent assessment.","difficulty":1,"system":"Pulm","id":"O086"},{"dx":"Tension pneumothorax","patient":"24M","chief":"Severe breathing difficulty","opening":"After chest trauma he becomes hypotensive and acutely dyspneic.","history":"Rapid worsening and unilateral chest discomfort.","exam":"Absent unilateral breath sounds, hyperresonance, hypotension; tracheal shift late.","test":"Clinical diagnosis in unstable patient; do not wait for chest x-ray.","mechanism":"Increasing pleural pressure collapses lung and impairs venous return.","differential":"Cardiac tamponade; massive hemothorax","management":"Immediate needle/finger decompression followed by chest drain per setting.","redflag":"Treat before imaging when unstable.","difficulty":1,"system":"Pulm","id":"O087"},{"dx":"Primary spontaneous pneumothorax","patient":"22M","chief":"Sudden chest pain","opening":"A tall thin young adult develops abrupt one-sided pleuritic pain.","history":"No trauma or known lung disease; breathlessness variable.","exam":"Reduced breath sounds and hyperresonance on affected side.","test":"Chest radiograph or ultrasound in stable patient.","mechanism":"Air enters pleural space and collapses lung without known structural disease.","differential":"Pulmonary embolism; costochondritis","management":"Management depends on size, symptoms and stability, ranging from observation to aspiration/drain.","redflag":"Check for tension physiology first.","difficulty":1,"system":"Pulm","id":"O088"},{"dx":"Pleural effusion","patient":"69F","chief":"Progressive breathlessness","opening":"She has weeks of increasing dyspnea and a heavy feeling in one chest.","history":"Heart failure, malignancy or infection may be relevant.","exam":"Dullness to percussion, reduced breath sounds and tactile fremitus.","test":"Chest ultrasound; diagnostic thoracentesis when indicated; Light criteria classify.","mechanism":"Fluid accumulates in pleural space from transudative or exudative processes.","differential":"Pneumonia; atelectasis","management":"Treat underlying cause and drain if symptomatic or diagnostic need.","redflag":"Fever, loculation or malignancy signs require focused workup.","difficulty":2,"system":"Pulm","id":"O089"},{"dx":"Empyema","patient":"56M","chief":"Fever despite antibiotics","opening":"He remains febrile with pleuritic pain despite pneumonia treatment.","history":"Persistent productive cough and systemic illness.","exam":"Reduced breath sounds, dullness and fever.","test":"Ultrasound/CT loculated effusion; pleural pH low or frank pus.","mechanism":"Infected pleural space develops fibrin, loculations and persistent sepsis.","differential":"Uncomplicated parapneumonic effusion; lung abscess","management":"Antibiotics plus pleural drainage, sometimes fibrinolytics or surgery.","redflag":"Antibiotics alone often inadequate without source control.","difficulty":2,"system":"Pulm","id":"O090"},{"dx":"Pulmonary tuberculosis","patient":"34M","chief":"Cough and weight loss","opening":"He has a cough for weeks, night sweats and unintended weight loss.","history":"Exposure risk, travel, prior TB or immunosuppression.","exam":"May have apical crackles or normal auscultation.","test":"Chest radiograph, sputum NAAT and AFB smear/culture; isolation protocol.","mechanism":"Mycobacterium tuberculosis causes granulomatous infection with possible cavitation.","differential":"Lung cancer; bacterial pneumonia","management":"Airborne precautions, public health coordination and multidrug therapy after evaluation.","redflag":"Consider contagious disease and protect staff/patients.","difficulty":2,"system":"Pulm","id":"O091"},{"dx":"Bronchiectasis","patient":"57F","chief":"Daily productive cough","opening":"She coughs large amounts of sputum most mornings.","history":"Repeated chest infections, childhood illness or immune disorder.","exam":"Coarse crackles, sometimes clubbing.","test":"High-resolution CT shows bronchial dilation and lack of tapering; sputum culture.","mechanism":"Chronic airway damage impairs clearance, sustaining infection and inflammation.","differential":"COPD; chronic bronchitis","management":"Airway clearance, vaccines and culture-directed treatment of exacerbations.","redflag":"Hemoptysis can become severe.","difficulty":2,"system":"Pulm","id":"O092"},{"dx":"Cystic fibrosis","patient":"17M","chief":"Recurrent chest infections","opening":"A teen has persistent cough and difficulty gaining weight.","history":"Chronic sinus disease, pancreatic insufficiency and family history.","exam":"Clubbing, crackles, low weight.","test":"Sweat chloride and CFTR genetic testing.","mechanism":"CFTR dysfunction produces thick secretions in lungs and pancreas.","differential":"Primary ciliary dyskinesia; bronchiectasis","management":"Specialist multidisciplinary care, airway clearance and genotype-specific modulators.","redflag":"Monitor nutrition, infection and respiratory decline.","difficulty":2,"system":"Pulm","id":"O093"},{"dx":"Idiopathic pulmonary fibrosis","patient":"72M","chief":"Dry cough and dyspnea","opening":"Dry cough and progressive breathlessness have increased for a year.","history":"Older age and gradual exertional limitation without clear exposure.","exam":"Fine bibasilar Velcro crackles and possible clubbing.","test":"HRCT with usual interstitial pneumonia pattern; PFT restrictive with low DLCO.","mechanism":"Progressive lung fibrosis stiffens alveoli and impairs diffusion.","differential":"Heart failure; hypersensitivity pneumonitis","management":"Specialist assessment for antifibrotics, rehab and oxygen needs.","redflag":"Exclude connective tissue disease and environmental exposures.","difficulty":2,"system":"Pulm","id":"O094"},{"dx":"Sarcoidosis","patient":"33F","chief":"Dry cough and fatigue","opening":"She has persistent cough and painful red nodules on her shins.","history":"May have eye irritation, skin lesions or fatigue.","exam":"Erythema nodosum, lymphadenopathy, occasionally crackles.","test":"Chest x-ray shows bilateral hilar adenopathy; tissue noncaseating granulomas if needed.","mechanism":"Immune granulomas can involve lungs, skin, eyes and heart.","differential":"Tuberculosis; lymphoma","management":"Evaluate organ involvement; observe mild disease or treat symptomatic organ disease.","redflag":"Screen ocular and cardiac red flags.","difficulty":2,"system":"Pulm","id":"O095"},{"dx":"Hypersensitivity pneumonitis","patient":"51M","chief":"Cough after home renovation","opening":"Breathlessness and cough worsen when he spends time in a damp basement.","history":"Bird, mold or agricultural antigen exposure; improves away from trigger.","exam":"Crackles, possible hypoxia after exposure.","test":"HRCT ground-glass and mosaic attenuation; history and multidisciplinary workup.","mechanism":"Inhaled antigens provoke immune-mediated bronchiolar/interstitial inflammation.","differential":"Idiopathic pulmonary fibrosis; asthma","management":"Antigen avoidance and specialist management; selected cases need steroids.","redflag":"Occupational/environmental history is essential.","difficulty":3,"system":"Pulm","id":"O096"},{"dx":"Silicosis","patient":"59M","chief":"Increasing exertional dyspnea","opening":"A stone countertop worker has developed chronic cough.","history":"Years of engineered-stone dust exposure, tuberculosis risk.","exam":"Crackles or normal exam early.","test":"Occupational history plus chest imaging with upper-lobe nodules, sometimes eggshell calcification.","mechanism":"Inhaled crystalline silica causes progressive fibrotic pneumoconiosis.","differential":"Sarcoidosis; tuberculosis","management":"Eliminate exposure, monitor lung function and manage complications.","redflag":"Silicosis increases TB susceptibility.","difficulty":3,"system":"Pulm","id":"O097"},{"dx":"Asbestosis","patient":"68M","chief":"Gradual breathlessness","opening":"A retired shipyard worker is increasingly breathless.","history":"Asbestos exposure decades earlier and dry cough.","exam":"Basal crackles and sometimes clubbing.","test":"HRCT basal interstitial fibrosis and pleural plaques; restrictive PFTs.","mechanism":"Long-latency asbestos fibers cause pulmonary interstitial fibrosis.","differential":"Idiopathic pulmonary fibrosis; mesothelioma","management":"Exposure cessation, surveillance and supportive respiratory care.","redflag":"Asbestos exposure raises mesothelioma and lung cancer risk.","difficulty":3,"system":"Pulm","id":"O098"},{"dx":"Obstructive sleep apnea","patient":"52M","chief":"Daytime sleepiness","opening":"He snores loudly and falls asleep during meetings.","history":"Witnessed pauses in breathing, morning headaches, obesity.","exam":"Large neck circumference, crowded oropharynx; hypertension may coexist.","test":"Home sleep apnea testing or polysomnography by clinical indication.","mechanism":"Recurrent pharyngeal collapse causes hypoxia and fragmented sleep.","differential":"Obesity hypoventilation; insomnia","management":"CPAP or other airway therapy, weight management and driving safety advice.","redflag":"Severe sleepiness creates accident risk.","difficulty":1,"system":"Pulm","id":"O099"},{"dx":"Obesity hypoventilation syndrome","patient":"58F","chief":"Daytime fatigue and breathlessness","opening":"She has obesity, morning headaches and chronic breathlessness.","history":"Hypersomnolence, nocturnal snoring and edema; no other cause of hypoventilation.","exam":"Obesity with possible signs of pulmonary hypertension.","test":"Awake PaCO2 at least 45 mmHg, sleep testing and exclusion of alternate causes.","mechanism":"Inadequate ventilation in obesity causes chronic daytime hypercapnia.","differential":"Obstructive sleep apnea; COPD","management":"Positive airway pressure and weight management; manage respiratory failure.","redflag":"Oxygen alone may worsen hypercapnia in susceptible patients.","difficulty":2,"system":"Pulm","id":"O100"},{"dx":"Non-small cell lung cancer","patient":"65M","chief":"Persistent cough and weight loss","opening":"A long-term smoker has a cough that will not settle.","history":"Hemoptysis, weight loss or recurrent focal pneumonia.","exam":"May have focal wheeze, clubbing or lymph nodes.","test":"Chest CT and tissue biopsy with staging and biomarkers.","mechanism":"Malignant pulmonary epithelial tumor produces persistent focal symptoms.","differential":"Tuberculosis; chronic bronchitis","management":"Urgent cancer referral for staging and tailored surgery/systemic/radiation therapy.","redflag":"Hemoptysis and unexplained weight loss require evaluation.","difficulty":1,"system":"Pulm","id":"O101"},{"dx":"Small cell lung carcinoma","patient":"62M","chief":"Cough and confusion","opening":"A smoker presents with cough and new fatigue/confusion.","history":"Weight loss, rapid onset, possible hyponatremia symptoms.","exam":"May have focal signs or features of ectopic hormone production.","test":"Chest imaging and biopsy; serum sodium and staging.","mechanism":"Aggressive neuroendocrine lung tumor can produce ectopic ADH and early metastases.","differential":"Non-small cell lung cancer; SIADH from another cause","management":"Urgent oncology staging and systemic therapy; correct severe hyponatremia safely.","redflag":"Neurologic symptoms from severe low sodium can be emergent.","difficulty":3,"system":"Pulm","id":"O102"},{"dx":"Acute respiratory distress syndrome","patient":"54M","chief":"Rapid severe breathing failure","opening":"After severe pancreatitis he develops worsening oxygenation in hospital.","history":"Critical illness and rapid onset within a week of insult.","exam":"Tachypnea, diffuse crackles, marked oxygen requirement.","test":"Bilateral opacities not fully explained by heart failure; assess PaO2/FiO2.","mechanism":"Diffuse alveolar-capillary injury causes noncardiogenic pulmonary edema.","differential":"Cardiogenic pulmonary edema; pneumonia","management":"Treat cause, lung-protective ventilation and supportive critical care.","redflag":"Severe refractory hypoxemia is life-threatening.","difficulty":2,"system":"Pulm","id":"O103"},{"dx":"Cardiogenic pulmonary edema","patient":"74F","chief":"Sudden nighttime breathlessness","opening":"She wakes gasping with frothy sputum.","history":"Cardiac history, orthopnea and recent salt/medication changes.","exam":"Crackles throughout lungs, JVP elevation, possible edema.","test":"Chest radiograph interstitial/alveolar edema, BNP and bedside echo.","mechanism":"Elevated left heart filling pressure drives fluid into alveoli.","differential":"ARDS; COPD exacerbation","management":"Oxygen/ventilatory support as needed, diuresis and treat cardiac cause.","redflag":"Severe respiratory distress or hypoxia needs emergency stabilization.","difficulty":1,"system":"Pulm","id":"O104"},{"dx":"Acute bronchitis","patient":"29M","chief":"Cough after cold","opening":"He has a lingering cough after sore throat and runny nose.","history":"Mostly viral prodrome, no persistent high fever or dyspnea.","exam":"Normal vitals and no focal consolidation on lung exam.","test":"Clinical diagnosis after evaluating pneumonia probability.","mechanism":"Transient inflammation of large airways causes cough without pneumonia.","differential":"Pneumonia; asthma","management":"Supportive treatment; avoid routine antibiotics in uncomplicated acute bronchitis.","redflag":"Abnormal vitals or focal findings warrant pneumonia assessment.","difficulty":1,"system":"Pulm","id":"O105"},{"dx":"Pertussis","patient":"25F","chief":"Coughing fits","opening":"She has severe coughing bouts that end in vomiting.","history":"Paroxysmal cough for over two weeks, little fever, exposure to unvaccinated contact.","exam":"Exam may be normal between cough paroxysms.","test":"Nasopharyngeal PCR early; testing varies with symptom timing.","mechanism":"Bordetella pertussis toxin disrupts respiratory ciliary defenses.","differential":"Viral bronchitis; asthma","management":"Macrolide therapy when indicated, isolation and contact prophylaxis under guidance.","redflag":"Infants exposed to pertussis are especially vulnerable.","difficulty":2,"system":"Pulm","id":"O106"},{"dx":"Viral croup","patient":"2M","chief":"Barking cough","opening":"A toddler develops a seal-like cough at night after a cold.","history":"Hoarse voice, inspiratory noisy breathing; low-grade fever.","exam":"Inspiratory stridor, barky cough; severity depends on distress at rest.","test":"Clinical diagnosis; imaging usually not required.","mechanism":"Viral laryngotracheal inflammation narrows subglottic airway.","differential":"Epiglottitis; foreign body aspiration","management":"Dexamethasone; nebulized epinephrine for moderate/severe stridor with observation.","redflag":"Agitation and severe stridor can herald airway compromise.","difficulty":1,"system":"Pulm","id":"O107"},{"dx":"Epiglottitis","patient":"5F","chief":"Drooling and difficulty breathing","opening":"A child looks very ill with fever and refuses to swallow.","history":"Rapid progression, severe sore throat and muffled voice.","exam":"Drooling, tripod position, stridor; do not force throat exam.","test":"Clinical airway assessment in controlled setting; cultures after stabilization.","mechanism":"Supraglottic swelling can abruptly obstruct the airway.","differential":"Croup; retropharyngeal abscess","management":"Urgent airway team and IV antibiotics, avoid distressing manipulations.","redflag":"Do not examine throat aggressively in an unstable child.","difficulty":1,"system":"Pulm","id":"O108"},{"dx":"Bronchiolitis","patient":"7moF","chief":"Wheezing with a cold","opening":"An infant has cough, congestion and increased work of breathing.","history":"Recent runny nose, decreased feeding and possible apnea risk.","exam":"Tachypnea, wheeze/crackles, retractions.","test":"Clinical; pulse oximetry, no routine chest x-ray in uncomplicated cases.","mechanism":"Usually RSV-mediated inflammation blocks small infant airways.","differential":"Asthma; pneumonia","management":"Supportive suction, hydration and oxygen based on clinical status.","redflag":"Apnea, dehydration and fatigue can mandate hospitalization.","difficulty":1,"system":"Pulm","id":"O109"},{"dx":"Influenza","patient":"38M","chief":"Fever and body aches","opening":"Fever, abrupt myalgias and cough began yesterday.","history":"Sick contacts during flu season and marked fatigue.","exam":"Febrile, tachycardic, usually nonfocal chest exam.","test":"Clinical diagnosis or molecular respiratory assay when useful.","mechanism":"Influenza virus causes abrupt systemic and respiratory illness.","differential":"COVID-19; bacterial pneumonia","management":"Supportive care and antivirals for indicated patients and timing.","redflag":"Watch for secondary bacterial pneumonia and high-risk hosts.","difficulty":1,"system":"Pulm","id":"O110"},{"dx":"COVID-19","patient":"44F","chief":"Cough and loss of smell","opening":"She has fever and cough with altered smell after a family gathering.","history":"Exposure, myalgias, sore throat or dyspnea.","exam":"Often mild exam; hypoxia in severe disease.","test":"Antigen or NAAT testing; assess oxygen saturation and risk factors.","mechanism":"SARS-CoV-2 causes variable upper and lower respiratory disease.","differential":"Influenza; community pneumonia","management":"Risk-stratified antiviral consideration early, supportive care and precautions.","redflag":"Assess hypoxia and drug interactions with antivirals.","difficulty":1,"system":"Pulm","id":"O111"},{"dx":"Alpha-1 antitrypsin deficiency","patient":"37M","chief":"Breathlessness at a young age","opening":"He has progressive dyspnea despite never smoking.","history":"Family liver disease and early emphysema; recurrent wheezing.","exam":"Hyperinflation and reduced breath sounds.","test":"Serum A1AT level, genotype/phenotype; CT often basilar emphysema.","mechanism":"Loss of protease inhibition destroys alveoli and may injure liver.","differential":"Smoking-related COPD; asthma","management":"Smoking avoidance, pulmonary management and specialist assessment for augmentation in select cases.","redflag":"Evaluate liver disease and family members.","difficulty":3,"system":"Pulm","id":"O112"},{"dx":"Pneumocystis jirovecii pneumonia","patient":"36M","chief":"Progressive dry cough","opening":"He becomes increasingly breathless over several weeks.","history":"Immunosuppression or advanced HIV, fever and dry cough.","exam":"Marked desaturation with exertion; chest exam can be deceptively normal.","test":"CT diffuse ground-glass; induced sputum or BAL PCR/stain; HIV testing as appropriate.","mechanism":"Opportunistic fungus causes diffuse interstitial alveolar injury.","differential":"Viral pneumonia; tuberculosis","management":"TMP-SMX; adjunct corticosteroids for significant hypoxemia when indicated.","redflag":"Failure to recognize profound hypoxia can be dangerous.","difficulty":2,"system":"Pulm","id":"O113"},{"dx":"Allergic bronchopulmonary aspergillosis","patient":"30F","chief":"Recurrent wheezing and mucus","opening":"An asthmatic patient reports worsening cough with brownish mucus plugs.","history":"Poorly controlled asthma and recurrent infiltrates.","exam":"Wheeze and sometimes crackles.","test":"Elevated total IgE, Aspergillus-specific IgE and CT central bronchiectasis.","mechanism":"Hypersensitivity reaction to colonizing Aspergillus injures bronchi.","differential":"Asthma alone; bronchiectasis","management":"Specialist-directed glucocorticoid or antifungal strategy and asthma control.","redflag":"Consider in asthma with unexpectedly high IgE and bronchiectasis.","difficulty":3,"system":"Pulm","id":"O114"},{"dx":"Vocal cord dysfunction","patient":"23F","chief":"Noisy breathing during exercise","opening":"She develops abrupt difficulty breathing during intense workouts.","history":"More difficulty inhaling than exhaling; limited bronchodilator response.","exam":"Inspiratory stridor during episode, often normal between attacks.","test":"Laryngoscopy during symptoms demonstrates paradoxical vocal fold adduction.","mechanism":"Inducible laryngeal obstruction mimics asthma but occurs in upper airway.","differential":"Exercise-induced asthma; foreign body","management":"Breathing retraining and speech therapy; identify triggers.","redflag":"Rule out anaphylaxis or true airway emergency during severe episodes.","difficulty":2,"system":"Pulm","id":"O115"},{"dx":"Foreign body aspiration","patient":"3M","chief":"Sudden cough and wheeze","opening":"A toddler suddenly starts coughing while eating peanuts.","history":"Choking event, abrupt unilateral symptoms, no preceding viral illness.","exam":"Unilateral reduced breath sounds or focal wheeze.","test":"Airway assessment; chest x-ray may show air trapping; bronchoscopy is definitive.","mechanism":"Obstructing material creates focal airflow limitation.","differential":"Bronchiolitis; asthma","management":"Urgent bronchoscopy when suspected; emergency airway approach if obstruction severe.","redflag":"A normal radiograph does not exclude an aspirated object.","difficulty":1,"system":"Pulm","id":"O116"},{"dx":"Connective tissue disease-associated ILD","patient":"47F","chief":"Dry cough and tight fingers","opening":"She reports progressive dry cough and dyspnea plus stiff fingers.","history":"Raynaud phenomenon, skin tightening, reflux or arthritis.","exam":"Fine bibasilar crackles, sclerodactyly or nailfold changes.","test":"Autoimmune serology, PFT/DLCO and HRCT.","mechanism":"Systemic autoimmune inflammation causes interstitial fibrosis.","differential":"Idiopathic pulmonary fibrosis; hypersensitivity pneumonitis","management":"Rheumatology/pulmonary multidisciplinary care and disease-specific immunomodulation.","redflag":"Evaluate pulmonary hypertension alongside ILD.","difficulty":3,"system":"Pulm","id":"O117"},{"dx":"Hemothorax","patient":"31M","chief":"Chest pain after crash","opening":"He has dyspnea after a high-speed collision.","history":"Chest trauma, dizziness and possible blood loss.","exam":"Dull percussion, diminished unilateral breath sounds, hypotension if severe.","test":"Trauma ultrasound and chest radiograph; CT in stable patient.","mechanism":"Bleeding into pleural space impairs ventilation and circulation.","differential":"Pneumothorax; pleural effusion","management":"Resuscitate and chest tube drainage with surgical evaluation for major bleeding.","redflag":"Massive blood loss can cause hemorrhagic shock.","difficulty":1,"system":"Pulm","id":"O118"},{"dx":"Lung abscess","patient":"53M","chief":"Foul sputum and fever","opening":"He has weeks of fever and cough producing foul-smelling sputum.","history":"Poor dentition, aspiration risk or impaired consciousness.","exam":"Focal crackles, possible clubbing with chronicity.","test":"Chest CT shows cavity with air-fluid level.","mechanism":"Necrotizing bacterial infection forms a pus-filled pulmonary cavity.","differential":"Tuberculosis; cavitating lung cancer","management":"Prolonged antibiotics targeting likely organisms; drain or evaluate refractory disease.","redflag":"Assess aspiration risk and rule out obstructing tumor.","difficulty":2,"system":"Pulm","id":"O119"},{"dx":"Postoperative atelectasis","patient":"66F","chief":"Breathlessness after surgery","opening":"A day after abdominal surgery she develops mild hypoxia.","history":"Shallow breathing from pain and prolonged immobility.","exam":"Reduced basal air entry and fine crackles.","test":"Chest x-ray shows volume loss and plate-like basal opacity.","mechanism":"Alveolar collapse reduces ventilation following anesthesia and splinting.","differential":"Pneumonia; pulmonary embolism","management":"Mobilize, optimize analgesia and lung expansion measures.","redflag":"Persistent fever, instability or severe hypoxia warrants broader assessment.","difficulty":1,"system":"Pulm","id":"O120"},{"dx":"Pulmonary alveolar proteinosis","patient":"42M","chief":"Slowly worsening breathlessness","opening":"He has months of dyspnea and a dry cough with few other symptoms.","history":"Often insidious; recurrent infections occasionally.","exam":"Fine crackles or near-normal exam.","test":"HRCT crazy-paving pattern; BAL milky fluid with PAS-positive material.","mechanism":"Impaired surfactant clearance fills alveoli, often due to anti-GM-CSF antibodies.","differential":"Pulmonary edema; pneumocystis pneumonia","management":"Specialist diagnosis and whole-lung lavage for symptomatic disease.","redflag":"Crazy-paving is not specific; confirm diagnosis.","difficulty":3,"system":"Pulm","id":"O121"},{"dx":"Acute eosinophilic pneumonia","patient":"27M","chief":"Severe fever and cough","opening":"He has fever and rapid respiratory decline after beginning vaping.","history":"Recent tobacco/vaping change, dyspnea and chest pain.","exam":"Hypoxemia and diffuse crackles.","test":"Bilateral infiltrates; BAL eosinophilia after excluding infection.","mechanism":"Acute pulmonary eosinophilic inflammation can cause respiratory failure.","differential":"Bacterial pneumonia; ARDS","management":"Stop exposure and specialist-guided corticosteroids after evaluation.","redflag":"Peripheral eosinophilia may be absent early.","difficulty":3,"system":"Pulm","id":"O122"},{"dx":"Acute uncomplicated cystitis","patient":"24F","chief":"Burning urination","opening":"She has burning and urgency for two days.","history":"Frequency without fever, flank pain or vaginal discharge.","exam":"Suprapubic tenderness possible; no costovertebral angle tenderness.","test":"Urinalysis can support; culture in recurrent/complicated cases.","mechanism":"Ascending bladder infection, often E coli, causes lower urinary symptoms.","differential":"Vaginitis; pyelonephritis","management":"Short-course guideline-recommended oral antibiotic when indicated.","redflag":"Pregnancy or systemic signs change evaluation and treatment.","difficulty":1,"system":"Renal","id":"O123"},{"dx":"Acute pyelonephritis","patient":"31F","chief":"Fever and flank pain","opening":"She has fever, nausea and pain along one side of her back.","history":"Dysuria may precede fever; rigors and vomiting possible.","exam":"Febrile with CVA tenderness and tachycardia.","test":"Urinalysis plus urine culture; image if obstruction or complicated course suspected.","mechanism":"Ascending infection reaches renal parenchyma.","differential":"Cystitis; kidney stone","management":"Systemic antibiotics and fluids; hospitalize if toxic or unable to tolerate PO.","redflag":"Sepsis or obstructed infected collecting system is an emergency.","difficulty":1,"system":"Renal","id":"O124"},{"dx":"Obstructed infected kidney stone","patient":"44M","chief":"Flank pain with fever","opening":"Severe flank pain began with chills and vomiting.","history":"Known stones, dysuria, fever or reduced urine.","exam":"Fever, CVA tenderness and possible hypotension.","test":"Urine/blood cultures, renal imaging for hydronephrosis and stone.","mechanism":"Urinary obstruction prevents infected urine drainage and risks sepsis.","differential":"Uncomplicated renal colic; pyelonephritis","management":"Immediate IV antibiotics plus urgent urologic drainage, not routine outpatient stone care.","redflag":"Never delay decompression for a septic obstructed kidney.","difficulty":1,"system":"Renal","id":"O125"},{"dx":"Ureterolithiasis","patient":"39M","chief":"Severe flank pain","opening":"He has waves of intense flank pain radiating toward the groin.","history":"Restlessness, microscopic or visible hematuria, nausea.","exam":"CVA discomfort, often afebrile and unable to stay still.","test":"Urinalysis, renal function; low-dose noncontrast CT or ultrasound as appropriate.","mechanism":"Ureteral stone causes acute smooth muscle spasm and upstream obstruction.","differential":"Pyelonephritis; abdominal aortic aneurysm","management":"Analgesia, fluids if dehydrated and size/location-based urologic follow-up.","redflag":"Fever, solitary kidney or AKI mandates escalation.","difficulty":1,"system":"Renal","id":"O126"},{"dx":"Benign prostatic hyperplasia","patient":"69M","chief":"Weak urine stream","opening":"He reports slow stream and waking several times nightly.","history":"Hesitancy, incomplete emptying and urgency; no fevers.","exam":"Enlarged smooth prostate on DRE when appropriate; assess retention.","test":"Urinalysis and postvoid residual as indicated; evaluate symptoms.","mechanism":"Age-related periurethral prostate growth obstructs bladder outflow.","differential":"Prostate cancer; neurogenic bladder","management":"Lifestyle measures and alpha blocker; consider 5-alpha reductase inhibitor if enlarged.","redflag":"Acute retention or renal dysfunction changes urgency.","difficulty":1,"system":"Renal","id":"O127"},{"dx":"Acute bacterial prostatitis","patient":"56M","chief":"Fever and pelvic pain","opening":"He has fever, dysuria and deep perineal discomfort.","history":"Acute urinary symptoms, chills and painful ejaculation possible.","exam":"Tender boggy prostate on gentle examination if needed; avoid massage.","test":"Urinalysis and culture; check sepsis risk.","mechanism":"Bacterial prostate infection causes obstructive and systemic symptoms.","differential":"Cystitis; epididymitis","management":"Appropriate systemic antibiotics, analgesia and supportive care.","redflag":"Do not perform vigorous prostatic massage; monitor retention or sepsis.","difficulty":2,"system":"Renal","id":"O128"},{"dx":"Acute urinary retention","patient":"73M","chief":"Cannot urinate","opening":"He has progressive suprapubic discomfort and cannot pass urine.","history":"Prior obstructive urinary symptoms or new anticholinergic drug.","exam":"Palpably distended tender bladder.","test":"Bladder scan/postvoid residual, urinalysis and renal function.","mechanism":"Bladder outflow obstruction or impaired detrusor function traps urine.","differential":"Anuria from kidney injury; UTI","management":"Prompt bladder decompression and investigate cause.","redflag":"Look for postobstructive diuresis and neurologic red flags.","difficulty":1,"system":"Renal","id":"O129"},{"dx":"Prerenal acute kidney injury","patient":"82F","chief":"Weakness and less urine","opening":"She has poor oral intake and has urinated very little.","history":"Recent vomiting or diarrhea and diuretic use.","exam":"Dry mucosa, orthostasis or tachycardia.","test":"Creatinine increase, concentrated urine in many cases; assess volume status.","mechanism":"Reduced renal perfusion decreases GFR without primary nephron injury initially.","differential":"Acute tubular necrosis; obstruction","management":"Correct hypovolemia and stop nephrotoxic exposures as appropriate.","redflag":"Assess shock, severe electrolyte abnormalities and urine output.","difficulty":1,"system":"Renal","id":"O130"},{"dx":"Acute tubular necrosis","patient":"63M","chief":"Rising creatinine in hospital","opening":"Kidney function worsens after septic shock.","history":"Recent hypotension or nephrotoxin exposure; nonoliguric or oliguric.","exam":"Volume status variable; may have edema.","test":"Urinalysis granular muddy-brown casts; serial creatinine and electrolytes.","mechanism":"Ischemic/toxic tubular epithelial injury impairs renal function.","differential":"Prerenal AKI; acute interstitial nephritis","management":"Treat trigger, avoid nephrotoxins and support fluid/electrolyte balance.","redflag":"Hyperkalemia and fluid overload may require urgent renal replacement therapy.","difficulty":2,"system":"Renal","id":"O131"},{"dx":"Acute interstitial nephritis","patient":"48F","chief":"Fever and kidney dysfunction","opening":"Creatinine rises after starting a new medication.","history":"Antibiotic, PPI or NSAID exposure; rash or arthralgias may occur.","exam":"Rash and low-grade fever possible but classic triad uncommon.","test":"Urinalysis with pyuria or WBC casts; consider biopsy if unclear.","mechanism":"Drug-triggered interstitial immune inflammation injures kidneys.","differential":"Acute tubular necrosis; pyelonephritis","management":"Stop suspected offending drug and consult nephrology if persistent/severe.","redflag":"Eosinophiluria is neither sufficiently sensitive nor specific.","difficulty":2,"system":"Renal","id":"O132"},{"dx":"Poststreptococcal glomerulonephritis","patient":"9M","chief":"Dark urine and puffy eyes","opening":"A child develops cola-colored urine two weeks after a sore throat.","history":"Recent pharyngitis or skin infection; reduced urine and headache.","exam":"Periorbital edema and hypertension.","test":"Urine RBC casts, low C3 and elevated streptococcal antibody titers.","mechanism":"Immune-complex deposition following streptococcal infection causes nephritic syndrome.","differential":"IgA nephropathy; lupus nephritis","management":"Support BP, salt/fluid balance and monitor renal function.","redflag":"Severe hypertension or pulmonary edema needs urgent care.","difficulty":1,"system":"Renal","id":"O133"},{"dx":"IgA nephropathy","patient":"22M","chief":"Blood in urine after cold","opening":"Visible hematuria begins while he still has an upper respiratory infection.","history":"Recurrent episodes within one to two days of mucosal illness.","exam":"May have elevated BP; otherwise exam often normal.","test":"Urinalysis with dysmorphic RBCs; complement often normal; biopsy if indicated.","mechanism":"Mesangial IgA deposits cause synpharyngitic nephritis.","differential":"Poststreptococcal GN; kidney stone","management":"Assess proteinuria and renal function, manage BP/proteinuria, nephrology follow-up.","redflag":"Significant proteinuria predicts progression.","difficulty":2,"system":"Renal","id":"O134"},{"dx":"Lupus nephritis","patient":"26F","chief":"Swelling and frothy urine","opening":"She has leg swelling and new foamy urine with joint pain.","history":"Photosensitivity, rash and oral ulcers; systemic autoimmune symptoms.","exam":"Edema, hypertension, possible rash.","test":"Protein quantification, creatinine, anti-dsDNA, complements, renal biopsy to classify.","mechanism":"Immune-complex glomerular inflammation in SLE causes proteinuria and hematuria.","differential":"IgA nephropathy; membranous nephropathy","management":"Urgent nephrology/rheumatology input and class-dependent immunosuppression.","redflag":"Monitor renal function; missing nephritis can cause irreversible damage.","difficulty":2,"system":"Renal","id":"O135"},{"dx":"Anti-GBM disease","patient":"35M","chief":"Coughing blood and dark urine","opening":"He coughs up blood and notices tea-colored urine.","history":"Rapid renal decline and pulmonary bleeding.","exam":"Pallor, crackles, hypertension or edema.","test":"Urine RBC casts, anti-GBM antibodies and urgent kidney biopsy if needed.","mechanism":"Antibodies against type IV collagen damage glomerular and alveolar basement membranes.","differential":"ANCA-associated vasculitis; lupus nephritis","management":"Emergency nephrology care, immunosuppression and plasma exchange in indicated disease.","redflag":"Pulmonary hemorrhage and rapidly progressive renal failure are life-threatening.","difficulty":2,"system":"Renal","id":"O136"},{"dx":"ANCA-associated glomerulonephritis","patient":"51F","chief":"Fatigue, sinus trouble and dark urine","opening":"She has prolonged sinus symptoms followed by hematuria.","history":"Constitutional symptoms, epistaxis and cough possible.","exam":"Purpura, sinus inflammation or neuropathy signs.","test":"Creatinine, urine sediment, PR3/MPO-ANCA and biopsy.","mechanism":"Pauci-immune small-vessel vasculitis causes rapidly progressive nephritis.","differential":"Anti-GBM disease; infection-related GN","management":"Urgent specialist evaluation with induction immunosuppression when confirmed.","redflag":"Check lung hemorrhage and other organ injury.","difficulty":3,"system":"Renal","id":"O137"},{"dx":"Minimal change disease","patient":"5F","chief":"Sudden puffy eyelids","opening":"A child develops striking edema after a minor cold.","history":"Frothy urine with little hematuria; may be otherwise well.","exam":"Periorbital and dependent edema.","test":"Heavy proteinuria, low albumin, typically bland sediment; pediatric pattern often clinical.","mechanism":"Podocyte foot-process effacement produces selective nephrotic protein leak.","differential":"FSGS; postinfectious GN","management":"Glucocorticoids per pediatric pathway, manage edema and infection risk.","redflag":"Evaluate thrombosis and severe intravascular depletion.","difficulty":1,"system":"Renal","id":"O138"},{"dx":"Focal segmental glomerulosclerosis","patient":"34M","chief":"Leg swelling and foamy urine","opening":"He reports progressive edema and protein-rich urine.","history":"Risk factors include obesity, HIV or family history.","exam":"Edema, sometimes hypertension.","test":"Protein quantification and kidney biopsy showing focal segmental scarring.","mechanism":"Podocyte injury and segmental glomerular sclerosis produce nephrotic proteinuria.","differential":"Minimal change disease; membranous nephropathy","management":"Renal protection, assess secondary causes and specialist-directed immunosuppression if primary.","redflag":"Progressive decline in eGFR is a concern.","difficulty":3,"system":"Renal","id":"O139"},{"dx":"Membranous nephropathy","patient":"57M","chief":"New swelling","opening":"Both legs swell and urine becomes foamy.","history":"May have autoimmune illness, hepatitis or malignancy risk.","exam":"Pitting edema without active joint inflammation.","test":"Heavy proteinuria; anti-PLA2R and biopsy when needed.","mechanism":"Subepithelial immune deposits thicken glomerular basement membrane.","differential":"FSGS; diabetic kidney disease","management":"RAAS blockade, sodium restriction and risk-stratified immunotherapy.","redflag":"Nephrotic syndrome raises venous thrombosis risk.","difficulty":2,"system":"Renal","id":"O140"},{"dx":"Diabetic kidney disease","patient":"62F","chief":"Swollen feet","opening":"A patient with longstanding diabetes develops albumin in urine.","history":"Years of hyperglycemia and retinopathy; gradual progression.","exam":"Hypertension, edema or other diabetic complications.","test":"Urine albumin/creatinine ratio and eGFR trends.","mechanism":"Chronic glomerular hyperfiltration and metabolic injury cause albuminuria and sclerosis.","differential":"Membranous nephropathy; hypertensive nephrosclerosis","management":"Optimize glucose/BP, SGLT2 inhibitor and RAAS blockade when indicated.","redflag":"Rapid unexpected decline or active urine sediment suggests an alternative diagnosis.","difficulty":1,"system":"Renal","id":"O141"},{"dx":"Autosomal dominant polycystic kidney disease","patient":"41M","chief":"Flank fullness and hypertension","opening":"He has intermittent flank pressure and early hypertension.","history":"Family history of kidney failure and aneurysms; occasional hematuria.","exam":"Enlarged kidneys may be palpable.","test":"Renal ultrasound or MRI shows multiple bilateral cysts; assess family history.","mechanism":"PKD1/PKD2-associated cyst growth destroys normal parenchyma.","differential":"Simple renal cysts; renal tumor","management":"Control BP, nephrology follow-up and consider disease-modifying treatment if eligible.","redflag":"Screen selectively for intracranial aneurysm risk.","difficulty":2,"system":"Renal","id":"O142"},{"dx":"Chronic kidney disease with uremia","patient":"66M","chief":"Fatigue and itching","opening":"He reports increasing fatigue, itching and poor appetite.","history":"Long history of diabetes, hypertension or renal disease.","exam":"Pallor, edema, possible asterixis in advanced disease.","test":"Persistent low eGFR or kidney damage for over 3 months; electrolyte and anemia workup.","mechanism":"Loss of nephron function causes toxin retention, anemia and mineral abnormalities.","differential":"Acute kidney injury; hepatic failure","management":"Treat complications, kidney protection and plan renal replacement if needed.","redflag":"Uremic pericarditis, refractory hyperkalemia or pulmonary edema indicate urgent dialysis assessment.","difficulty":2,"system":"Renal","id":"O143"},{"dx":"Renal artery stenosis","patient":"73F","chief":"Resistant high blood pressure","opening":"Blood pressure remains high despite several medications.","history":"Atherosclerosis, recurrent flash pulmonary edema or creatinine rise after ACE inhibitor.","exam":"Abdominal bruit may be heard; vascular disease elsewhere.","test":"Duplex renal ultrasound or CTA/MRA depending on kidney function.","mechanism":"Reduced renal perfusion activates RAAS and causes renovascular hypertension.","differential":"Primary hypertension; hyperaldosteronism","management":"Optimize vascular risk and medications; revascularization only selected cases.","redflag":"Bilateral disease may cause marked creatinine change with RAAS blockade.","difficulty":3,"system":"Renal","id":"O144"},{"dx":"Renal cell carcinoma","patient":"61M","chief":"Blood in urine","opening":"He notices intermittent painless visible blood in the urine.","history":"Smoking or obesity risk; weight loss or flank discomfort sometimes.","exam":"Often normal; occasionally abdominal mass.","test":"CT renal protocol imaging and urologic assessment.","mechanism":"Malignant renal tubular tumor can cause hematuria and paraneoplastic effects.","differential":"Bladder cancer; kidney stone","management":"Stage and refer for surgery or other oncologic treatment.","redflag":"Visible hematuria requires malignancy evaluation.","difficulty":2,"system":"Renal","id":"O145"},{"dx":"Bladder carcinoma","patient":"68M","chief":"Painless hematuria","opening":"He has painless bright-red urine without infection symptoms.","history":"Long smoking history or occupational chemical exposure.","exam":"Often normal examination.","test":"Cystoscopy with biopsy and upper-tract imaging according to risk.","mechanism":"Urothelial malignancy frequently presents with painless bleeding.","differential":"Kidney stone; renal cell carcinoma","management":"Urgent urology evaluation and stage-dependent resection/therapy.","redflag":"Never attribute persistent gross hematuria to age alone.","difficulty":1,"system":"Renal","id":"O146"},{"dx":"Interstitial cystitis bladder pain syndrome","patient":"36F","chief":"Bladder pain and urgency","opening":"She has months of suprapubic pain with urinary frequency.","history":"Pain worsens with filling and eases after voiding; cultures repeatedly negative.","exam":"Suprapubic tenderness or pelvic floor tenderness.","test":"Diagnosis based on symptoms after excluding infection and other causes.","mechanism":"Chronic bladder pain signaling occurs without an identifiable bacterial infection.","differential":"Recurrent cystitis; endometriosis","management":"Education, trigger identification and stepped pelvic/bladder pain treatment.","redflag":"Hematuria or systemic signs require further evaluation.","difficulty":3,"system":"Renal","id":"O147"},{"dx":"Nephrolithiasis from cystinuria","patient":"16M","chief":"Repeated kidney stones","opening":"A teenager has recurrent stones since childhood.","history":"Family history of early stones and repeated colic.","exam":"CVA tenderness during attack.","test":"Urine hexagonal crystals, stone analysis and metabolic urine tests.","mechanism":"Defective renal dibasic amino acid transport causes poorly soluble cystine stones.","differential":"Calcium oxalate stones; uric acid stones","management":"High fluid intake, urine alkalinization and specific drugs when required.","redflag":"Recurrent childhood stones should prompt metabolic investigation.","difficulty":3,"system":"Renal","id":"O148"},{"dx":"Uric acid nephrolithiasis","patient":"56M","chief":"Recurrent flank pain","opening":"He experiences repeat episodes of renal colic.","history":"History of gout, metabolic syndrome and low urine pH.","exam":"Restless with flank tenderness during acute episodes.","test":"Urine pH typically low; uric acid stones radiolucent on plain x-ray but seen on CT.","mechanism":"Acidic urine favors uric acid precipitation.","differential":"Calcium oxalate stones; cystine stones","management":"Hydration and urine alkalinization; address uric acid burden.","redflag":"Exclude infected obstruction in febrile patients.","difficulty":2,"system":"Renal","id":"O149"},{"dx":"Distal renal tubular acidosis","patient":"32F","chief":"Weakness and recurrent stones","opening":"She has repeated kidney stones and muscle weakness.","history":"Autoimmune disease or hearing issues possible.","exam":"May have muscle weakness or dehydration.","test":"Normal anion gap metabolic acidosis with inappropriately high urine pH and hypokalemia.","mechanism":"Defective distal hydrogen secretion prevents urinary acidification.","differential":"Proximal renal tubular acidosis; diarrhea","management":"Alkali replacement and potassium correction as needed.","redflag":"Correct severe hypokalemia and look for secondary causes.","difficulty":3,"system":"Renal","id":"O150"},{"dx":"Proximal renal tubular acidosis","patient":"8M","chief":"Poor growth and frequent urination","opening":"A child has slow growth and increased urination.","history":"May have Fanconi syndrome with glucosuria despite normal blood glucose.","exam":"Signs of dehydration or rickets.","test":"Normal anion gap acidosis; bicarbonate wasting, associated tubular losses.","mechanism":"Proximal bicarbonate reabsorption defect causes type 2 RTA.","differential":"Distal renal tubular acidosis; chronic diarrhea","management":"Alkali replacement, correct phosphate/potassium and investigate cause.","redflag":"Look for multisystem proximal tubule defects.","difficulty":3,"system":"Renal","id":"O151"},{"dx":"Type 4 renal tubular acidosis","patient":"65M","chief":"High potassium on labs","opening":"He has persistent hyperkalemia despite modest kidney impairment.","history":"Diabetes, ACE inhibitor or adrenal disease possible.","exam":"Often nonspecific.","test":"Hyperkalemia with normal anion gap acidosis and low/ineffective aldosterone.","mechanism":"Hypoaldosteronism reduces distal potassium and acid excretion.","differential":"Acute kidney injury; medication-induced isolated hyperkalemia","management":"Address drugs and causes, manage potassium and use selected mineralocorticoid therapy.","redflag":"ECG changes from hyperkalemia demand urgent treatment.","difficulty":2,"system":"Renal","id":"O152"},{"dx":"Severe hyperkalemia","patient":"70M","chief":"Weakness and slow heartbeat","opening":"He feels weak after a missed dialysis appointment.","history":"Kidney failure or potassium-raising medications.","exam":"Bradycardia or muscle weakness possible.","test":"Urgent ECG: peaked T waves, widened QRS in severe cases; serum potassium.","mechanism":"Extracellular potassium alters cardiac membrane excitability.","differential":"Heart block; hypocalcemia","management":"IV calcium for ECG toxicity, shift K intracellularly and remove K definitively.","redflag":"Treat ECG toxicity immediately while confirming results.","difficulty":1,"system":"Renal","id":"O153"},{"dx":"Symptomatic hyponatremia","patient":"67F","chief":"Confusion and nausea","opening":"She becomes confused after several days of vomiting and drinking water.","history":"Diuretics or SIADH risks; seizures if severe.","exam":"Altered attention, possible volume signs.","test":"Serum osmolarity, urine osmolarity and urine sodium with volume assessment.","mechanism":"Hypotonic hyponatremia allows water entry into brain cells.","differential":"Hypoglycemia; stroke","management":"Severe neurologic symptoms warrant controlled hypertonic saline and close sodium monitoring.","redflag":"Overly rapid correction risks osmotic demyelination.","difficulty":1,"system":"Renal","id":"O154"},{"dx":"Hemolytic uremic syndrome","patient":"6F","chief":"Decreased urine after diarrhea","opening":"A child develops pallor and low urine output after bloody diarrhea.","history":"Several days after gastroenteritis, fatigue and bruising.","exam":"Pallor, hypertension or edema.","test":"Thrombocytopenia, schistocytes, elevated creatinine; stool Shiga-toxin testing.","mechanism":"Shiga toxin endothelial injury causes microangiopathic hemolysis and AKI.","differential":"TTP; acute glomerulonephritis","management":"Supportive renal/fluid care; dialysis if required, assess specific etiology.","redflag":"Monitor anemia, platelet count and renal deterioration.","difficulty":2,"system":"Renal","id":"O155"},{"dx":"Thrombotic thrombocytopenic purpura","patient":"36F","chief":"Confusion and bruising","opening":"She has unexplained bruising, fatigue and episodic confusion.","history":"May have fever and kidney dysfunction, not always full pentad.","exam":"Petechiae, pallor or focal neurologic findings.","test":"Schistocytes, thrombocytopenia, hemolysis; ADAMTS13 activity testing.","mechanism":"Severe ADAMTS13 deficiency permits platelet-rich microthrombi.","differential":"HUS; disseminated intravascular coagulation","management":"Urgent plasma exchange and disease-specific immunotherapy.","redflag":"Treat on strong clinical suspicion without waiting for ADAMTS13 result.","difficulty":1,"system":"Renal","id":"O156"},{"dx":"Rhabdomyolysis-associated AKI","patient":"28M","chief":"Dark urine after exercise","opening":"After extreme exertion he has severe muscle pain and cola-colored urine.","history":"Recent crush injury, heat stress or intense workout.","exam":"Tender swollen muscles and possible weakness.","test":"Very high CK, urine heme-positive with few RBCs, monitor K/creatinine.","mechanism":"Myoglobin and volume depletion cause tubular toxicity and obstruction.","differential":"Glomerulonephritis; hemolysis","management":"IV fluids tailored to clinical status and monitor renal/electrolyte complications.","redflag":"Hyperkalemia and compartment syndrome are emergencies.","difficulty":1,"system":"Renal","id":"O157"},{"dx":"Tumor lysis syndrome","patient":"27M","chief":"Weakness after chemotherapy","opening":"One day after starting cancer therapy he develops nausea and muscle cramps.","history":"High tumor burden or hematologic malignancy; low urine.","exam":"Tachycardia, dehydration or arrhythmia signs.","test":"High potassium, phosphate and uric acid; low calcium; AKI.","mechanism":"Rapid cell lysis releases intracellular ions and purines causing crystals and arrhythmia.","differential":"Rhabdomyolysis; acute kidney injury","management":"Aggressive prophylaxis/treatment, urate-lowering agents and electrolyte management.","redflag":"Life-threatening arrhythmias and renal failure require urgent treatment.","difficulty":2,"system":"Renal","id":"O158"},{"dx":"Nephrotic syndrome with renal vein thrombosis","patient":"54M","chief":"Flank pain and leg swelling","opening":"A patient with heavy proteinuria develops sudden flank discomfort.","history":"Known nephrotic edema and hypercoagulability.","exam":"Unilateral CVA tenderness and edema possible.","test":"Protein quantification; renal venous imaging with CT/MR/duplex as appropriate.","mechanism":"Urinary anticoagulant protein losses increase venous thrombosis risk.","differential":"Kidney stone; pyelonephritis","management":"Anticoagulation when indicated and treat underlying nephrotic disease.","redflag":"Evaluate for PE and kidney dysfunction.","difficulty":3,"system":"Renal","id":"O159"},{"dx":"Hypertensive nephrosclerosis","patient":"68M","chief":"Slowly worsening kidney numbers","opening":"His kidney function has gradually declined during years of poorly controlled BP.","history":"Longstanding hypertension without heavy proteinuria.","exam":"Hypertensive retinopathy or LVH may coexist.","test":"eGFR trend, urine ACR, ultrasound for chronic changes; exclude other causes.","mechanism":"Chronic small-vessel injury and ischemic glomerulosclerosis reduce nephron mass.","differential":"Diabetic kidney disease; renal artery stenosis","management":"BP control, cardiovascular prevention and CKD management.","redflag":"Unexpected rapid decline or active sediment requires alternate workup.","difficulty":3,"system":"Renal","id":"O160"},{"dx":"Renal papillary necrosis","patient":"59F","chief":"Flank pain and visible blood","opening":"She has flank pain with blood in urine after heavy analgesic use.","history":"Diabetes, sickle cell trait/disease, pyelonephritis or NSAIDs predispose.","exam":"Flank tenderness, may have fever with infection.","test":"CT urography may show papillary abnormalities; urinalysis and renal function.","mechanism":"Ischemia of vulnerable renal papillae leads to sloughing and bleeding.","differential":"Kidney stone; upper-tract malignancy","management":"Stop cause, treat infection or obstruction and obtain urology/nephrology care.","redflag":"Sloughed papilla can obstruct collecting system.","difficulty":3,"system":"Renal","id":"O161"},{"dx":"Postrenal acute kidney injury","patient":"76M","chief":"Low urine output and abdominal fullness","opening":"Urine output falls sharply in a man with longstanding urinary hesitancy.","history":"Nocturia, weak stream and possible drug trigger.","exam":"Suprapubic fullness or bilateral hydronephrosis signs.","test":"Bladder scan and renal ultrasound; rising creatinine.","mechanism":"Bilateral urinary obstruction or bladder outflow blockage raises back pressure.","differential":"Prerenal AKI; acute tubular necrosis","management":"Prompt relieve obstruction and monitor for postobstructive diuresis.","redflag":"Severe retention, infection or hyperkalemia needs urgent care.","difficulty":1,"system":"Renal","id":"O162"},{"dx":"Gastroesophageal reflux disease","patient":"43M","chief":"Burning chest discomfort","opening":"He feels burning behind his breastbone after large meals.","history":"Sour regurgitation, worse lying down, relieved by antacids.","exam":"Usually normal exam.","test":"Typical symptoms often clinical; endoscopy for alarm features or refractory symptoms.","mechanism":"Transient LES relaxation allows gastric acid reflux into esophagus.","differential":"Cardiac ischemia; peptic ulcer disease","management":"Lifestyle changes and acid suppression when appropriate.","redflag":"Dysphagia, bleeding, weight loss or exertional pain need evaluation.","difficulty":1,"system":"GI","id":"O163"},{"dx":"Achalasia","patient":"38F","chief":"Difficulty swallowing","opening":"She has trouble swallowing both liquids and solids.","history":"Regurgitation of undigested food, nocturnal cough, weight loss.","exam":"Usually normal exam except malnutrition in advanced disease.","test":"Barium esophagram bird-beak, manometry confirms absent peristalsis and impaired LES relaxation.","mechanism":"Degeneration of esophageal inhibitory neurons prevents normal relaxation.","differential":"Esophageal cancer; GERD","management":"Endoscopic exclusion of obstruction then pneumatic dilation, POEM or myotomy.","redflag":"New symptoms in older adults require evaluation for pseudoachalasia.","difficulty":2,"system":"GI","id":"O164"},{"dx":"Esophageal carcinoma","patient":"68M","chief":"Progressive difficulty swallowing","opening":"He increasingly struggles to swallow food.","history":"Initially solids then liquids; weight loss, tobacco/alcohol or reflux history.","exam":"Cachexia or supraclavicular nodes in advanced disease.","test":"Urgent upper endoscopy with biopsy and staging.","mechanism":"Malignant narrowing causes progressive mechanical dysphagia.","differential":"Achalasia; benign peptic stricture","management":"Urgent specialist staging and multidisciplinary treatment.","redflag":"Progressive dysphagia and weight loss are alarm findings.","difficulty":1,"system":"GI","id":"O165"},{"dx":"Candida esophagitis","patient":"35M","chief":"Painful swallowing","opening":"Swallowing now causes sharp pain behind the sternum.","history":"Advanced immunosuppression or inhaled steroid use, oral thrush possible.","exam":"White oral plaques may be present.","test":"Endoscopy shows adherent plaques when diagnosis uncertain.","mechanism":"Fungal infection inflames esophageal mucosa, causing odynophagia.","differential":"Pill esophagitis; herpes esophagitis","management":"Systemic antifungal therapy and evaluate immunosuppression.","redflag":"Severe odynophagia and inability to hydrate need urgent assessment.","difficulty":2,"system":"GI","id":"O166"},{"dx":"Mallory-Weiss tear","patient":"29M","chief":"Vomiting blood","opening":"He vomits a small amount of bright blood after repeated retching.","history":"Binge alcohol or gastroenteritis followed by forceful vomiting.","exam":"May have epigastric tenderness and volume depletion.","test":"Upper endoscopy if bleeding significant or persistent.","mechanism":"Longitudinal mucosal laceration at gastroesophageal junction follows retching.","differential":"Peptic ulcer bleed; Boerhaave syndrome","management":"Resuscitate as needed, antiemetic and endoscopic hemostasis if persistent.","redflag":"Severe chest pain or mediastinal air points to rupture rather than tear.","difficulty":2,"system":"GI","id":"O167"},{"dx":"Boerhaave syndrome","patient":"52M","chief":"Severe chest pain after vomiting","opening":"After forceful vomiting he develops abrupt excruciating chest pain.","history":"Dyspnea, fever and rapid deterioration after emesis.","exam":"Toxic, tachycardic, subcutaneous emphysema may be present.","test":"Urgent CT chest with water-soluble contrast/CT esophagography under specialist guidance.","mechanism":"Full-thickness esophageal rupture contaminates mediastinum.","differential":"Mallory-Weiss tear; myocardial infarction","management":"NPO, IV antibiotics, resuscitation and emergency surgical/endoscopic consultation.","redflag":"Missed rupture can rapidly cause mediastinitis and shock.","difficulty":1,"system":"GI","id":"O168"},{"dx":"Peptic ulcer disease","patient":"47M","chief":"Upper abdominal pain","opening":"He has episodic epigastric discomfort.","history":"NSAID use or H pylori exposure; pain related variably to meals.","exam":"Epigastric tenderness, may be normal.","test":"H pylori stool antigen/breath test; endoscopy with alarm features.","mechanism":"Acid-peptic injury breaches gastroduodenal mucosal defenses.","differential":"GERD; functional dyspepsia","management":"Eradicate H pylori if positive, avoid NSAIDs and use PPI.","redflag":"Perforation or major GI bleed requires urgent intervention.","difficulty":1,"system":"GI","id":"O169"},{"dx":"Upper gastrointestinal hemorrhage","patient":"71F","chief":"Black stools and dizziness","opening":"She notices black tarry stools and becomes lightheaded.","history":"NSAID or anticoagulant use, ulcer or variceal risk.","exam":"Tachycardia, orthostatic hypotension and melena.","test":"CBC, type and cross, BUN/creatinine, urgent upper endoscopy after stabilization.","mechanism":"Bleeding proximal to ligament of Treitz commonly causes melena.","differential":"Lower GI bleed; iron supplements","management":"Resuscitation, risk stratification, PPI if nonvariceal suspected and early endoscopy.","redflag":"Hemodynamic instability requires immediate resuscitation.","difficulty":1,"system":"GI","id":"O170"},{"dx":"NSAID gastritis","patient":"60M","chief":"Gnawing stomach pain","opening":"He has new epigastric discomfort after taking ibuprofen daily.","history":"Medication dose, alcohol and prior ulcer risk.","exam":"Mild epigastric tenderness without peritonitis.","test":"Usually clinical, test H pylori or endoscopy if alarm features.","mechanism":"NSAID inhibition of prostaglandins reduces protective gastric mucus and blood flow.","differential":"Peptic ulcer disease; gallstone disease","management":"Stop offending NSAID if possible and use acid suppression.","redflag":"Black stool or hematemesis implies bleeding complication.","difficulty":1,"system":"GI","id":"O171"},{"dx":"Gastric outlet obstruction","patient":"65M","chief":"Persistent vomiting","opening":"He vomits large meals several hours after eating.","history":"Early satiety, weight loss, ulcer or cancer history.","exam":"Succussion splash, dehydration or distension possible.","test":"CT and upper endoscopy after stabilization.","mechanism":"Mechanical blockage prevents gastric emptying.","differential":"Gastroparesis; small bowel obstruction","management":"IV fluids, gastric decompression if needed and treat underlying obstruction.","redflag":"Malignancy needs exclusion in new adult obstruction.","difficulty":3,"system":"GI","id":"O172"},{"dx":"Biliary colic","patient":"39F","chief":"Pain after fatty meal","opening":"She has episodic right upper abdominal pain after dinner.","history":"Episodes last under several hours, no fever or persistent vomiting.","exam":"Minimal RUQ tenderness between attacks, negative Murphy sign.","test":"RUQ ultrasound shows gallstones without inflammation.","mechanism":"Transient cystic duct obstruction causes episodic visceral pain.","differential":"Acute cholecystitis; peptic ulcer disease","management":"Analgesia and elective surgical consultation for symptomatic stones.","redflag":"Fever, jaundice or pain lasting more than 6 hours suggests complication.","difficulty":1,"system":"GI","id":"O173"},{"dx":"Acute cholecystitis","patient":"48F","chief":"Persistent right upper abdominal pain","opening":"Severe RUQ pain continues since last night.","history":"Nausea, fever and history of postmeal episodes.","exam":"Positive Murphy sign and RUQ guarding.","test":"RUQ ultrasound shows stones, wall thickening or pericholecystic fluid.","mechanism":"Persistent cystic duct obstruction inflames gallbladder.","differential":"Biliary colic; acute cholangitis","management":"IV fluids, antibiotics when indicated and early cholecystectomy.","redflag":"Sepsis or perforation changes urgency.","difficulty":1,"system":"GI","id":"O174"},{"dx":"Choledocholithiasis","patient":"56M","chief":"Pain and yellow eyes","opening":"He has intermittent RUQ pain with new jaundice.","history":"Dark urine, pale stool and known gallstones.","exam":"Icterus and RUQ tenderness, often afebrile.","test":"Cholestatic labs; ultrasound duct dilation and MRCP/EUS if needed.","mechanism":"Stone in common bile duct obstructs bile flow.","differential":"Acute cholecystitis; pancreatic cancer","management":"Risk-based ERCP for confirmed/high-risk stones followed by gallbladder management.","redflag":"Fever with jaundice suggests ascending cholangitis.","difficulty":2,"system":"GI","id":"O175"},{"dx":"Ascending cholangitis","patient":"68F","chief":"Fever and jaundice","opening":"She develops fever, right upper abdominal pain and jaundice.","history":"May have hypotension or altered mental status in severe illness.","exam":"Fever, icterus and RUQ tenderness; shock in severe cases.","test":"Cholestatic labs, cultures, ultrasound/CT for biliary obstruction.","mechanism":"Infected obstructed biliary tree can cause sepsis.","differential":"Choledocholithiasis without infection; acute hepatitis","management":"Immediate IV antibiotics, resuscitation and urgent biliary drainage/ERCP.","redflag":"Charcot triad and Reynold pentad signal a potentially fatal emergency.","difficulty":1,"system":"GI","id":"O176"},{"dx":"Acute pancreatitis","patient":"45M","chief":"Severe upper abdominal pain","opening":"Pain radiates from the epigastrium into his back.","history":"Heavy alcohol exposure or gallstones; nausea and vomiting.","exam":"Epigastric tenderness, reduced bowel sounds.","test":"Lipase usually over three times upper limit of normal; ultrasound for gallstones.","mechanism":"Premature pancreatic enzyme activation causes autodigestion/inflammation.","differential":"Perforated ulcer; biliary colic","management":"IV fluids tailored to status, analgesia, early enteral nutrition when tolerated and treat cause.","redflag":"Assess organ failure, biliary obstruction and shock.","difficulty":1,"system":"GI","id":"O177"},{"dx":"Chronic pancreatitis","patient":"53M","chief":"Chronic abdominal pain and diarrhea","opening":"He has recurrent epigastric pain, oily stools and weight loss.","history":"Long alcohol history or recurrent acute pancreatitis.","exam":"Malnutrition and epigastric tenderness.","test":"CT pancreatic calcifications; fecal elastase can assess insufficiency.","mechanism":"Progressive pancreatic fibrosis destroys exocrine and endocrine function.","differential":"Pancreatic cancer; celiac disease","management":"Alcohol/tobacco cessation, enzyme replacement and pain/nutrition support.","redflag":"New weight loss can also indicate malignancy.","difficulty":2,"system":"GI","id":"O178"},{"dx":"Pancreatic adenocarcinoma","patient":"70F","chief":"Painless jaundice and weight loss","opening":"She has noticed yellow skin, dark urine and marked weight loss.","history":"Poor appetite, painless jaundice and sometimes new diabetes.","exam":"Icterus; palpable nontender gallbladder possible.","test":"Pancreatic-protocol CT and tissue diagnosis for treatment planning.","mechanism":"Pancreatic head mass can obstruct common bile duct.","differential":"Choledocholithiasis; cholangiocarcinoma","management":"Urgent hepatopancreatobiliary/oncology referral and staging.","redflag":"Unexplained painless jaundice is a cancer red flag.","difficulty":1,"system":"GI","id":"O179"},{"dx":"Acute appendicitis","patient":"19M","chief":"Migrating abdominal pain","opening":"Pain started near the belly button and moved lower right.","history":"Loss of appetite, nausea and low fever.","exam":"RLQ McBurney tenderness, rebound or guarding if peritoneal irritation.","test":"CBC, pregnancy test if applicable; ultrasound or CT by patient context.","mechanism":"Luminal obstruction inflames appendix and can progress to perforation.","differential":"Gastroenteritis; ovarian torsion","management":"NPO, analgesia, surgical consult and antibiotics/surgery as indicated.","redflag":"Pregnancy-related emergencies must be considered when relevant.","difficulty":1,"system":"GI","id":"O180"},{"dx":"Acute diverticulitis","patient":"61F","chief":"Left lower abdominal pain","opening":"A steady left lower abdominal ache developed yesterday.","history":"Fever, change in bowel habits; prior diverticulosis.","exam":"LLQ tenderness, possibly low-grade fever.","test":"CT abdomen/pelvis when needed to confirm and stage complications.","mechanism":"Inflammation of colonic diverticula, commonly sigmoid.","differential":"Colon cancer; ischemic colitis","management":"Analgesia, selective antibiotics based on severity/risk and follow-up.","redflag":"Peritonitis, abscess or obstruction is complicated disease.","difficulty":1,"system":"GI","id":"O181"},{"dx":"Diverticular hemorrhage","patient":"74M","chief":"Large amount of red blood in stool","opening":"He passes painless bright-red blood in the toilet.","history":"Known diverticulosis, aspirin use; no major pain.","exam":"May be tachycardic if heavy bleeding; abdomen soft.","test":"CBC, hemodynamic evaluation, colonoscopy or CTA for active severe bleed.","mechanism":"Diverticular vessel erosion causes abrupt painless lower GI bleeding.","differential":"Hemorrhoids; ischemic colitis","management":"Resuscitate and localize bleeding; endoscopic/interventional hemostasis if needed.","redflag":"Large-volume bleeding can cause shock despite little pain.","difficulty":2,"system":"GI","id":"O182"},{"dx":"Ischemic colitis","patient":"73F","chief":"Bloody diarrhea and cramps","opening":"She develops crampy left abdominal pain followed by blood in stool.","history":"Recent hypotension, vascular disease or dehydration.","exam":"LLQ tenderness usually without severe peritoneal signs.","test":"CT may show segmental colitis; colonoscopy when appropriate.","mechanism":"Transient low blood flow injures watershed colon mucosa.","differential":"Infectious colitis; ulcerative colitis","management":"Fluids, bowel rest and address precipitant; surgery if gangrene/perforation.","redflag":"Severe pain out of proportion suggests mesenteric ischemia.","difficulty":2,"system":"GI","id":"O183"},{"dx":"Acute mesenteric ischemia","patient":"77M","chief":"Severe abdominal pain","opening":"He has sudden intense abdominal pain with surprisingly little tenderness.","history":"Atrial fibrillation or vascular disease; possible diarrhea or bloody stool.","exam":"Pain out of proportion early; peritoneal signs late.","test":"Urgent CT angiography and lactate assessment, without delaying care.","mechanism":"Acute intestinal arterial occlusion causes bowel infarction.","differential":"Gastroenteritis; ischemic colitis","management":"Resuscitation, broad antibiotics, anticoagulation when appropriate and emergency vascular/surgical intervention.","redflag":"Time-to-revascularization determines bowel survival.","difficulty":1,"system":"GI","id":"O184"},{"dx":"Crohn disease","patient":"24F","chief":"Chronic diarrhea and cramps","opening":"She has months of diarrhea, RLQ pain and weight loss.","history":"Perianal symptoms, mouth ulcers and family history.","exam":"RLQ tenderness, perianal fistula or skin findings.","test":"Fecal calprotectin, ileocolonoscopy with biopsy and small-bowel imaging.","mechanism":"Transmural discontinuous inflammation can affect mouth to anus.","differential":"Ulcerative colitis; irritable bowel syndrome","management":"Gastroenterology-directed anti-inflammatory or biologic therapy and nutritional care.","redflag":"Fistula, abscess or obstruction may complicate disease.","difficulty":1,"system":"GI","id":"O185"},{"dx":"Ulcerative colitis","patient":"28M","chief":"Bloody diarrhea","opening":"He has frequent urgent bloody stools and cramping.","history":"Tenesmus and symptoms starting at rectum; possible extraintestinal manifestations.","exam":"LLQ tenderness, pallor or dehydration if severe.","test":"Colonoscopy with biopsy shows continuous mucosal inflammation from rectum.","mechanism":"Immune-mediated colonic mucosal disease causes hematochezia and urgency.","differential":"Crohn disease; infectious colitis","management":"Disease-severity-directed mesalamine or immunotherapy, monitor colorectal cancer risk.","redflag":"Severe colitis with fever/distention raises toxic megacolon concern.","difficulty":1,"system":"GI","id":"O186"},{"dx":"Irritable bowel syndrome","patient":"30F","chief":"Recurring abdominal cramps","opening":"She has abdominal pain that improves after defecation.","history":"Months of pain associated with altered stool frequency or form; no alarm signs.","exam":"Normal or mildly tender abdomen without peritonitis.","test":"Positive symptom-based diagnosis after limited targeted exclusion tests.","mechanism":"Disorder of gut-brain interaction alters motility and visceral sensation.","differential":"Celiac disease; inflammatory bowel disease","management":"Dietary intervention, symptom-directed medication and stress/sleep support.","redflag":"Bleeding, anemia, nocturnal symptoms or weight loss need further workup.","difficulty":1,"system":"GI","id":"O187"},{"dx":"Celiac disease","patient":"27F","chief":"Chronic diarrhea and fatigue","opening":"She has loose stools, bloating and low energy for months.","history":"Iron-deficiency anemia, weight loss or dermatitis herpetiformis.","exam":"Pallor, mouth ulcers or pruritic extensor rash.","test":"tTG-IgA and total IgA while eating gluten; duodenal biopsy as indicated.","mechanism":"Gluten-driven autoimmune small-bowel villous atrophy reduces nutrient absorption.","differential":"IBS; lactose intolerance","management":"Lifelong gluten-free diet after appropriate diagnostic confirmation.","redflag":"Do not start gluten exclusion before testing if diagnosis unconfirmed.","difficulty":2,"system":"GI","id":"O188"},{"dx":"Lactose intolerance","patient":"22M","chief":"Bloating after dairy","opening":"He develops gas and watery diarrhea after ice cream.","history":"Symptoms closely follow milk products, no blood or fever.","exam":"Usually normal between episodes.","test":"Diet trial or hydrogen breath test if needed.","mechanism":"Reduced intestinal lactase causes osmotic diarrhea and fermentation.","differential":"Celiac disease; irritable bowel syndrome","management":"Limit lactose or use lactase supplements while preserving calcium intake.","redflag":"Weight loss or bloody diarrhea warrants alternative workup.","difficulty":1,"system":"GI","id":"O189"},{"dx":"Viral gastroenteritis","patient":"21F","chief":"Vomiting and diarrhea","opening":"Several classmates develop vomiting and watery diarrhea.","history":"Abrupt onset after shared exposure, no blood and limited duration.","exam":"Mild dehydration, diffuse cramps, no focal peritonitis.","test":"Clinical diagnosis; electrolytes if significant dehydration.","mechanism":"Viral enteritis causes transient fluid loss and inflammation.","differential":"Food poisoning; bacterial dysentery","management":"Oral rehydration and supportive care; infection control.","redflag":"Severe dehydration or bloody stool requires reassessment.","difficulty":1,"system":"GI","id":"O190"},{"dx":"Clostridioides difficile colitis","patient":"68F","chief":"Watery diarrhea after antibiotics","opening":"She has frequent watery stools after a recent hospital stay.","history":"Recent antibiotic use; fever and crampy pain.","exam":"Abdominal tenderness, may have leukocytosis.","test":"Stool NAAT/toxin algorithm only for clinically compatible diarrhea.","mechanism":"Antibiotic disruption permits toxigenic C difficile colitis.","differential":"Viral gastroenteritis; inflammatory bowel disease","management":"Stop unnecessary inciting antibiotic, treat with guideline-preferred oral agent.","redflag":"Ileus, hypotension or megacolon indicates fulminant disease.","difficulty":1,"system":"GI","id":"O191"},{"dx":"Colorectal carcinoma","patient":"62M","chief":"Change in bowel habits","opening":"He reports narrowing stools, fatigue and occasional bleeding.","history":"Weight loss, family history or iron deficiency.","exam":"Pallor, possible abdominal mass; rectal exam when indicated.","test":"Colonoscopy with biopsy and staging CT.","mechanism":"Malignant colonic growth can bleed or obstruct.","differential":"Hemorrhoids; inflammatory bowel disease","management":"Urgent colonoscopy and oncology/surgical staging.","redflag":"Iron-deficiency anemia in adult requires GI evaluation.","difficulty":1,"system":"GI","id":"O192"},{"dx":"Internal hemorrhoids","patient":"36F","chief":"Blood on toilet paper","opening":"Bright-red bleeding occurs after bowel movements with little pain.","history":"Constipation and straining; blood coats rather than mixes with stool.","exam":"Internal cushions on anoscopy, often painless.","test":"Anorectal exam; age/risk-based further colorectal evaluation.","mechanism":"Enlarged vascular cushions bleed with defecation.","differential":"Anal fissure; colorectal cancer","management":"Fiber, hydration and reduce straining; office intervention if persistent.","redflag":"Do not dismiss rectal bleeding without evaluating cancer risk.","difficulty":1,"system":"GI","id":"O193"},{"dx":"Anal fissure","patient":"33M","chief":"Pain with bowel movements","opening":"He experiences tearing pain and a small amount of red blood.","history":"Hard stools and persistent pain after defecation.","exam":"Linear posterior midline tear on gentle inspection.","test":"Clinical exam; avoid painful digital exam if not needed.","mechanism":"Trauma and internal sphincter spasm sustain mucosal tear.","differential":"Hemorrhoids; perianal abscess","management":"Stool softening, sitz baths and topical sphincter relaxants when indicated.","redflag":"Lateral/multiple fissures suggest an underlying disorder.","difficulty":1,"system":"GI","id":"O194"},{"dx":"Perianal abscess","patient":"46M","chief":"Severe anal pain","opening":"Pain near the anus worsens with sitting and he has fever.","history":"Rapidly progressive focal pain, possible Crohn disease.","exam":"Tender red fluctuant perianal swelling.","test":"Usually clinical; imaging for deep or complex abscess.","mechanism":"Blocked anal glands form purulent collection.","differential":"Hemorrhoid thrombosis; anal fissure","management":"Prompt incision and drainage with antibiotics in selected patients.","redflag":"Systemic toxicity or deep perirectal infection is urgent.","difficulty":2,"system":"GI","id":"O195"},{"dx":"Small bowel obstruction","patient":"63F","chief":"Vomiting and swollen abdomen","opening":"She has colicky abdominal pain, vomiting and cannot pass gas.","history":"Prior abdominal surgery, progressive distention.","exam":"Distended tympanitic abdomen, high-pitched sounds early.","test":"CT abdomen/pelvis identifies transition point and complications.","mechanism":"Adhesions or hernia physically block intestinal transit.","differential":"Ileus; gastroenteritis","management":"NPO, IV fluids, nasogastric decompression when indicated and surgical assessment.","redflag":"Peritonitis, ischemia or strangulation needs urgent operation.","difficulty":1,"system":"GI","id":"O196"},{"dx":"Sigmoid volvulus","patient":"79M","chief":"Severe distention and constipation","opening":"His abdomen is markedly distended and he has not passed stool.","history":"Chronic constipation or neurologic disease.","exam":"Tympanic distended abdomen and colicky pain.","test":"X-ray coffee-bean sign, CT if uncertain.","mechanism":"Twisting of sigmoid colon causes closed-loop obstruction.","differential":"Small bowel obstruction; fecal impaction","management":"Urgent endoscopic detorsion if no ischemia/perforation, then definitive planning.","redflag":"Peritonitis or ischemia mandates surgery.","difficulty":2,"system":"GI","id":"O197"},{"dx":"Intussusception","patient":"11moM","chief":"Episodes of severe abdominal pain","opening":"An infant suddenly cries and draws his knees to his chest repeatedly.","history":"Intermittent episodes, vomiting; late currant-jelly stools.","exam":"Possible sausage-shaped mass, periods of apparent wellness.","test":"Abdominal ultrasound target sign.","mechanism":"Telescoping bowel obstructs lumen and compromises mesenteric blood flow.","differential":"Gastroenteritis; malrotation","management":"Urgent air/contrast enema reduction if stable and no perforation.","redflag":"Shock or peritonitis requires emergent surgical involvement.","difficulty":1,"system":"GI","id":"O198"},{"dx":"Acute hepatitis A","patient":"24F","chief":"Nausea and jaundice","opening":"She develops fatigue, nausea and yellow eyes after travel.","history":"Food/water exposure and preceding viral prodrome.","exam":"Hepatomegaly, scleral icterus and RUQ discomfort.","test":"Marked hepatocellular aminotransferase elevation and HAV IgM.","mechanism":"Fecal-oral viral hepatitis causes acute hepatocellular injury.","differential":"Hepatitis B; biliary obstruction","management":"Supportive care, exposure prevention and public health actions.","redflag":"Encephalopathy or coagulopathy suggests acute liver failure.","difficulty":1,"system":"GI","id":"O199"},{"dx":"Acute hepatitis B","patient":"30M","chief":"Fatigue and dark urine","opening":"He has nausea, arthralgia and jaundice after new sexual exposure.","history":"Unprotected sex, injection drug exposure; variable incubation.","exam":"Jaundice and tender liver.","test":"HBsAg and IgM anti-HBc with hepatocellular lab pattern.","mechanism":"Blood/body-fluid transmitted HBV can produce acute immune-mediated hepatitis.","differential":"Hepatitis A; drug-induced hepatitis","management":"Supportive care in most acute cases, monitoring and prevention counseling.","redflag":"Watch for fulminant hepatic failure and chronic infection risk.","difficulty":2,"system":"GI","id":"O200"},{"dx":"Decompensated cirrhosis with ascites","patient":"58M","chief":"Abdominal swelling","opening":"His abdomen has steadily enlarged with ankle edema.","history":"Chronic alcohol use or viral/metabolic liver disease; early satiety.","exam":"Shifting dullness, spider angiomata, muscle wasting.","test":"Diagnostic paracentesis for new/worsening ascites, SAAG and infection evaluation.","mechanism":"Portal hypertension and low effective arterial volume cause sodium retention.","differential":"Heart failure; malignant ascites","management":"Salt restriction, diuretics and paracentesis as indicated; hepatology evaluation.","redflag":"Every hospitalized cirrhotic with ascites needs prompt infection evaluation.","difficulty":1,"system":"GI","id":"O201"},{"dx":"Hepatic encephalopathy","patient":"61F","chief":"New confusion","opening":"A patient with known liver disease becomes sleepy and disoriented.","history":"Constipation, GI bleeding, infection or sedating drugs trigger episode.","exam":"Asterixis and altered attention; no single sign is definitive.","test":"Clinical diagnosis after excluding mimics; assess precipitant and electrolytes.","mechanism":"Ammonia and neurotoxins bypass failing hepatic clearance and affect brain function.","differential":"Stroke; hypoglycemia","management":"Treat trigger, lactulose titrated clinically and rifaximin when indicated.","redflag":"Protect airway and rule out intracranial causes in altered patients.","difficulty":2,"system":"GI","id":"O202"},{"dx":"Spontaneous bacterial peritonitis","patient":"54M","chief":"Fever and abdominal discomfort","opening":"A patient with ascites develops fever, mild pain and confusion.","history":"Known cirrhosis; symptoms may be subtle or absent.","exam":"Ascites and diffuse tenderness, sometimes no guarding.","test":"Urgent paracentesis with PMN count at least 250 cells/mm3; culture.","mechanism":"Bacterial translocation infects ascitic fluid without surgical source.","differential":"Secondary bacterial peritonitis; sterile ascites","management":"Prompt IV antibiotics and albumin in indicated patients.","redflag":"Do not delay diagnostic paracentesis for imaging in stable cases.","difficulty":1,"system":"GI","id":"O203"},{"dx":"Metabolic dysfunction-associated steatotic liver disease","patient":"51F","chief":"High liver enzymes","opening":"Routine testing reveals elevated ALT in a patient with central obesity.","history":"Diabetes, dyslipidemia and little alcohol exposure.","exam":"Often normal exam or hepatomegaly.","test":"Exclude alternate causes, ultrasound or elastography; fibrosis risk scoring.","mechanism":"Insulin resistance promotes hepatic steatosis with possible inflammation/fibrosis.","differential":"Alcohol-associated liver disease; viral hepatitis","management":"Weight loss, metabolic risk treatment and fibrosis-based referral.","redflag":"Normal aminotransferases do not exclude advanced fibrosis.","difficulty":2,"system":"GI","id":"O204"},{"dx":"Hereditary hemochromatosis","patient":"49M","chief":"Fatigue and joint pain","opening":"He has fatigue, hand-joint pain and newly diagnosed diabetes.","history":"Family history, bronze skin or liver symptoms possible.","exam":"Hepatomegaly, MCP arthropathy and hyperpigmentation.","test":"Transferrin saturation and ferritin, HFE testing in appropriate setting.","mechanism":"Increased intestinal iron absorption deposits iron in organs.","differential":"Chronic hepatitis; metabolic liver disease","management":"Therapeutic phlebotomy and family screening when indicated.","redflag":"Assess liver fibrosis and cardiac/endocrine damage.","difficulty":3,"system":"GI","id":"O205"},{"dx":"Wilson disease","patient":"18F","chief":"Abnormal movements and jaundice","opening":"A teen has new tremor, behavioral change and liver abnormalities.","history":"Psychiatric change, dysarthria or family history.","exam":"Tremor and possible Kayser-Fleischer rings.","test":"Ceruloplasmin, urinary copper and specialist assessment.","mechanism":"ATP7B defect prevents hepatic copper excretion, damaging liver and brain.","differential":"Huntington disease; hepatitis","management":"Chelation or zinc under specialist care and family evaluation.","redflag":"Young patient with unexplained liver plus neurologic disease needs workup.","difficulty":3,"system":"GI","id":"O206"},{"dx":"Primary biliary cholangitis","patient":"52F","chief":"Itching and fatigue","opening":"She has chronic itching with abnormal liver tests.","history":"Fatigue, sicca symptoms and autoimmune history.","exam":"Excoriations, sometimes xanthelasma.","test":"Cholestatic ALP elevation and antimitochondrial antibodies.","mechanism":"Autoimmune destruction of intrahepatic small bile ducts causes cholestasis.","differential":"Primary sclerosing cholangitis; biliary obstruction","management":"Ursodeoxycholic acid and monitor complications.","redflag":"Consider osteoporosis and fat-soluble vitamin issues in advanced disease.","difficulty":2,"system":"GI","id":"O207"},{"dx":"Primary sclerosing cholangitis","patient":"33M","chief":"Itching and abnormal liver enzymes","opening":"A man with longstanding colitis develops cholestatic liver tests.","history":"Pruritus, fatigue or episodes of cholangitis; inflammatory bowel disease.","exam":"Jaundice or hepatomegaly may appear.","test":"MRCP with multifocal strictures and beading after excluding secondary causes.","mechanism":"Fibroinflammatory injury of intra- and extrahepatic bile ducts causes strictures.","differential":"Primary biliary cholangitis; cholangiocarcinoma","management":"Hepatology surveillance and management of strictures and complications.","redflag":"Increased cholangiocarcinoma and colorectal cancer risk.","difficulty":3,"system":"GI","id":"O208"},{"dx":"Acute ischemic stroke","patient":"72M","chief":"Sudden arm weakness and speech trouble","opening":"His right arm became weak and speech slurred 25 minutes ago.","history":"Exact last-known-well time, anticoagulants, vascular risk and associated deficits.","exam":"Unilateral weakness, facial droop, aphasia or neglect depending on territory.","test":"Fingerstick glucose, emergent noncontrast head CT and vascular imaging per pathway.","mechanism":"Arterial occlusion deprives brain of oxygen, causing focal deficits.","differential":"Hypoglycemia; intracerebral hemorrhage","management":"Activate stroke pathway for thrombolysis/thrombectomy eligibility and supportive care.","redflag":"Time-dependent emergency; do not delay imaging.","difficulty":1,"system":"Neuro","id":"O209"},{"dx":"Posterior circulation stroke","patient":"66F","chief":"Dizziness and trouble walking","opening":"She suddenly develops vertigo, double vision and inability to stand.","history":"Abrupt onset, headache, weakness or swallowing difficulty possible.","exam":"Limb/truncal ataxia, dysarthria, gaze abnormalities and possible crossed signs.","test":"Urgent stroke assessment with CT/CTA and MRI when appropriate.","mechanism":"Vertebrobasilar ischemia affects brainstem or cerebellum.","differential":"Vestibular neuritis; BPPV","management":"Immediate stroke pathway and reperfusion eligibility evaluation.","redflag":"Posterior strokes can lack obvious arm weakness and early CT can be negative.","difficulty":2,"system":"Neuro","id":"O210"},{"dx":"Transient ischemic attack","patient":"69M","chief":"Brief speech difficulty","opening":"He was unable to find words for ten minutes but now feels normal.","history":"Abrupt transient focal deficit; vascular risk factors.","exam":"Normal exam after resolution.","test":"Urgent brain/vascular imaging, ECG and risk evaluation.","mechanism":"Transient focal cerebral ischemia warns of imminent stroke.","differential":"Migraine aura; focal seizure","management":"Urgent stroke-prevention workup and appropriate antithrombotic/vascular management.","redflag":"Resolution of symptoms does not eliminate emergency risk.","difficulty":1,"system":"Neuro","id":"O211"},{"dx":"Intracerebral hemorrhage","patient":"74F","chief":"Sudden weakness and headache","opening":"She develops sudden weakness, vomiting and severe headache.","history":"Hypertension or anticoagulants; progressively impaired consciousness.","exam":"Focal deficit with possible reduced alertness and high BP.","test":"Emergency noncontrast CT head shows parenchymal blood.","mechanism":"Ruptured intracerebral vessel causes mass effect and tissue injury.","differential":"Ischemic stroke; brain tumor","management":"Stroke/neurosurgical management, BP control and anticoagulant reversal when indicated.","redflag":"Never give thrombolytic before excluding hemorrhage.","difficulty":1,"system":"Neuro","id":"O212"},{"dx":"Subarachnoid hemorrhage","patient":"46F","chief":"Worst headache of life","opening":"A thunderclap headache reaches maximum intensity instantly.","history":"Exertional onset, neck stiffness, vomiting or brief collapse.","exam":"Meningismus or neurologic deficit; exam may initially be normal.","test":"Emergency noncontrast CT; LP/vascular imaging if needed per timing and risk.","mechanism":"Ruptured intracranial aneurysm bleeds into subarachnoid space.","differential":"Migraine; meningitis","management":"Urgent neurosurgical/neurovascular care and aneurysm management.","redflag":"A normal exam does not exclude aneurysmal SAH.","difficulty":1,"system":"Neuro","id":"O213"},{"dx":"Subdural hematoma","patient":"78M","chief":"Confusion after fall","opening":"After a minor fall last week he becomes increasingly confused.","history":"Anticoagulant use, headache and delayed deterioration.","exam":"Variable cognitive changes or unilateral weakness.","test":"Noncontrast head CT shows crescentic extra-axial collection.","mechanism":"Torn bridging veins cause blood between dura and arachnoid.","differential":"Epidural hematoma; delirium","management":"Urgent neurosurgical evaluation and reversal of anticoagulation as indicated.","redflag":"Slow onset does not make an intracranial bleed benign.","difficulty":1,"system":"Neuro","id":"O214"},{"dx":"Epidural hematoma","patient":"19M","chief":"Head injury with deterioration","opening":"After being knocked unconscious he briefly improves, then becomes drowsy.","history":"High-energy temporal head impact.","exam":"Declining GCS, unequal pupils or focal deficit.","test":"Emergency noncontrast CT shows biconvex extra-axial blood.","mechanism":"Middle meningeal artery injury causes rapidly expanding epidural hemorrhage.","differential":"Subdural hematoma; concussion","management":"Immediate resuscitation and neurosurgical evacuation assessment.","redflag":"Potential rapid herniation: time-critical emergency.","difficulty":1,"system":"Neuro","id":"O215"},{"dx":"Migraine with aura","patient":"24F","chief":"Recurrent one-sided headache","opening":"She has pulsating headaches preceded by shimmering visual patterns.","history":"Nausea, photophobia; visual aura develops over minutes and resolves.","exam":"Neurologic exam normal between attacks.","test":"Clinical diagnosis when typical; image only for red flags or atypical features.","mechanism":"Cortical spreading depolarization produces aura and trigeminovascular activation causes pain.","differential":"TIA; tension headache","management":"Acute migraine-specific therapy and prevention if frequent.","redflag":"Sudden maximal headache or persistent focal deficit needs evaluation.","difficulty":1,"system":"Neuro","id":"O216"},{"dx":"Cluster headache","patient":"35M","chief":"Severe pain around one eye","opening":"Excruciating attacks around the right eye last about an hour.","history":"Recur at same time daily; restlessness, ipsilateral tearing and nasal congestion.","exam":"Ipsilateral ptosis, conjunctival injection during attack.","test":"Clinical pattern; image if atypical or secondary concern.","mechanism":"Trigeminal autonomic cephalalgia causes brief severe unilateral attacks.","differential":"Migraine; acute angle-closure glaucoma","management":"High-flow oxygen and subcutaneous/intranasal triptan; preventive verapamil with monitoring.","redflag":"Eye pain plus visual loss needs ocular emergency evaluation.","difficulty":2,"system":"Neuro","id":"O217"},{"dx":"Tension-type headache","patient":"29F","chief":"Band-like headache","opening":"She has mild to moderate bilateral pressure late in the day.","history":"Stress and poor sleep, no vomiting or major disability.","exam":"Normal neurologic exam and no meningeal signs.","test":"Clinical after excluding red flags.","mechanism":"Pericranial muscular and central pain pathways produce pressing headache.","differential":"Migraine; medication overuse headache","management":"Sleep/stress management and limited simple analgesia.","redflag":"New neurologic signs, fever or thunderclap onset are red flags.","difficulty":1,"system":"Neuro","id":"O218"},{"dx":"Bacterial meningitis","patient":"20M","chief":"Fever and stiff neck","opening":"He develops fever, headache and neck stiffness over one day.","history":"Photophobia, vomiting, altered mentation; close living exposure.","exam":"Febrile, meningismus, possible petechiae or confusion.","test":"Blood cultures, urgent LP when safe; CT before LP only if indicated.","mechanism":"Bacterial meningeal inflammation can rapidly progress to sepsis/brain injury.","differential":"Viral meningitis; subarachnoid hemorrhage","management":"Immediate empiric IV antibiotics and indicated dexamethasone; do not delay for LP.","redflag":"Time-critical emergency with potential airway compromise.","difficulty":1,"system":"Neuro","id":"O219"},{"dx":"Herpes simplex encephalitis","patient":"37F","chief":"Fever and unusual behavior","opening":"She has fever and sudden personality changes with confusion.","history":"New seizure, headache or aphasia possible.","exam":"Altered mentation, temporal-lobe deficits or focal seizures.","test":"CSF HSV PCR, MRI temporal abnormalities and EEG as needed.","mechanism":"HSV causes necrotizing temporal-lobe encephalitis.","differential":"Psychiatric illness; bacterial meningitis","management":"Start IV acyclovir immediately when suspected while testing.","redflag":"Delay in acyclovir worsens neurologic outcomes.","difficulty":2,"system":"Neuro","id":"O220"},{"dx":"Focal impaired awareness seizure","patient":"26M","chief":"Episodes of staring","opening":"He has repeated one-minute episodes of staring and lip smacking.","history":"Altered awareness and confusion after events; possible déjà vu aura.","exam":"Normal exam between spells.","test":"EEG and brain MRI depending on evaluation.","mechanism":"Focal cortical electrical discharge can spread within temporal networks.","differential":"Absence seizure; syncope","management":"Neurology assessment, driving safety and appropriate antiseizure therapy.","redflag":"New seizure requires review of provoking causes.","difficulty":2,"system":"Neuro","id":"O221"},{"dx":"Generalized tonic-clonic seizure","patient":"33F","chief":"Witnessed convulsion","opening":"Witnesses describe sudden stiffening followed by rhythmic jerks.","history":"Tongue bite, incontinence and postictal confusion may occur.","exam":"Postictal drowsiness, transient focal deficit possible.","test":"Glucose/electrolytes, EEG and MRI based on first-seizure evaluation.","mechanism":"Synchronous widespread neuronal activity causes bilateral convulsion.","differential":"Convulsive syncope; psychogenic nonepileptic event","management":"Protect airway, assess cause and determine antiseizure treatment need.","redflag":"Persistent convulsion beyond 5 minutes is status epilepticus.","difficulty":1,"system":"Neuro","id":"O222"},{"dx":"Convulsive status epilepticus","patient":"41M","chief":"Ongoing seizure","opening":"He has been convulsing continuously for more than five minutes.","history":"Missed antiseizure medication, intoxication or metabolic insult.","exam":"Generalized convulsions and impaired airway protection.","test":"Immediate bedside glucose and urgent labs; EEG for ongoing nonconvulsive seizures.","mechanism":"Sustained seizure activity drives neuronal injury and systemic instability.","differential":"Brief seizure; hypoglycemia","management":"Immediate benzodiazepine, airway care and second-line antiseizure medication if persistent.","redflag":"Treat immediately; do not wait for diagnostic confirmation.","difficulty":1,"system":"Neuro","id":"O223"},{"dx":"Diabetic distal polyneuropathy","patient":"62M","chief":"Burning feet","opening":"He reports burning, tingling and reduced sensation in both feet.","history":"Years of diabetes; nocturnal symptoms and imbalance.","exam":"Length-dependent stocking sensory loss, reduced ankle reflexes.","test":"Clinical foot and sensory exam, A1c and targeted tests for alternate neuropathy.","mechanism":"Chronic metabolic injury damages longest peripheral axons first.","differential":"Lumbar radiculopathy; vitamin B12 deficiency","management":"Glycemic optimization, foot protection and neuropathic pain strategies.","redflag":"Check for ulcers and loss of protective sensation.","difficulty":1,"system":"Neuro","id":"O224"},{"dx":"Guillain-Barre syndrome","patient":"30M","chief":"Rapidly progressive weakness","opening":"Leg weakness has ascended over several days after diarrhea.","history":"Tingling, back pain, autonomic symptoms or respiratory difficulty.","exam":"Symmetric flaccid weakness, depressed reflexes.","test":"Serial forced vital capacity; LP may show albuminocytologic dissociation, NCS.","mechanism":"Postinfectious immune attack on peripheral nerves causes acute demyelination or axonal injury.","differential":"Spinal cord compression; myasthenia gravis","management":"Hospitalize, monitor breathing/autonomic function and treat with IVIG or plasma exchange.","redflag":"Respiratory failure can develop rapidly.","difficulty":1,"system":"Neuro","id":"O225"},{"dx":"Myasthenia gravis","patient":"28F","chief":"Drooping eyelids and double vision","opening":"Her eyelids droop more as the day progresses.","history":"Fatigable chewing, swallowing or speech trouble; improvement with rest.","exam":"Fatigable ptosis/diplopia with preserved sensation and reflexes.","test":"AChR/MuSK antibodies, electrodiagnostics; chest imaging for thymoma.","mechanism":"Autoantibodies disrupt neuromuscular junction transmission.","differential":"Lambert-Eaton syndrome; brainstem stroke","management":"Pyridostigmine and immunotherapy under specialist guidance; thymus evaluation.","redflag":"Bulbar/respiratory weakness requires urgent assessment.","difficulty":1,"system":"Neuro","id":"O226"},{"dx":"Lambert-Eaton myasthenic syndrome","patient":"59M","chief":"Weak legs when rising","opening":"He has difficulty standing that briefly improves after exertion.","history":"Dry mouth, autonomic symptoms and tobacco history.","exam":"Proximal weakness, reduced reflexes that improve after contraction.","test":"VGCC antibodies, incremental response on stimulation; evaluate for small-cell lung cancer.","mechanism":"Presynaptic calcium-channel antibodies reduce acetylcholine release.","differential":"Myasthenia gravis; inflammatory myopathy","management":"Search for and treat malignancy, plus specialist neuromuscular treatment.","redflag":"Cancer association is a critical discriminator.","difficulty":3,"system":"Neuro","id":"O227"},{"dx":"Multiple sclerosis","patient":"29F","chief":"Numbness and visual symptoms","opening":"She has recurrent episodes of neurologic symptoms separated by months.","history":"Past transient vision loss, electric-shock sensation with neck flexion or weakness.","exam":"Multifocal CNS findings, internuclear ophthalmoplegia possible.","test":"MRI brain/spine demyelinating lesions in space/time; CSF oligoclonal bands as needed.","mechanism":"Autoimmune CNS demyelination causes relapsing deficits.","differential":"Neuromyelitis optica; stroke","management":"Neurology-directed disease-modifying therapy and relapse treatment.","redflag":"New severe vision or motor loss needs expedited care.","difficulty":2,"system":"Neuro","id":"O228"},{"dx":"Optic neuritis","patient":"27F","chief":"Painful vision loss in one eye","opening":"Vision becomes blurry over two days and eye movement hurts.","history":"Reduced color saturation; prior neurologic episodes possible.","exam":"Relative afferent pupillary defect and impaired red-color vision.","test":"MRI brain/orbits; consider inflammatory demyelination.","mechanism":"Inflammation of optic nerve interrupts visual conduction.","differential":"Retinal detachment; ischemic optic neuropathy","management":"Urgent ophthalmology/neurology assessment; steroids for selected cases.","redflag":"Severe atypical bilateral or recurrent disease raises alternative diagnosis.","difficulty":2,"system":"Neuro","id":"O229"},{"dx":"Parkinson disease","patient":"68M","chief":"Slow movements and tremor","opening":"He has gradually become slower and his hand trembles at rest.","history":"Smaller handwriting, constipation, reduced smell and rigidity.","exam":"Bradykinesia with resting tremor and cogwheel rigidity, reduced arm swing.","test":"Clinical diagnosis and medication review.","mechanism":"Degeneration of nigrostriatal dopamine neurons impairs movement initiation.","differential":"Essential tremor; drug-induced parkinsonism","management":"Exercise and individualized dopaminergic therapy.","redflag":"Early falls or prominent autonomic/cognitive issues suggest atypical syndrome.","difficulty":1,"system":"Neuro","id":"O230"},{"dx":"Essential tremor","patient":"63F","chief":"Shaky hands","opening":"Her hands shake when holding a cup or writing.","history":"Family history, improvement with small amounts of alcohol sometimes.","exam":"Bilateral action/postural tremor without bradykinesia.","test":"Clinical exam, medication and thyroid review.","mechanism":"Action tremor network dysfunction rather than nigrostriatal degeneration.","differential":"Parkinson disease; hyperthyroidism","management":"Reduce triggers, propranolol or primidone when appropriate.","redflag":"Unilateral resting tremor or rigidity suggests Parkinson disease.","difficulty":1,"system":"Neuro","id":"O231"},{"dx":"Huntington disease","patient":"42M","chief":"Involuntary movements and mood changes","opening":"He has irregular jerky movements and declining work performance.","history":"Autosomal dominant family history, irritability or cognitive change.","exam":"Chorea, impaired saccades and executive dysfunction.","test":"HTT CAG repeat genetic testing with counseling.","mechanism":"CAG expansion causes progressive striatal neuron loss.","differential":"Wilson disease; tardive dyskinesia","management":"Specialist symptomatic treatment and family/genetic counseling.","redflag":"Assess suicide risk and capacity in neuropsychiatric disease.","difficulty":3,"system":"Neuro","id":"O232"},{"dx":"Amyotrophic lateral sclerosis","patient":"58M","chief":"Progressive hand weakness","opening":"His hand weakens gradually and muscles twitch.","history":"Progressive asymmetric weakness without early sensory loss.","exam":"Mixed upper and lower motor signs: brisk reflexes, atrophy, fasciculations.","test":"EMG/NCS and MRI/labs to exclude mimics.","mechanism":"Motor neuron degeneration affects corticospinal and lower motor pathways.","differential":"Cervical myelopathy; multifocal motor neuropathy","management":"Multidisciplinary motor-neuron care and disease-modifying therapy where eligible.","redflag":"Monitor respiratory function and swallowing.","difficulty":2,"system":"Neuro","id":"O233"},{"dx":"Bell palsy","patient":"38F","chief":"Drooping side of face","opening":"One side of her face became weak over several hours.","history":"Recent viral symptoms; no arm weakness or language difficulty.","exam":"Peripheral facial weakness involving forehead and eye closure.","test":"Clinical after careful neurologic exam; investigate atypical cases.","mechanism":"Idiopathic acute peripheral CN VII dysfunction causes full hemiface weakness.","differential":"Ischemic stroke; Ramsay Hunt syndrome","management":"Eye protection and early oral glucocorticoids when appropriate.","redflag":"Other focal deficits or forehead-sparing warrant stroke evaluation.","difficulty":1,"system":"Neuro","id":"O234"},{"dx":"Trigeminal neuralgia","patient":"64F","chief":"Electric-shock facial pain","opening":"Brief intense stabbing pains strike one side of her cheek.","history":"Triggered by brushing teeth or light touch, lasting seconds.","exam":"Often normal facial sensory examination.","test":"Clinical features; MRI to assess secondary causes when appropriate.","mechanism":"Irritation of trigeminal nerve produces paroxysmal neuralgic pain.","differential":"Dental abscess; cluster headache","management":"Carbamazepine or oxcarbazepine with safety monitoring.","redflag":"Objective sensory loss suggests secondary pathology.","difficulty":2,"system":"Neuro","id":"O235"},{"dx":"Benign paroxysmal positional vertigo","patient":"56F","chief":"Spinning when turning in bed","opening":"The room spins briefly whenever she rolls to one side.","history":"Episodes under a minute, no hearing loss or focal weakness.","exam":"Dix-Hallpike elicits brief torsional upbeat nystagmus in posterior canal BPPV.","test":"Bedside positional testing; imaging not routine when classic.","mechanism":"Dislodged otoconia stimulate semicircular canal during head position changes.","differential":"Vestibular neuritis; posterior stroke","management":"Epley canalith repositioning when posterior-canal BPPV confirmed.","redflag":"Continuous dizziness with focal deficits is not typical BPPV.","difficulty":1,"system":"Neuro","id":"O236"},{"dx":"Vestibular neuritis","patient":"43M","chief":"Severe continuous vertigo","opening":"He has sudden continuous spinning and vomiting for a day.","history":"Recent virus, no hearing loss or focal neurologic symptoms.","exam":"Unidirectional nystagmus and gait unsteadiness; specialist HINTS only in acute vestibular syndrome.","test":"Clinical evaluation with careful stroke exclusion.","mechanism":"Acute unilateral vestibular nerve dysfunction produces persistent vertigo.","differential":"Posterior stroke; BPPV","management":"Short-term antiemetics, early vestibular rehab and selected steroids.","redflag":"HINTS is only reliable in trained hands and appropriate patients.","difficulty":2,"system":"Neuro","id":"O237"},{"dx":"Meniere disease","patient":"47F","chief":"Episodes of spinning and ear fullness","opening":"She has several episodes of vertigo lasting hours.","history":"Fluctuating unilateral hearing loss, tinnitus and ear fullness.","exam":"Often normal between attacks; hearing deficits may be present.","test":"Audiometry documents sensorineural hearing loss.","mechanism":"Endolymphatic hydrops causes episodic vestibulocochlear symptoms.","differential":"Vestibular migraine; BPPV","management":"ENT referral, symptom management and hearing-focused care.","redflag":"Progressive unilateral hearing loss may need imaging for other causes.","difficulty":2,"system":"Neuro","id":"O238"},{"dx":"Vestibular migraine","patient":"34F","chief":"Recurrent dizziness","opening":"She has recurrent vertigo episodes sometimes without headache.","history":"History of migraine, light/sound sensitivity and motion sensitivity.","exam":"Normal neurologic exam between attacks.","test":"Clinical vestibular migraine criteria after excluding mimics.","mechanism":"Migraine-associated vestibular network dysfunction causes episodes of vertigo.","differential":"Meniere disease; BPPV","management":"Migraine trigger control and prevention strategies when frequent.","redflag":"New focal deficits warrant stroke evaluation.","difficulty":3,"system":"Neuro","id":"O239"},{"dx":"Wernicke encephalopathy","patient":"50M","chief":"Confusion and unsteady gait","opening":"A malnourished patient develops confusion and difficulty walking.","history":"Heavy alcohol use or severe malnutrition; visual complaints possible.","exam":"Gait ataxia, ophthalmoplegia or nystagmus, altered attention.","test":"Clinical diagnosis; magnesium and nutritional labs, MRI not needed to treat.","mechanism":"Thiamine deficiency damages metabolically vulnerable brain regions.","differential":"Alcohol intoxication; cerebellar stroke","management":"Give IV thiamine promptly, with nutrition and magnesium repletion.","redflag":"Treat empirically before waiting for confirmatory tests.","difficulty":1,"system":"Neuro","id":"O240"},{"dx":"Normal pressure hydrocephalus","patient":"76M","chief":"Falls and forgetfulness","opening":"He has a slow shuffling gait and worsening urinary urgency.","history":"Gait problems often precede memory and urinary symptoms.","exam":"Wide-based magnetic gait and frontal cognitive changes.","test":"Brain MRI/CT ventriculomegaly and CSF tap test in selected patients.","mechanism":"Abnormal CSF dynamics enlarge ventricles despite often normal measured pressure.","differential":"Parkinson disease; Alzheimer disease","management":"Neurology/neurosurgery evaluation for shunt candidacy.","redflag":"Look for reversible contributors to gait and cognition.","difficulty":2,"system":"Neuro","id":"O241"},{"dx":"Alzheimer disease","patient":"78F","chief":"Gradual memory loss","opening":"She increasingly repeats questions and loses her way.","history":"Progressive episodic memory impairment affecting everyday function.","exam":"Impaired delayed recall, otherwise often nonfocal early.","test":"Cognitive assessment, labs for reversible causes and brain imaging when indicated.","mechanism":"Amyloid and tau-associated neurodegeneration impairs memory networks.","differential":"Vascular dementia; depression","management":"Safety planning, caregiver support and symptom/disease-modifying therapies when appropriate.","redflag":"Exclude delirium and potentially reversible causes first.","difficulty":1,"system":"Neuro","id":"O242"},{"dx":"Delirium","patient":"82M","chief":"Sudden confusion in hospital","opening":"He becomes inattentive and disoriented after surgery.","history":"Fluctuating symptoms over hours, new medicines or infection.","exam":"Inattention, altered awareness and sleep-wake reversal.","test":"Clinical delirium screen plus evaluation for infection, drugs, metabolic causes.","mechanism":"Acute brain dysfunction from systemic insults, often multifactorial.","differential":"Dementia; primary psychiatric illness","management":"Treat cause, reorientation, sleep and mobilization, avoid unnecessary sedatives.","redflag":"Delirium can be first sign of sepsis or hypoxia.","difficulty":1,"system":"Neuro","id":"O243"},{"dx":"Dementia with Lewy bodies","patient":"74M","chief":"Memory problems and seeing people","opening":"He has fluctuating attention, vivid visual hallucinations and stiffness.","history":"REM sleep behavior disorder and sensitivity to antipsychotics.","exam":"Parkinsonism and variable cognition.","test":"Clinical criteria and assessment of cognitive/neuropsychiatric symptoms.","mechanism":"Alpha-synuclein inclusions affect cortical and subcortical networks.","differential":"Alzheimer disease; Parkinson disease dementia","management":"Specialist dementia care, fall prevention and cautious medication use.","redflag":"Typical antipsychotics may cause severe sensitivity.","difficulty":3,"system":"Neuro","id":"O244"},{"dx":"Intracranial mass lesion","patient":"52F","chief":"Headache and new seizure","opening":"She has weeks of worsening morning headache and a first seizure.","history":"Progressive focal symptoms, vomiting or known malignancy.","exam":"Possible papilledema or focal neurologic deficit.","test":"Urgent contrast MRI brain (CT initially if needed).","mechanism":"Space-occupying process causes cortical irritation and raised pressure.","differential":"Migraine; intracerebral hemorrhage","management":"Urgent neurologic/neurosurgical evaluation and cause-specific management.","redflag":"Signs of herniation or rapidly declining consciousness are emergencies.","difficulty":2,"system":"Neuro","id":"O245"},{"dx":"Spinal cord compression","patient":"64M","chief":"Back pain and weak legs","opening":"A man with cancer develops severe back pain and leg weakness.","history":"Night pain, new bowel/bladder difficulty, malignancy history.","exam":"Sensory level, bilateral motor deficits, hyperreflexia below lesion.","test":"Emergency MRI whole spine when malignant compression suspected.","mechanism":"Epidural tumor or fracture compresses spinal cord.","differential":"Cauda equina syndrome; lumbar radiculopathy","management":"Immediate specialist assessment, steroids for suspected malignant compression per pathway and definitive treatment.","redflag":"Time-critical to preserve ambulation.","difficulty":1,"system":"Neuro","id":"O246"},{"dx":"Transverse myelitis","patient":"35F","chief":"Weakness and numbness in both legs","opening":"Over several days she develops bilateral weakness and tingling.","history":"New bladder symptoms, sensory level and recent infection.","exam":"Bilateral signs, sensory level and upper motor findings.","test":"Spine MRI with contrast, CSF and antibody evaluation after excluding compression.","mechanism":"Inflammation across spinal cord interrupts ascending and descending pathways.","differential":"Spinal cord compression; multiple sclerosis","management":"Urgent neurologic assessment and high-dose steroid therapy when indicated.","redflag":"Bladder dysfunction and rapid weakness need emergency workup.","difficulty":3,"system":"Neuro","id":"O247"},{"dx":"Idiopathic intracranial hypertension","patient":"27F","chief":"Daily headache and transient blurry vision","opening":"She has daily headaches and brief dimming of vision.","history":"Pulsatile tinnitus, recent weight gain, medication exposures.","exam":"Papilledema and possible sixth-nerve palsy.","test":"MRI/MRV excluding mass and venous thrombosis; LP elevated opening pressure.","mechanism":"Elevated intracranial pressure without mass can damage optic nerves.","differential":"Migraine; cerebral venous sinus thrombosis","management":"Weight management and acetazolamide; urgent eye assessment.","redflag":"Threatened vision may need urgent surgical intervention.","difficulty":2,"system":"Neuro","id":"O248"},{"dx":"Cerebral venous sinus thrombosis","patient":"31F","chief":"Headache and seizure","opening":"She has worsening headache after childbirth and a new seizure.","history":"Postpartum state, estrogen or thrombophilia; headache can evolve over days.","exam":"Papilledema or focal deficit may occur.","test":"CT/MR venography showing venous sinus thrombosis.","mechanism":"Blocked cerebral venous outflow raises intracranial pressure and causes venous infarction.","differential":"Idiopathic intracranial hypertension; migraine","management":"Urgent anticoagulation and neurologic management, including selected hemorrhagic cases.","redflag":"Do not dismiss postpartum persistent headache.","difficulty":3,"system":"Neuro","id":"O249"},{"dx":"Amyloid cerebral angiopathy hemorrhage","patient":"80F","chief":"New confusion and focal weakness","opening":"An older adult has an unexplained sudden neurologic change.","history":"No history of severe hypertension; possible recurrent lobar bleeding.","exam":"Focal deficit and variable consciousness.","test":"Noncontrast CT shows lobar hemorrhage; MRI susceptibility reveals microbleeds.","mechanism":"Amyloid deposition weakens cortical small vessels causing lobar hemorrhage.","differential":"Hypertensive intracerebral hemorrhage; ischemic stroke","management":"Emergency hemorrhage care and careful future antithrombotic risk assessment.","redflag":"High recurrence risk with lobar hemorrhage.","difficulty":3,"system":"Neuro","id":"O250"},{"dx":"Functional neurological disorder","patient":"26F","chief":"Leg weakness after stress","opening":"She reports sudden leg weakness after a distressing event.","history":"Symptoms are genuine; may vary with attention, without intentional production.","exam":"Positive Hoover sign or internally inconsistent motor findings.","test":"Clinical positive signs plus evaluation for coexisting neurologic disease.","mechanism":"Altered nervous-system functioning rather than structural pathway damage.","differential":"Stroke; spinal cord compression","management":"Clear nonjudgmental explanation and specialized rehabilitation.","redflag":"Never diagnose solely from stress history or normal imaging.","difficulty":3,"system":"Neuro","id":"O251"},{"dx":"New-onset type 1 diabetes mellitus","patient":"13F","chief":"Thirst and weight loss","opening":"A teenager has been very thirsty and losing weight despite eating.","history":"Polyuria, nocturia and fatigue; possible abdominal pain.","exam":"Dry mucosa or tachycardia if dehydrated.","test":"Random plasma glucose with symptoms; A1c, ketones and autoantibodies when appropriate.","mechanism":"Autoimmune beta-cell destruction produces absolute insulin deficiency.","differential":"Type 2 diabetes; diabetes insipidus","management":"Initiate insulin and diabetes education; evaluate for ketoacidosis.","redflag":"Nausea, rapid breathing or altered mentation may signal DKA.","difficulty":1,"system":"Endo/Repro","id":"O252"},{"dx":"Type 2 diabetes mellitus","patient":"52M","chief":"Frequent urination","opening":"He reports thirst, tiredness and more frequent urination.","history":"Central obesity, family history and sedentary lifestyle; symptoms may be absent.","exam":"Central adiposity and acanthosis nigricans possible.","test":"A1c or fasting plasma glucose using diagnostic criteria and confirmation as needed.","mechanism":"Insulin resistance and progressive beta-cell dysfunction raise glucose.","differential":"Type 1 diabetes; diabetes insipidus","management":"Lifestyle/metabolic risk care and individualized glucose-lowering therapy.","redflag":"Assess kidney, retinal, neuropathic and cardiovascular complications.","difficulty":1,"system":"Endo/Repro","id":"O253"},{"dx":"Diabetic ketoacidosis","patient":"18F","chief":"Vomiting and fast breathing","opening":"She has abdominal pain, vomiting and very deep breathing.","history":"Known diabetes or new diagnosis; missed insulin or infection.","exam":"Dehydration, tachycardia, Kussmaul respirations and fruity breath.","test":"High anion gap metabolic acidosis, ketosis, hyperglycemia usually but euglycemic possible.","mechanism":"Insulin deficiency triggers lipolysis and ketone acid production.","differential":"HHS; alcoholic ketoacidosis","management":"IV fluids, potassium-guided insulin and treat precipitant under protocol.","redflag":"Potassium can fall dangerously after insulin begins.","difficulty":1,"system":"Endo/Repro","id":"O254"},{"dx":"Hyperosmolar hyperglycemic state","patient":"72M","chief":"Extreme thirst and confusion","opening":"An older adult with diabetes becomes progressively confused over days.","history":"Marked polyuria, dehydration and preceding illness.","exam":"Very dry mucosa, hypotension or altered consciousness.","test":"Marked hyperglycemia, high effective serum osmolality, little significant ketoacidosis.","mechanism":"Relative insulin suffices to limit ketones but not profound osmotic diuresis.","differential":"DKA; stroke","management":"Careful IV fluid and electrolyte resuscitation, insulin after appropriate assessment.","redflag":"Severe dehydration, thrombosis and altered mentation make this an emergency.","difficulty":1,"system":"Endo/Repro","id":"O255"},{"dx":"Severe hypoglycemia","patient":"57F","chief":"Sweating and confusion","opening":"She becomes sweaty, shaky and unable to answer questions.","history":"Insulin or sulfonylurea use, missed meal or exertion.","exam":"Tachycardia, diaphoresis and neuroglycopenia.","test":"Immediate bedside glucose confirms low glucose.","mechanism":"Insufficient circulating glucose impairs cerebral function and triggers adrenergic response.","differential":"Stroke; panic attack","management":"Give oral glucose if alert, IV dextrose or glucagon when unable to swallow; monitor recurrence.","redflag":"Check glucose immediately in altered consciousness.","difficulty":1,"system":"Endo/Repro","id":"O256"},{"dx":"Hashimoto hypothyroidism","patient":"38F","chief":"Fatigue and feeling cold","opening":"She reports fatigue, constipation and weight gain.","history":"Cold intolerance, dry skin, menstrual changes and family autoimmunity.","exam":"Bradycardia, delayed reflex relaxation and coarse dry skin.","test":"Elevated TSH with low free T4 in overt primary disease; anti-TPO supports.","mechanism":"Autoimmune thyroid destruction lowers hormone production.","differential":"Depression; anemia","management":"Levothyroxine titrated to TSH and clinical context.","redflag":"Severe confusion with hypothermia suggests myxedema coma.","difficulty":1,"system":"Endo/Repro","id":"O257"},{"dx":"Graves hyperthyroidism","patient":"29F","chief":"Weight loss and palpitations","opening":"She is losing weight despite a strong appetite and feels shaky.","history":"Heat intolerance, frequent stools and menstrual irregularity.","exam":"Fine tremor, tachycardia, diffuse goiter and possible ophthalmopathy.","test":"Low TSH, high free T4/T3 and thyroid-stimulating immunoglobulin.","mechanism":"TSH-receptor antibodies stimulate thyroid hormone release.","differential":"Thyroiditis; toxic multinodular goiter","management":"Beta blocker for symptoms and antithyroid therapy/definitive options after evaluation.","redflag":"Fever and severe tachyarrhythmia raise thyroid storm concern.","difficulty":1,"system":"Endo/Repro","id":"O258"},{"dx":"Thyroid storm","patient":"46F","chief":"Fever and racing heart","opening":"She has fever, confusion and marked tachycardia after stopping thyroid medication.","history":"Known hyperthyroidism, infection or surgery trigger.","exam":"Hyperthermia, tachyarrhythmia and agitation/delirium.","test":"Clinical emergency; thyroid labs support but may not reflect severity.","mechanism":"Extreme effects of excess thyroid hormone cause multiorgan decompensation.","differential":"Sepsis; pheochromocytoma crisis","management":"ICU care, beta blockade if safe, thionamide then iodine, glucocorticoids and treat trigger.","redflag":"Do not wait for laboratory confirmation to treat a strongly suspected storm.","difficulty":1,"system":"Endo/Repro","id":"O259"},{"dx":"Subacute thyroiditis","patient":"35F","chief":"Painful neck and palpitations","opening":"Her thyroid area became tender after a viral illness.","history":"Neck pain radiates to jaw; transient hyperthyroid symptoms.","exam":"Tender enlarged thyroid and possible fever.","test":"Low TSH in early phase, elevated ESR; low radionuclide uptake if tested.","mechanism":"Postviral thyroid inflammation releases stored hormone, then can cause hypothyroidism.","differential":"Graves disease; bacterial thyroiditis","management":"NSAIDs or glucocorticoids for severe pain, beta blocker if symptomatic.","redflag":"Antithyroid drugs do not treat hormone release from destructive thyroiditis.","difficulty":2,"system":"Endo/Repro","id":"O260"},{"dx":"Toxic multinodular goiter","patient":"71M","chief":"Irregular heartbeat and weight loss","opening":"He has increasing palpitations and unintended weight loss.","history":"Longstanding nodular goiter and no eye symptoms.","exam":"Irregular pulse and multinodular thyroid.","test":"Low TSH, high T4/T3, uptake scan shows patchy autonomous nodules.","mechanism":"Autonomous thyroid nodules produce hormone without TSH control.","differential":"Graves disease; thyroiditis","management":"Rate control and definitive radioiodine/surgery or selected medication.","redflag":"Hyperthyroidism can trigger atrial fibrillation.","difficulty":2,"system":"Endo/Repro","id":"O261"},{"dx":"Papillary thyroid carcinoma","patient":"36F","chief":"Neck lump","opening":"She notices a painless lump on the front of her neck.","history":"Prior neck radiation or family history; often no hormone symptoms.","exam":"Firm thyroid nodule or cervical lymphadenopathy.","test":"TSH, thyroid ultrasound risk stratification and fine-needle aspiration as indicated.","mechanism":"Differentiated follicular-derived cancer often spreads via lymphatics.","differential":"Benign thyroid nodule; thyroid lymphoma","management":"Endocrine surgery assessment based on size/risk and pathology.","redflag":"Rapid growth, voice change or nodes are suspicious.","difficulty":2,"system":"Endo/Repro","id":"O262"},{"dx":"Primary hyperparathyroidism","patient":"64F","chief":"Kidney stones and constipation","opening":"She has recurrent stones, fatigue and constipation.","history":"Bone pain, mood changes or incidental high calcium.","exam":"Possible dehydration or no overt findings.","test":"Elevated calcium with inappropriately nonsuppressed PTH, phosphate and urine calcium workup.","mechanism":"Autonomous PTH raises calcium through bone, kidney and vitamin D effects.","differential":"Malignancy-associated hypercalcemia; familial hypocalciuric hypercalcemia","management":"Hydration and assessment for parathyroidectomy criteria.","redflag":"Severe hypercalcemia causes arrhythmia and altered consciousness.","difficulty":1,"system":"Endo/Repro","id":"O263"},{"dx":"Hypoparathyroidism","patient":"45F","chief":"Tingling around mouth","opening":"She develops muscle cramps and tingling after thyroid surgery.","history":"Perioral paresthesias, carpopedal spasm.","exam":"Chvostek/Trousseau signs, possible tetany.","test":"Low calcium, high phosphate and low/inappropriately normal PTH.","mechanism":"PTH deficiency impairs calcium homeostasis after parathyroid injury.","differential":"Vitamin D deficiency; hypomagnesemia","management":"Calcium and active vitamin D replacement; IV calcium for severe symptoms.","redflag":"Check QT prolongation and airway spasm in severe hypocalcemia.","difficulty":2,"system":"Endo/Repro","id":"O264"},{"dx":"Primary adrenal insufficiency","patient":"37M","chief":"Fatigue and darkening skin","opening":"He has chronic weakness, weight loss and craving for salt.","history":"Dizziness on standing, abdominal discomfort and autoimmune history.","exam":"Hyperpigmentation and hypotension.","test":"Low morning cortisol, high ACTH and cosyntropin testing when safe; hyponatremia/hyperkalemia.","mechanism":"Adrenal cortical failure lowers cortisol and aldosterone.","differential":"Secondary adrenal insufficiency; hypothyroidism","management":"Lifelong glucocorticoid and mineralocorticoid replacement with sick-day education.","redflag":"Intercurrent illness may precipitate adrenal crisis.","difficulty":2,"system":"Endo/Repro","id":"O265"},{"dx":"Adrenal crisis","patient":"41F","chief":"Vomiting and low blood pressure","opening":"A steroid-dependent patient has severe vomiting and collapses.","history":"Recent infection or abrupt steroid cessation.","exam":"Profound hypotension, dehydration and altered mental status.","test":"Draw cortisol/ACTH if no delay; electrolytes, glucose and infection workup.","mechanism":"Acute cortisol deficiency causes refractory shock and metabolic derangement.","differential":"Septic shock; hypoglycemia","management":"Give immediate IV hydrocortisone and isotonic fluids, dextrose if needed.","redflag":"Treatment must not wait for test results.","difficulty":1,"system":"Endo/Repro","id":"O266"},{"dx":"Cushing syndrome","patient":"42F","chief":"Weight gain and bruising","opening":"She develops central weight gain and easy bruising over a year.","history":"Proximal weakness, poor wound healing, mood changes or steroid use.","exam":"Wide purple striae, facial rounding, thin skin and hypertension.","test":"First exclude exogenous steroids, then validated cortisol screening tests.","mechanism":"Chronic glucocorticoid excess redistributes fat and causes muscle and skin catabolism.","differential":"Metabolic syndrome; PCOS","management":"Endocrine evaluation to localize source and treat cause.","redflag":"Do not use random serum cortisol alone to diagnose Cushing syndrome.","difficulty":2,"system":"Endo/Repro","id":"O267"},{"dx":"Primary aldosteronism","patient":"49M","chief":"High blood pressure and low potassium","opening":"His hypertension remains difficult to control and potassium is low.","history":"Muscle cramps or weakness; sometimes normal potassium.","exam":"High BP, usually no overt specific findings.","test":"Aldosterone-to-renin ratio followed by confirmatory/localization testing.","mechanism":"Autonomous aldosterone causes sodium retention, potassium and hydrogen loss.","differential":"Renal artery stenosis; Cushing syndrome","management":"Mineralocorticoid receptor antagonist or unilateral adrenalectomy when appropriate.","redflag":"Correct potassium and account for medication interference in testing.","difficulty":2,"system":"Endo/Repro","id":"O268"},{"dx":"Pheochromocytoma","patient":"36F","chief":"Episodes of headaches and sweating","opening":"She has spells of pounding headache and palpitations.","history":"Episodic sweating, pallor and severe hypertension.","exam":"BP may spike during attacks.","test":"Plasma free or urinary fractionated metanephrines, then imaging.","mechanism":"Catecholamine-secreting tumor causes intermittent sympathetic surges.","differential":"Panic disorder; hyperthyroidism","management":"Specialist-directed alpha blockade before surgery; evaluate genetics.","redflag":"Avoid initiating beta blockade alone before adequate alpha blockade.","difficulty":2,"system":"Endo/Repro","id":"O269"},{"dx":"Acromegaly","patient":"48M","chief":"Hands and shoes getting bigger","opening":"His ring no longer fits and his shoe size has increased.","history":"Headache, snoring, joint pain and diabetes possible.","exam":"Coarse facial features, enlarged jaw, broad hands.","test":"Elevated IGF-1 and failure of GH suppression after oral glucose; pituitary MRI.","mechanism":"Excess pituitary GH after growth-plate closure produces tissue overgrowth.","differential":"Hypothyroidism; normal aging","management":"Transsphenoidal surgery often first-line, with endocrine follow-up.","redflag":"Consider visual field compromise from macroadenoma.","difficulty":3,"system":"Endo/Repro","id":"O270"},{"dx":"Prolactinoma","patient":"31F","chief":"Missed periods and milky discharge","opening":"She has irregular periods and spontaneous breast discharge.","history":"Infertility, decreased libido and headaches if mass large.","exam":"Galactorrhea; possible visual-field defects.","test":"Serum prolactin, pregnancy test, TSH and pituitary MRI when indicated.","mechanism":"Excess prolactin suppresses GnRH and gonadal function.","differential":"Pregnancy; medication-induced hyperprolactinemia","management":"Dopamine agonist such as cabergoline in many cases, specialist follow-up.","redflag":"Visual loss or apoplexy symptoms demand urgent evaluation.","difficulty":2,"system":"Endo/Repro","id":"O271"},{"dx":"Central diabetes insipidus","patient":"28M","chief":"Extreme thirst and clear urine","opening":"He drinks water constantly and urinates large volumes day and night.","history":"Prior pituitary surgery/head injury or unexplained onset.","exam":"May have dehydration if unable to access water.","test":"Serum/urine osmolality and supervised water deprivation/desmopressin testing when appropriate.","mechanism":"Deficient ADH secretion prevents urine concentration.","differential":"Primary polydipsia; uncontrolled diabetes mellitus","management":"Desmopressin with careful fluid/sodium education and evaluate cause.","redflag":"Untreated water loss may cause severe hypernatremia.","difficulty":2,"system":"Endo/Repro","id":"O272"},{"dx":"Polycystic ovary syndrome","patient":"23F","chief":"Irregular periods and acne","opening":"She has infrequent periods and worsening facial hair.","history":"Weight gain, infertility or insulin resistance; onset since adolescence.","exam":"Hirsutism, acne, acanthosis possible.","test":"Exclude pregnancy/thyroid/prolactin causes; assess hyperandrogenism and ovulatory dysfunction.","mechanism":"Ovarian androgen excess and ovulatory dysfunction are linked to insulin resistance.","differential":"Cushing syndrome; congenital adrenal hyperplasia","management":"Lifestyle/metabolic management and cycle regulation or fertility care based on goals.","redflag":"Protect endometrium from prolonged unopposed estrogen exposure.","difficulty":1,"system":"Endo/Repro","id":"O273"},{"dx":"Endometriosis","patient":"27F","chief":"Severe period pain","opening":"Her menstrual cramps are worsening and now affect daily life.","history":"Cyclic pelvic pain, painful intercourse, painful bowel movements and infertility.","exam":"Pelvic tenderness, possible uterosacral nodularity.","test":"Clinical suspicion; ultrasound for endometrioma, laparoscopy selectively.","mechanism":"Ectopic endometrial-like tissue causes inflammation and pain.","differential":"Adenomyosis; pelvic inflammatory disease","management":"NSAIDs, hormonal suppression when appropriate and gynecology referral.","redflag":"Acute severe pelvic pain still needs pregnancy and torsion evaluation.","difficulty":1,"system":"Endo/Repro","id":"O274"},{"dx":"Pelvic inflammatory disease","patient":"21F","chief":"Pelvic pain and discharge","opening":"She has lower abdominal pain and new vaginal discharge.","history":"Recent new partner, fever or dyspareunia.","exam":"Cervical motion, uterine or adnexal tenderness on consented exam.","test":"Pregnancy test, gonorrhea/chlamydia NAAT; clinical diagnosis with low threshold.","mechanism":"Ascending genital tract infection inflames uterus/tubes, often polymicrobial.","differential":"Ectopic pregnancy; appendicitis","management":"Prompt empiric antibiotics covering likely pathogens and partner management.","redflag":"Fever with peritoneal signs or tubo-ovarian abscess needs escalation.","difficulty":1,"system":"Endo/Repro","id":"O275"},{"dx":"Ectopic pregnancy","patient":"29F","chief":"Pelvic pain and spotting","opening":"She has sharp unilateral pelvic pain and light vaginal bleeding.","history":"Missed period, positive pregnancy test; previous tubal disease.","exam":"Adnexal tenderness, hypotension if ruptured.","test":"Immediate pregnancy test, quantitative beta-hCG and transvaginal ultrasound.","mechanism":"Implantation outside uterine cavity, usually tubal, risks rupture.","differential":"Early intrauterine pregnancy; ovarian cyst rupture","management":"Stabilize, urgent OB/GYN assessment and medical/surgical care depending on stability.","redflag":"Hemodynamic instability is ruptured ectopic until excluded.","difficulty":1,"system":"Endo/Repro","id":"O276"},{"dx":"Ovarian torsion","patient":"19F","chief":"Sudden one-sided pelvic pain","opening":"She has abrupt severe lower abdominal pain with vomiting.","history":"Pain may wax and wane; known ovarian cyst.","exam":"Unilateral adnexal tenderness, possible palpable mass.","test":"Pelvic ultrasound with Doppler, but normal flow does not exclude torsion.","mechanism":"Ovary twists vascular pedicle, threatening ischemic necrosis.","differential":"Ectopic pregnancy; appendicitis","management":"Urgent gynecologic laparoscopy for suspected torsion.","redflag":"Do not delay surgery solely because Doppler flow remains.","difficulty":1,"system":"Endo/Repro","id":"O277"},{"dx":"Ruptured ovarian cyst","patient":"25F","chief":"Sudden pelvic pain","opening":"Sharp unilateral pain began abruptly after exercise.","history":"Known functional cyst, pain may follow intercourse; last period timing.","exam":"Adnexal tenderness, possible peritoneal irritation.","test":"Pregnancy test and pelvic ultrasound with free fluid/collapsed cyst.","mechanism":"Cyst rupture releases fluid or blood into peritoneum.","differential":"Ectopic pregnancy; ovarian torsion","management":"Analgesia and observation if stable; surgery if ongoing hemorrhage.","redflag":"Always exclude pregnancy and assess hemodynamic stability.","difficulty":2,"system":"Endo/Repro","id":"O278"},{"dx":"Uterine leiomyoma","patient":"40F","chief":"Heavy periods","opening":"She reports progressively heavy menstrual flow and pelvic pressure.","history":"Prolonged bleeding, urinary frequency and possible infertility.","exam":"Enlarged irregular firm uterus.","test":"Pelvic ultrasound and CBC for anemia.","mechanism":"Benign estrogen/progesterone-responsive myometrial smooth muscle tumor.","differential":"Adenomyosis; endometrial carcinoma","management":"Iron replacement and medical/procedural bleeding management tailored to fertility wishes.","redflag":"Postmenopausal bleeding warrants endometrial evaluation.","difficulty":1,"system":"Endo/Repro","id":"O279"},{"dx":"Adenomyosis","patient":"43F","chief":"Painful heavy periods","opening":"She has heavy menstrual bleeding with increasingly painful cramps.","history":"Multiparity or midlife onset; pelvic pressure.","exam":"Globular boggy tender enlarged uterus.","test":"Transvaginal ultrasound or MRI may support diagnosis.","mechanism":"Endometrial tissue within myometrium causes uterine enlargement and dysmenorrhea.","differential":"Fibroids; endometriosis","management":"NSAIDs, hormonal therapy including LNG-IUD, or procedural management.","redflag":"Anemia can develop with persistent heavy bleeding.","difficulty":2,"system":"Endo/Repro","id":"O280"},{"dx":"Endometrial carcinoma","patient":"64F","chief":"Bleeding after menopause","opening":"She notices vaginal bleeding several years after her last period.","history":"Obesity, unopposed estrogen exposure or diabetes possible.","exam":"Pelvic exam may be normal.","test":"Transvaginal endometrial thickness assessment and endometrial biopsy as indicated.","mechanism":"Endometrial neoplasia often presents early with abnormal uterine bleeding.","differential":"Atrophic vaginitis; uterine polyps","management":"Prompt gynecologic evaluation and cancer staging if confirmed.","redflag":"Every postmenopausal bleeding episode needs appropriate evaluation.","difficulty":1,"system":"Endo/Repro","id":"O281"},{"dx":"Cervical carcinoma","patient":"41F","chief":"Bleeding after intercourse","opening":"She has postcoital spotting and abnormal discharge.","history":"HPV exposure, incomplete screening or smoking.","exam":"Friable abnormal cervical lesion may be visible.","test":"Speculum examination with biopsy of suspicious lesion, HPV/cytology and staging.","mechanism":"Persistent high-risk HPV promotes cervical intraepithelial neoplasia and carcinoma.","differential":"Cervicitis; cervical polyp","management":"Urgent gynecology oncology referral if malignancy found.","redflag":"A visible suspicious lesion needs biopsy regardless of screening history.","difficulty":2,"system":"Endo/Repro","id":"O282"},{"dx":"Epithelial ovarian carcinoma","patient":"62F","chief":"Abdominal bloating and early satiety","opening":"She has persistent bloating and is full after only a few bites.","history":"Pelvic pressure, urinary frequency and family history of BRCA cancers.","exam":"Ascites or pelvic/adnexal mass may be present.","test":"Transvaginal ultrasound and risk-directed CA-125, specialist referral.","mechanism":"Ovarian epithelial cancer presents with vague symptoms and peritoneal spread.","differential":"IBS; benign ovarian cyst","management":"Urgent gynecology-oncology evaluation and staging.","redflag":"New persistent bloating in older patient should not be dismissed.","difficulty":2,"system":"Endo/Repro","id":"O283"},{"dx":"Hyperemesis gravidarum","patient":"25F","chief":"Severe vomiting during pregnancy","opening":"At nine weeks pregnant she cannot keep water down.","history":"Frequent vomiting, weight loss and reduced urine.","exam":"Dry mucosa, orthostatic symptoms, weight loss.","test":"Pregnancy evaluation, electrolytes and urinalysis; assess alternate diagnoses.","mechanism":"Severe pregnancy-related nausea/vomiting causes dehydration and electrolyte disturbance.","differential":"Gastroenteritis; molar pregnancy","management":"IV fluids, thiamine before dextrose if prolonged poor intake, antiemetics and nutrition support.","redflag":"Check for electrolyte abnormalities and malnutrition.","difficulty":2,"system":"Endo/Repro","id":"O284"},{"dx":"Preeclampsia","patient":"30F","chief":"Headache late in pregnancy","opening":"At 32 weeks pregnant she develops headache and swollen hands.","history":"New hypertension after 20 weeks, visual symptoms, epigastric pain possible.","exam":"Elevated BP, hyperreflexia or edema (nonspecific).","test":"BP confirmation, urine protein, platelets, creatinine and liver tests.","mechanism":"Placental endothelial dysfunction causes multisystem maternal disease.","differential":"Gestational hypertension; migraine","management":"Urgent obstetric assessment, BP treatment and delivery planning by severity/gestation.","redflag":"Severe headache, vision change, RUQ pain or severe BP are red flags.","difficulty":1,"system":"Endo/Repro","id":"O285"},{"dx":"Eclampsia","patient":"22F","chief":"Seizure during pregnancy","opening":"At 36 weeks pregnant she has a new generalized convulsion.","history":"May have preceding headache, high BP and visual symptoms.","exam":"Postictal state, hypertension and possible hyperreflexia.","test":"Clinical emergency; assess glucose, BP, HELLP labs and fetal status.","mechanism":"Severe preeclampsia can cause cerebral endothelial dysfunction and seizures.","differential":"Epilepsy; intracranial hemorrhage","management":"Airway protection, IV magnesium sulfate, BP control and urgent obstetric delivery planning.","redflag":"Maternal stabilization precedes fetal intervention.","difficulty":1,"system":"Endo/Repro","id":"O286"},{"dx":"Placenta previa","patient":"32F","chief":"Painless bleeding in third trimester","opening":"At 30 weeks pregnant she notices bright-red vaginal bleeding without pain.","history":"Prior cesarean or placenta previa risk.","exam":"Soft nontender uterus; bleeding variable.","test":"Transabdominal/transvaginal ultrasound identifies placenta covering cervical os.","mechanism":"Low-lying placenta bleeds with lower uterine segment change.","differential":"Placental abruption; cervical lesion","management":"Maternal/fetal stabilization and obstetric management based on bleeding/gestation.","redflag":"Avoid digital vaginal examination until previa excluded.","difficulty":1,"system":"Endo/Repro","id":"O287"},{"dx":"Placental abruption","patient":"34F","chief":"Painful bleeding in pregnancy","opening":"At 34 weeks pregnant she develops sudden abdominal pain and bleeding.","history":"Hypertension, trauma or cocaine use may predispose.","exam":"Tender rigid uterus, fetal distress, possible concealed bleeding.","test":"Clinical diagnosis, fetal monitoring and labs; ultrasound can miss it.","mechanism":"Premature placental separation causes maternal hemorrhage and fetal hypoxia.","differential":"Placenta previa; uterine rupture","management":"Emergency maternal resuscitation and obstetric delivery decisions.","redflag":"Concealed hemorrhage can be severe despite scant visible blood.","difficulty":1,"system":"Endo/Repro","id":"O288"},{"dx":"Postpartum hemorrhage due to atony","patient":"28F","chief":"Heavy bleeding after delivery","opening":"Shortly after giving birth she has rapidly increasing vaginal bleeding.","history":"Prolonged labor, uterine overdistention or retained products risk.","exam":"Boggy enlarged uterus with brisk bleeding.","test":"Quantify blood loss, CBC/coags and examine four Ts: tone, trauma, tissue, thrombin.","mechanism":"Failure of myometrial contraction leaves uterine vessels open.","differential":"Retained placenta; genital tract laceration","management":"Uterine massage, oxytocin and hemorrhage protocol with further uterotonics/interventions as indicated.","redflag":"Treat shock immediately; escalate rapidly if not responding.","difficulty":1,"system":"Endo/Repro","id":"O289"},{"dx":"Lactational mastitis","patient":"29F","chief":"Painful breast and fever","opening":"A breastfeeding parent develops a red painful area of one breast.","history":"Milk stasis symptoms, chills and tenderness.","exam":"Localized erythematous tender wedge with fever.","test":"Clinical diagnosis; ultrasound if abscess suspected.","mechanism":"Inflammation and sometimes bacterial infection develops during lactation.","differential":"Breast abscess; inflammatory breast cancer","management":"Support lactation with effective milk removal, anti-inflammatory measures and antibiotics when indicated.","redflag":"Fluctuant mass or persistent worsening suggests abscess.","difficulty":1,"system":"Endo/Repro","id":"O290"},{"dx":"Testicular torsion","patient":"16M","chief":"Sudden testicular pain","opening":"A teenager wakes with sudden severe testicular pain and nausea.","history":"Onset within hours; no urinary symptoms.","exam":"High-riding horizontal testis, absent cremasteric reflex may occur.","test":"Urgent urologic evaluation; ultrasound only if it will not delay exploration.","mechanism":"Twisting of spermatic cord compromises testicular blood flow.","differential":"Epididymitis; torsed appendix testis","management":"Immediate surgical exploration and detorsion.","redflag":"Time-critical ischemia: never wait for all imaging when strongly suspected.","difficulty":1,"system":"Endo/Repro","id":"O291"},{"dx":"Epididymitis","patient":"23M","chief":"Scrotal pain and swelling","opening":"One testicle region has become gradually sore and swollen.","history":"Dysuria or STI exposure; onset less sudden than torsion.","exam":"Tender swollen epididymis, cremasteric reflex typically present.","test":"Urine NAAT for STI and urinalysis; ultrasound if torsion concern.","mechanism":"Ascending urinary/sexually transmitted infection inflames epididymis.","differential":"Testicular torsion; orchitis","management":"Etiology-directed antibiotics, supportive care and partner management.","redflag":"Exclude torsion in any acute scrotum before reassurance.","difficulty":1,"system":"Endo/Repro","id":"O292"},{"dx":"Testicular germ cell tumor","patient":"27M","chief":"Painless testicular lump","opening":"He notices a firm lump on one testicle while showering.","history":"Usually painless; cryptorchidism history possible.","exam":"Firm intratesticular mass that does not transilluminate.","test":"Scrotal ultrasound, AFP/beta-hCG/LDH and urologic staging.","mechanism":"Malignant germ-cell proliferation occurs within testis.","differential":"Hydrocele; epididymal cyst","management":"Urgent urology referral, radical inguinal orchiectomy when indicated.","redflag":"Do not biopsy through scrotum for suspected testicular cancer.","difficulty":2,"system":"Endo/Repro","id":"O293"},{"dx":"Functional hypothalamic amenorrhea","patient":"21F","chief":"No period for months","opening":"A college athlete has stopped menstruating for six months.","history":"Intense training, reduced calories or recent stress; pregnancy excluded.","exam":"Low body weight, bradycardia or other energy deficiency signs.","test":"Pregnancy test, TSH/prolactin, low/normal gonadotropins and low estradiol.","mechanism":"Energy deficiency suppresses hypothalamic GnRH pulsatility.","differential":"PCOS; premature ovarian insufficiency","management":"Restore energy availability, assess bone health and address exercise/eating factors.","redflag":"Monitor stress-fracture and low bone density risk.","difficulty":2,"system":"Endo/Repro","id":"O294"},{"dx":"Premature ovarian insufficiency","patient":"32F","chief":"Irregular periods and hot flashes","opening":"She has stopped menstruating and experiences hot flashes.","history":"Possible autoimmune disease, family history or prior chemotherapy.","exam":"Often normal or signs of hypoestrogenism.","test":"Repeat elevated FSH with low estradiol after pregnancy excluded, etiologic evaluation.","mechanism":"Reduced ovarian follicular function before age 40 causes estrogen deficiency.","differential":"Functional hypothalamic amenorrhea; PCOS","management":"Hormone replacement until usual menopausal age when appropriate and fertility counseling.","redflag":"Address bone and cardiovascular protection.","difficulty":2,"system":"Endo/Repro","id":"O295"},{"dx":"Menopause transition","patient":"48F","chief":"Hot flashes and irregular periods","opening":"She has increasingly irregular periods, night sweats and sleep trouble.","history":"Vasomotor symptoms and vaginal dryness; age-appropriate transition.","exam":"Typically normal exam.","test":"Clinical diagnosis in typical age group; exclude pregnancy/other causes when appropriate.","mechanism":"Declining ovarian follicle reserve causes fluctuating then falling estrogen.","differential":"Hyperthyroidism; premature ovarian insufficiency","management":"Discuss symptom management, hormonal and nonhormonal options, and contraception needs.","redflag":"Abnormal heavy bleeding warrants endometrial evaluation.","difficulty":1,"system":"Endo/Repro","id":"O296"},{"dx":"Congenital adrenal hyperplasia due to 21-hydroxylase deficiency","patient":"15F","chief":"Excess facial hair and irregular periods","opening":"An adolescent has increasing acne and facial hair.","history":"Early puberty symptoms, family history or salt-wasting childhood history.","exam":"Hirsutism, acne, possible virilization.","test":"Early morning 17-hydroxyprogesterone, ACTH stimulation if needed.","mechanism":"21-hydroxylase defect diverts steroid precursors toward androgens.","differential":"PCOS; androgen-secreting tumor","management":"Endocrinology care with tailored glucocorticoids and reproductive counseling.","redflag":"Severe classic disease may cause life-threatening salt-wasting crisis.","difficulty":3,"system":"Endo/Repro","id":"O297"},{"dx":"Androgen deficiency","patient":"56M","chief":"Reduced libido and fatigue","opening":"He reports lower sexual desire and reduced morning erections.","history":"Medication use, obesity, pituitary disease or testicular injury.","exam":"Reduced body hair, small testes or gynecomastia in some cases.","test":"Repeat morning total testosterone with LH/FSH and cause evaluation.","mechanism":"Low testosterone from primary testicular or hypothalamic-pituitary dysfunction.","differential":"Depression; erectile dysfunction from vascular disease","management":"Address cause and discuss replacement only if symptomatic confirmed deficiency.","redflag":"Check fertility plans and contraindications before testosterone therapy.","difficulty":2,"system":"Endo/Repro","id":"O298"},{"dx":"Erectile dysfunction with vascular risk","patient":"58M","chief":"Difficulty maintaining an erection","opening":"He has gradually increasing difficulty with erections.","history":"Diabetes, hypertension, smoking and preserved or absent nocturnal erections.","exam":"Vascular risk signs; targeted genital exam when needed.","test":"History, BP, A1c/lipids, testosterone only if indicated.","mechanism":"Endothelial and penile arterial dysfunction reduce erectile blood flow.","differential":"Hypogonadism; psychogenic ED","management":"Treat cardiometabolic risks, review medicines and offer PDE5 inhibitor if safe.","redflag":"Never combine PDE5 inhibitors with nitrates.","difficulty":2,"system":"Endo/Repro","id":"O299"},{"dx":"Ovarian hyperstimulation syndrome","patient":"30F","chief":"Abdominal bloating after fertility treatment","opening":"She develops abdominal swelling and breathlessness after egg retrieval.","history":"Recent gonadotropin treatment; rapid weight gain or reduced urine.","exam":"Ascites, tachycardia, possible pleural effusion.","test":"Electrolytes, hematocrit, renal function and pelvic ultrasound.","mechanism":"Excess VEGF-related vascular permeability shifts fluid into third spaces.","differential":"Ovarian torsion; ectopic pregnancy","management":"Urgent fertility/gynecology assessment and fluid/thrombotic risk management.","redflag":"Severe ascites, oliguria or thrombosis can be life-threatening.","difficulty":3,"system":"Endo/Repro","id":"O300"}];
